import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum TransactionType {
  INCOME = 'Thu',
  EXPENSE = 'Chi'
}

export enum PaymentSource {
  CASH = 'Tiền mặt',
  BANK = 'Tài khoản'
}

export interface Transaction {
  id: string;
  date: string;
  content: string;
  type: TransactionType;
  source: PaymentSource;
  amount: number;
}

export interface Settings {
  initialCash: number;
  initialBank: number;
  dailyCost: number;
}

export interface FinancialStats {
  currentCash: number;
  currentBank: number;
  total: number;
  survivalDays: number;
  totalIncome: number;
  totalExpense: number;
}

import { GoogleGenAI, Modality } from "@google/genai";
import { Transaction, Settings, FinancialStats } from "../types";

export class GeminiService {
  private ai: any;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async getFinancialAdvice(transactions: Transaction[], stats: FinancialStats, query: string) {
    const context = `
      Dữ liệu tài chính hiện tại:
      - Tiền mặt: ${stats.currentCash.toLocaleString()} VND
      - Tài khoản: ${stats.currentBank.toLocaleString()} VND
      - Tổng cộng: ${stats.total.toLocaleString()} VND
      - Khả năng duy trì: ${stats.survivalDays} ngày (dựa trên chi phí cố định)
      - Lịch sử giao dịch: ${JSON.stringify(transactions.slice(-10))}

      Hãy đóng vai một chuyên gia tư vấn tài chính. Trả lời câu hỏi của người dùng một cách ngắn gọn, súc tích và hữu ích.
    `;

    const response = await this.ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `${context}\n\nNgười dùng hỏi: ${query}`,
    });

    return response.text;
  }

  async speakText(text: string) {
    const response = await this.ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Đọc nội dung sau một cách tự nhiên bằng tiếng Việt: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            // "Kore" often sounds good for Asian languages if localized, 
            // but we'll stick to a standard one known for quality.
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });

    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64Audio) {
      await this.playAudioFromBase64(base64Audio);
    }
  }

  private async playAudioFromBase64(base64: string) {
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const bytes = this.decodeBase64(base64);
    const audioBuffer = await this.decodeAudioData(bytes, audioContext, 24000, 1);

    const source = audioContext.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(audioContext.destination);
    source.start();
  }

  private decodeBase64(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  private async decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  }
}

export const geminiService = new GeminiService();

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, TransactionType, PaymentSource, Settings, FinancialStats } from './types';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import AIChat from './components/AIChat';

const INITIAL_SETTINGS: Settings = {
  initialCash: 0,
  initialBank: 0,
  dailyCost: 0
};

const App: React.FC = () => {
  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('cashflow_settings');
    return saved ? JSON.parse(saved) : INITIAL_SETTINGS;
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('cashflow_transactions');
    return saved ? JSON.parse(saved) : [];
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'ai'>('dashboard');

  useEffect(() => {
    localStorage.setItem('cashflow_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('cashflow_transactions', JSON.stringify(transactions));
  }, [transactions]);

  const stats = useMemo((): FinancialStats => {
    const totalIncome = transactions
      .filter(t => t.type === TransactionType.INCOME)
      .reduce((sum, t) => sum + t.amount, 0);

    const totalExpense = transactions
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    const cashIncome = transactions
      .filter(t => t.type === TransactionType.INCOME && t.source === PaymentSource.CASH)
      .reduce((sum, t) => sum + t.amount, 0);

    const cashExpense = transactions
      .filter(t => t.type === TransactionType.EXPENSE && t.source === PaymentSource.CASH)
      .reduce((sum, t) => sum + t.amount, 0);

    const bankIncome = transactions
      .filter(t => t.type === TransactionType.INCOME && t.source === PaymentSource.BANK)
      .reduce((sum, t) => sum + t.amount, 0);

    const bankExpense = transactions
      .filter(t => t.type === TransactionType.EXPENSE && t.source === PaymentSource.BANK)
      .reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + cashIncome - cashExpense;
    const currentBank = settings.initialBank + bankIncome - bankExpense;
    const total = currentCash + currentBank;
    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    return {
      currentCash,
      currentBank,
      total,
      survivalDays,
      totalIncome,
      totalExpense
    };
  }, [transactions, settings]);

  const addTransaction = (t: Omit<Transaction, 'id'>) => {
    const newTransaction = { ...t, id: Date.now().toString() };
    setTransactions(prev => [newTransaction, ...prev]);
  };

  const deleteTransaction = (id: string) => {
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row">
      {/* Sidebar Navigation */}
      <nav className="w-full md:w-64 bg-indigo-900 text-white flex flex-col shadow-xl">
        <div className="p-6">
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <i className="fas fa-wallet text-yellow-400"></i>
            CashFlow
          </h1>
          <p className="text-indigo-300 text-sm">Master your money</p>
        </div>

        <div className="flex-1 px-4 space-y-2">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-indigo-700 shadow-lg' : 'hover:bg-indigo-800'}`}
          >
            <i className="fas fa-chart-line"></i> Dashboard
          </button>
          <button 
            onClick={() => setActiveTab('transactions')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'transactions' ? 'bg-indigo-700 shadow-lg' : 'hover:bg-indigo-800'}`}
          >
            <i className="fas fa-exchange-alt"></i> Giao dịch
          </button>
          <button 
            onClick={() => setActiveTab('ai')}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'ai' ? 'bg-indigo-700 shadow-lg' : 'hover:bg-indigo-800'}`}
          >
            <i className="fas fa-robot"></i> Trợ lý AI
          </button>
        </div>

        <div className="p-4 border-t border-indigo-800">
           <div className="bg-indigo-800/50 p-3 rounded-lg text-xs">
              <p className="opacity-70 mb-1">Duy trì được</p>
              <p className="text-lg font-bold text-yellow-400">{stats.survivalDays} ngày</p>
           </div>
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col overflow-hidden">
        {/* Header with Settings toggle */}
        <header className="h-16 bg-white border-b flex items-center justify-between px-8">
           <h2 className="text-lg font-semibold text-slate-700 uppercase tracking-wider">
             {activeTab === 'dashboard' && 'Tổng quan hệ thống'}
             {activeTab === 'transactions' && 'Lịch sử giao dịch'}
             {activeTab === 'ai' && 'Tư vấn tài chính AI'}
           </h2>

           <div className="flex items-center gap-4">
              <span className="text-sm text-slate-400 italic">Hôm nay: {new Date().toLocaleDateString('vi-VN')}</span>
           </div>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 bg-slate-50">
          {activeTab === 'dashboard' && (
            <div className="space-y-6 max-w-6xl mx-auto">
              {/* Settings Section */}
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 grid grid-cols-1 md:grid-cols-3 gap-6">
                <div>
                  <label className="block text-xs font-semibold text-slate-500 uppercase mb-2">Tiền mặt ban đầu (VND)</label>
                  <input 
                    type="number" 
                    value={settings.initialCash}
                    onChange={(e) => setSettings({ ...settings, initialCash: Number(e.target.value) })}
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 outline-none"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-500 uppercase mb-2">Tài khoản ban đầu (VND)</label>
                  <input 
                    type="number" 
                    value={settings.initialBank}
                    onChange={(e) => setSettings({ ...settings, initialBank: Number(e.target.value) })}
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 outline-none"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-500 uppercase mb-2">Chi phí/ngày (VND)</label>
                  <input 
                    type="number" 
                    value={settings.dailyCost}
                    onChange={(e) => setSettings({ ...settings, dailyCost: Number(e.target.value) })}
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 focus:ring-2 focus:ring-indigo-500 outline-none"
                  />
                </div>
              </div>

              <Dashboard stats={stats} transactions={transactions} />
            </div>
          )}

          {activeTab === 'transactions' && (
            <div className="space-y-6 max-w-6xl mx-auto">
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-1">
                  <TransactionForm onAdd={addTransaction} />
                </div>
                <div className="lg:col-span-2">
                  <TransactionList transactions={transactions} onDelete={deleteTransaction} />
                </div>
              </div>
            </div>
          )}

          {activeTab === 'ai' && (
            <div className="max-w-4xl mx-auto h-full pb-8">
              <AIChat transactions={transactions} stats={stats} />
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Transaction, TransactionType, PaymentSource } from '../types';

interface Props {
  onAdd: (t: Omit<Transaction, 'id'>) => void;
}

const TransactionForm: React.FC<Props> = ({ onAdd }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [content, setContent] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [source, setSource] = useState<PaymentSource>(PaymentSource.CASH);
  const [amount, setAmount] = useState<number>(0);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content || amount <= 0) return;

    onAdd({
      date,
      content,
      type,
      source,
      amount
    });

    setContent('');
    setAmount(0);
  };

  return (
    <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100">
      <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
         <i className="fas fa-plus-circle text-indigo-500"></i>
         Thêm giao dịch mới
      </h3>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">Ngày</label>
          <input 
            type="date" 
            value={date} 
            onChange={(e) => setDate(e.target.value)}
            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500"
          />
        </div>

        <div>
          <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">Nội dung</label>
          <input 
            type="text" 
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Ví dụ: Ăn trưa, Tiền lương..."
            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500"
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">Phân loại</label>
            <select 
              value={type} 
              onChange={(e) => setType(e.target.value as TransactionType)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value={TransactionType.INCOME}>Thu</option>
              <option value={TransactionType.EXPENSE}>Chi</option>
            </select>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">Nguồn tiền</label>
            <select 
              value={source} 
              onChange={(e) => setSource(e.target.value as PaymentSource)}
              className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500"
            >
              <option value={PaymentSource.CASH}>Tiền mặt</option>
              <option value={PaymentSource.BANK}>Tài khoản</option>
            </select>
          </div>
        </div>

        <div>
          <label className="block text-xs font-semibold text-slate-500 uppercase mb-1">Số tiền (VND)</label>
          <input 
            type="number" 
            value={amount}
            onChange={(e) => setAmount(Number(e.target.value))}
            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500 text-lg font-bold"
          />
        </div>

        <button 
          type="submit"
          className="w-full bg-indigo-600 text-white py-3 rounded-xl font-bold hover:bg-indigo-700 transition-colors shadow-lg active:scale-95"
        >
          Xác nhận giao dịch
        </button>
      </form>
    </div>
  );
};

export default TransactionForm;

import React from 'react';
import { Transaction, TransactionType, PaymentSource } from '../types';

interface Props {
  transactions: Transaction[];
  onDelete: (id: string) => void;
}

const TransactionList: React.FC<Props> = ({ transactions, onDelete }) => {
  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
      <div className="p-6 border-b border-slate-50 flex justify-between items-center">
        <h3 className="text-lg font-bold text-slate-800">Danh sách giao dịch</h3>
        <span className="text-xs text-slate-400">{transactions.length} giao dịch</span>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-slate-500 text-xs font-bold uppercase tracking-wider">
            <tr>
              <th className="px-6 py-4">Ngày</th>
              <th className="px-6 py-4">Nội dung</th>
              <th className="px-6 py-4 text-center">Loại</th>
              <th className="px-6 py-4 text-center">Nguồn</th>
              <th className="px-6 py-4 text-right">Số tiền</th>
              <th className="px-6 py-4"></th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 text-sm">
            {transactions.length === 0 ? (
               <tr>
                  <td colSpan={6} className="px-6 py-10 text-center text-slate-400">Chưa có giao dịch nào được ghi lại.</td>
               </tr>
            ) : (
              transactions.map((t) => (
                <tr key={t.id} className="hover:bg-slate-50 transition-colors group">
                  <td className="px-6 py-4 text-slate-500 font-medium">
                    {new Date(t.date).toLocaleDateString('vi-VN')}
                  </td>
                  <td className="px-6 py-4 font-semibold text-slate-700">
                    {t.content}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase ${t.type === TransactionType.INCOME ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                      {t.type}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-center">
                    <span className={`px-2 py-1 rounded-full text-[10px] font-bold uppercase ${t.source === PaymentSource.CASH ? 'bg-yellow-100 text-yellow-700' : 'bg-blue-100 text-blue-700'}`}>
                      {t.source}
                    </span>
                  </td>
                  <td className={`px-6 py-4 text-right font-bold ${t.type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'}`}>
                    {t.type === TransactionType.INCOME ? '+' : '-'}{t.amount.toLocaleString()} đ
                  </td>
                  <td className="px-6 py-4 text-right opacity-0 group-hover:opacity-100 transition-opacity">
                    <button 
                      onClick={() => onDelete(t.id)}
                      className="text-slate-300 hover:text-rose-500 transition-colors"
                    >
                      <i className="fas fa-trash-alt"></i>
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default TransactionList;

import React, { useState, useRef, useEffect } from 'react';
import { Transaction, FinancialStats } from '../types';
import { geminiService } from '../services/geminiService';

interface Message {
  role: 'user' | 'ai';
  text: string;
}

interface Props {
  transactions: Transaction[];
  stats: FinancialStats;
}

const AIChat: React.FC<Props> = ({ transactions, stats }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'ai', text: 'Xin chào! Tôi là trợ lý tài chính AI của bạn. Tôi có thể giúp bạn phân tích dòng tiền hoặc đưa ra lời khuyên tiết kiệm. Bạn muốn hỏi gì không?' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || loading) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setLoading(true);

    try {
      const response = await geminiService.getFinancialAdvice(transactions, stats, userMessage);
      setMessages(prev => [...prev, { role: 'ai', text: response }]);
    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, { role: 'ai', text: 'Rất tiếc, đã có lỗi xảy ra khi kết nối với bộ não của tôi.' }]);
    } finally {
      setLoading(false);
    }
  };

  const handleSpeak = async (text: string) => {
    if (isSpeaking) return;
    setIsSpeaking(true);
    try {
      await geminiService.speakText(text);
    } finally {
      setIsSpeaking(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
      <div className="p-4 bg-indigo-50 border-b border-indigo-100 flex items-center justify-between">
         <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-full flex items-center justify-center text-white shadow-md">
               <i className="fas fa-robot text-lg"></i>
            </div>
            <div>
               <h3 className="font-bold text-slate-800 text-sm">FinAssist AI</h3>
               <p className="text-[10px] text-emerald-600 font-bold animate-pulse">ĐANG TRỰC TUYẾN</p>
            </div>
         </div>
         <div className="text-xs text-slate-400 italic">Dựa trên Gemini 3 Pro</div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((m, i) => (
          <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-4 rounded-2xl relative group ${
              m.role === 'user' 
                ? 'bg-indigo-600 text-white rounded-tr-none' 
                : 'bg-slate-100 text-slate-700 rounded-tl-none'
            }`}>
              <p className="text-sm whitespace-pre-wrap">{m.text}</p>
              {m.role === 'ai' && (
                <button 
                  onClick={() => handleSpeak(m.text)}
                  disabled={isSpeaking}
                  className="absolute -right-10 top-2 text-indigo-400 hover:text-indigo-600 opacity-0 group-hover:opacity-100 transition-opacity"
                  title="Đọc văn bản"
                >
                  <i className={`fas ${isSpeaking ? 'fa-spinner fa-spin' : 'fa-volume-up'}`}></i>
                </button>
              )}
            </div>
          </div>
        ))}
        {loading && (
          <div className="flex justify-start">
             <div className="bg-slate-100 p-4 rounded-2xl rounded-tl-none flex gap-2">
