export const exportToCSV = (transactions: Transaction[]) => {
  if (transactions.length === 0) {
    alert("Không có dữ liệu để xuất!");
    return;
  }

  // Header row
  const headers = ["Ngày", "Nội dung", "Loại", "Nguồn", "Số tiền (VND)"];

  // Data rows
  const rows = transactions.map(t => [
    new Date(t.date).toLocaleDateString('vi-VN'),
    t.content.replace(/,/g, ' '), // Tránh lỗi dấu phẩy trong CSV
    t.type,
    t.source,
    t.amount
  ]);

  // Combine headers and rows
  const csvContent = [
    headers.join(","),
    ...rows.map(r => r.join(","))
  ].join("\n");

  // Create blob with UTF-8 BOM for Excel compatibility with Vietnamese characters
  const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);

  // Trigger download
  const link = document.createElement("a");
  link.setAttribute("href", url);
  link.setAttribute("download", `Sao_Ke_Tai_Chinh_${new Date().toISOString().split('T')[0]}.csv`);
  link.style.visibility = 'hidden';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

const CACHE_NAME = 'cashflow-v2';
const ASSETS = [
  '/',
  '/index.html',
  '/index.tsx',
  '/types.ts',
  '/manifest.json',
  'https://cdn.tailwindcss.com',
  'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css',
  'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap'
];

self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(ASSETS);
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

self.addEventListener('fetch', (event) => {
  // Ưu tiên trả về từ cache, nếu không có mới tải từ mạng
  event.respondWith(
    caches.match(event.request).then((response) => {
      return response || fetch(event.request).catch(() => {
        // Nếu offline và không có cache, trả về trang chính
        if (event.request.mode === 'navigate') {
          return caches.match('/index.html');
        }
      });
    })
  );
});

