export enum TransactionType {
  INCOME = 'Thu',
  EXPENSE = 'Chi'
}

export enum PaymentSource {
  CASH = 'Tiền mặt',
  BANK = 'Tài khoản'
}

export interface Transaction {
  id: string;
  date: string;
  content: string;
  type: TransactionType;
  source: PaymentSource;
  amount: number;
}

export interface Settings {
  initialCash: number;
  initialBank: number;
  dailyCost: number;
}

export interface FinancialStats {
  currentCash: number;
  currentBank: number;
  total: number;
  survivalDays: number;
  totalIncome: number;
  totalExpense: number;
}

import { Transaction } from "../types";

export const exportToCSV = (transactions: Transaction[]) => {
  if (transactions.length === 0) return alert("Không có dữ liệu!");

  const headers = ["Ngày", "Nội dung", "Loại", "Nguồn", "Số tiền (VND)"];
  const rows = transactions.map(t => [
    new Date(t.date).toLocaleDateString('vi-VN'),
    t.content.replace(/,/g, ' '),
    t.type,
    t.source,
    t.amount
  ]);

  const csvContent = [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
  const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);

  const link = document.createElement("a");
  link.href = url;
  link.download = `SaoKe_CashFlow_${new Date().toISOString().split('T')[0]}.csv`;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

import { GoogleGenAI, Modality } from "@google/genai";
import { Transaction, FinancialStats } from "../types";

export class GeminiService {
  private ai: any;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async getFinancialAdvice(transactions: Transaction[], stats: FinancialStats, query: string) {
    const context = `
      Tài chính: Mặt: ${stats.currentCash}đ, Bank: ${stats.currentBank}đ. 
      Sống được: ${stats.survivalDays} ngày.
      Lịch sử: ${JSON.stringify(transactions.slice(0, 5))}
      Hãy tư vấn tài chính ngắn gọn (dưới 50 từ).
    `;
    const response = await this.ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: `${context}\n\nCâu hỏi: ${query}`,
    });
    return response.text;
  }

  async speakText(text: string) {
    const response = await this.ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Đọc: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
      },
    });
    const base64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (base64) await this.playAudio(base64);
  }

  private async playAudio(base64: string) {
    const ctx = new AudioContext();
    const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
    const dataInt16 = new Int16Array(bytes.buffer);
    const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.start();
  }
}
export const geminiService = new GeminiService();

