import { GoogleGenAI, Modality, Chat, GenerateContentResponse } from "@google/genai";
import { Transaction, FinancialStats } from "../types";

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  private chatSession: Chat | null = null;

  initChat(transactions: Transaction[], stats: FinancialStats) {
    const ai = this.getAI();
    const context = `
      Bạn là FinAssist - Chuyên gia tư vấn tài chính cá nhân thông minh.
      Dữ liệu người dùng hiện tại:
      - Tiền mặt: ${stats.currentCash.toLocaleString()} VND
      - Tài khoản: ${stats.currentBank.toLocaleString()} VND
      - Tổng cộng: ${stats.total.toLocaleString()} VND
      - Chi phí sống mỗi ngày dự kiến: ${stats.survivalDays > 0 ? (stats.total / stats.survivalDays).toLocaleString() : 'Chưa thiết lập'} VND
      - Khả năng duy trì: ${stats.survivalDays} ngày.
      - 5 giao dịch gần nhất: ${JSON.stringify(transactions.slice(0, 5))}

      Nhiệm vụ: 
      1. Phân tích xu hướng chi tiêu.
      2. Đưa ra lời khuyên tiết kiệm thực tế.
      3. Trả lời bằng tiếng Việt, giọng điệu chuyên nghiệp, thân thiện và ngắn gọn.
      4. Luôn ưu tiên an toàn tài chính.
    `;

    this.chatSession = ai.chats.create({
      model: 'gemini-3-pro-preview',
      config: {
        systemInstruction: context,
        temperature: 0.7,
      },
    });
  }

  async *askAIStream(query: string) {
    if (!this.chatSession) throw new Error("Chat chưa được khởi tạo");

    const result = await this.chatSession.sendMessageStream({ message: query });
    for await (const chunk of result) {
      const c = chunk as GenerateContentResponse;
      yield c.text;
    }
  }

  async speakText(text: string) {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Đọc nội dung này bằng tiếng Việt một cách tự nhiên: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Puck' }, // Giọng nam trầm ấm, chuyên nghiệp
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (base64Audio) {
        await this.playAudioFromBase64(base64Audio);
      }
    } catch (error) {
      console.error("TTS Error:", error);
    }
  }

  private async playAudioFromBase64(base64: string) {
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    const bytes = this.decode(base64);
    const audioBuffer = await this.decodeAudioData(bytes, audioContext, 24000, 1);

    const source = audioContext.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(audioContext.destination);
    source.start();
  }

  private decode(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  private async decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  }
}

