const App: React.FC = () => {
  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('cashflow_settings');
    return saved ? JSON.parse(saved) : { initialCash: 0, initialBank: 0, dailyCost: 0 };
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('cashflow_transactions');
    return saved ? JSON.parse(saved) : [];
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'ai'>('dashboard');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  useEffect(() => {
    localStorage.setItem('cashflow_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('cashflow_transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    const updateOnlineStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);
    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
    };
  }, []);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;
    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    // LOGIC KHOẢN NHO NHỎ TÍCH LŨY
    let cumulativeSaving = 0;
    if (transactions.length > 0 && settings.dailyCost > 0) {
      // Tìm ngày sớm nhất có giao dịch
      const dates = transactions.map(t => new Date(t.date).getTime());
      const startDate = new Date(Math.min(...dates));
      const today = new Date();

      // Tính số ngày đã trôi qua (bao gồm cả ngày hiện tại)
      const diffTime = Math.abs(today.getTime() - startDate.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) || 1;

      const totalBudget = diffDays * settings.dailyCost;
      const totalSpent = transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .reduce((sum, t) => sum + t.amount, 0);

      cumulativeSaving = totalBudget - totalSpent;
    }

    return {
      currentCash, currentBank, total, survivalDays,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense,
      cumulativeSaving
    };
  }, [transactions, settings]);

  const handleAddTransaction = (t: Omit<Transaction, 'id'>) => {
    setTransactions([{...t, id: Date.now().toString()}, ...transactions]);
    if (activeTab !== 'transactions') setActiveTab('transactions');
  };

  const handleUpdateTransaction = (updated: Transaction) => {
    setTransactions(transactions.map(t => t.id === updated.id ? updated : t));
    setEditingTransaction(null);
  };

  const handleDeleteTransaction = (id: string) => {
    if (window.confirm('Xóa giao dịch này khỏi hệ thống?')) {
      setTransactions(transactions.filter(t => t.id !== id));
      if (editingTransaction?.id === id) setEditingTransaction(null);
    }
  };

  const handleResetData = () => {
    if (window.confirm('CẢNH BÁO: Hành động này sẽ xóa toàn bộ lịch sử giao dịch và thiết lập ban đầu. Bạn có chắc chắn?')) {
      setTransactions([]);
      setSettings({ initialCash: 0, initialBank: 0, dailyCost: 0 });
      localStorage.clear();
      window.location.reload();
    }
  };

  return (
    <div className="h-screen flex flex-col bg-slate-50 overflow-hidden font-sans">
      <header className="flex-none h-16 bg-white border-b border-slate-100 flex items-center justify-between px-5 sticky top-0 z-50 glass-effect">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-200">
            <i className="fas fa-wallet text-white text-sm"></i>
          </div>
          <h1 className="text-lg font-black tracking-tight text-slate-800">
            CASH<span className="text-indigo-600">FLOW</span>
          </h1>
        </div>

        <div className="flex items-center gap-3">
          {!isOnline && (
            <div className="flex items-center gap-1.5 bg-rose-50 text-rose-600 px-2.5 py-1 rounded-full text-[10px] font-black border border-rose-100 animate-pulse">
              <i className="fas fa-plane"></i> OFFLINE
            </div>
          )}
          <button 
            onClick={() => exportToCSV(transactions, settings)} 
            className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all active-scale"
            title="Xuất dữ liệu"
          >
            <i className="fas fa-file-export"></i>
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-5 pb-24 scroll-smooth">
        {activeTab === 'dashboard' && (
          <div className="max-w-xl mx-auto space-y-5">
             <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100">
                <div className="flex justify-between items-center mb-4">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Thiết lập nguồn vốn & Mục tiêu</p>
                  <button onClick={handleResetData} className="text-[10px] text-rose-400 font-bold hover:text-rose-600">LÀM MỚI</button>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] text-slate-400 font-bold ml-1">VỐN TIỀN MẶT</label>
                    <input type="number" placeholder="0" value={settings.initialCash || ''} onChange={e => setSettings({...settings, initialCash: +e.target.value})} className="w-full bg-slate-50 p-3 rounded-2xl text-sm font-bold outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] text-slate-400 font-bold ml-1">VỐN TÀI KHOẢN</label>
                    <input type="number" placeholder="0" value={settings.initialBank || ''} onChange={e => setSettings({...settings, initialBank: +e.target.value})} className="w-full bg-slate-50 p-3 rounded-2xl text-sm font-bold outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                  </div>
                  <div className="col-span-2 space-y-1">
                    <label className="text-[10px] text-slate-400 font-bold ml-1 flex justify-between">
                      <span>MỤC TIÊU CHI TIÊU / NGÀY</span>
                      <span className="text-indigo-500">{settings.dailyCost.toLocaleString()}đ</span>
                    </label>
                    <input type="number" placeholder="Ví dụ: 80000" value={settings.dailyCost || ''} onChange={e => setSettings({...settings, dailyCost: +e.target.value})} className="w-full bg-indigo-50/50 p-3.5 rounded-2xl text-base font-black text-indigo-700 outline-none border border-indigo-100 focus:bg-white transition-all"/>
                  </div>
                </div>
             </div>
             <Dashboard stats={stats} transactions={transactions} settings={settings} />
          </div>
        )}

        {activeTab === 'transactions' && (
          <div className="max-w-xl mx-auto space-y-5">
            <TransactionForm 
              onAdd={handleAddTransaction} 
              editingTransaction={editingTransaction}
              onUpdate={handleUpdateTransaction}
              onCancelEdit={() => setEditingTransaction(null)}
            />
            <TransactionList 
              transactions={transactions} 
              settings={settings}
              onDelete={handleDeleteTransaction}
              onEdit={(t) => {
                setEditingTransaction(t);
                window.scrollTo({ top: 0, behavior: 'smooth' });
              }}
            />
          </div>
        )}

        {activeTab === 'ai' && (
          <div className="h-full max-w-xl mx-auto">
            {isOnline ? (
              <AIChat 
                transactions={transactions} 
                stats={stats} 
                onAddTransaction={handleAddTransaction} 
              />
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-center p-12 space-y-6">
                <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center">
                  <i className="fas fa-wifi-slash text-4xl text-slate-300"></i>
                </div>
                <div>
                  <h3 className="font-black text-xl text-slate-800">Cần kết nối mạng</h3>
                  <p className="text-sm text-slate-500 mt-2 leading-relaxed">Tính năng trợ lý AI yêu cầu Internet để xử lý giọng nói và tư vấn tài chính.</p>
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 inset-x-0 h-20 bg-white border-t border-slate-100 flex justify-around items-center px-6 pb-4 glass-effect shadow-[0_-10px_25px_rgba(0,0,0,0.03)]">
        {[
          { id: 'dashboard', icon: 'fa-chart-pie', label: 'Dashboard' },
          { id: 'transactions', icon: 'fa-exchange-alt', label: 'Giao dịch' },
          { id: 'ai', icon: 'fa-magic', label: 'FinAI' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex flex-col items-center gap-1.5 transition-all duration-300 relative ${
              activeTab === tab.id 
                ? 'text-indigo-600 scale-110' 
                : 'text-slate-400'
            }`}
          >
            {activeTab === tab.id && (
              <span className="absolute -top-3 w-1.5 h-1.5 bg-indigo-600 rounded-full"></span>
            )}
            <i className={`fas ${tab.icon} text-xl`}></i>
            <span className="text-[10px] font-black uppercase tracking-tighter">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { ComposedChart, Area, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Line, ReferenceLine } from 'recharts';
import { FinancialStats, Transaction, TransactionType, Settings } from '../types';

interface Props {
  stats: FinancialStats;
  transactions: Transaction[];
  settings: Settings;
}

const Dashboard: React.FC<Props> = ({ stats, transactions, settings }) => {
  const chartData = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      days.push(d.toISOString().split('T')[0]);
    }

    return days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const expense = dayTransactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .reduce((sum, t) => sum + t.amount, 0);
      const income = dayTransactions
        .filter(t => t.type === TransactionType.INCOME)
        .reduce((sum, t) => sum + t.amount, 0);

      return {
        date: date.split('-').slice(1).reverse().join('/'),
        expense,
        income,
        target: settings.dailyCost,
        saving: settings.dailyCost - expense
      };
    });
  }, [transactions, settings.dailyCost]);

  const formatCurrency = (val: number) => val.toLocaleString('vi-VN') + 'đ';

  const savingAdvice = () => {
    if (settings.dailyCost === 0) return "Hãy đặt mục tiêu chi tiêu/ngày để kích hoạt 'Khoản Nho Nhỏ'!";
    if (stats.cumulativeSaving > 0) return "Tổng tích lũy đang dương. Bạn đang làm rất tốt việc quản lý kỷ luật! 🚀";
    if (stats.cumulativeSaving === 0) return "Bạn đang tiêu đúng mức cho phép. Hãy cố gắng tiết kiệm thêm chút nhé! ⚖️";
    return "CẢNH BÁO: Tổng chi tiêu của bạn đã vượt quá hạn mức tích lũy. Cần thắt lưng buộc bụng ngay! 🛑";
  };

  return (
    <div className="space-y-5 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* KHOẢN NHO NHỎ CARD (TÍCH LŨY) */}
      <div className={`p-6 rounded-3xl shadow-xl border-2 transition-all duration-500 relative overflow-hidden ${
        stats.cumulativeSaving >= 0 
          ? 'bg-emerald-50 border-emerald-200 shadow-emerald-100/50' 
          : 'bg-rose-50 border-rose-300 shadow-rose-100/50 animate-shake'
      }`}>
        <div className="flex justify-between items-start z-10 relative">
          <div>
            <p className={`text-[11px] font-black uppercase tracking-widest ${stats.cumulativeSaving >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
              KHOẢN NHO NHỎ (TỔNG TÍCH LŨY)
            </p>
            <h2 className={`text-4xl font-black mt-1 ${stats.cumulativeSaving >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
              {stats.cumulativeSaving > 0 ? '+' : ''}{formatCurrency(stats.cumulativeSaving)}
            </h2>
          </div>
          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl shadow-lg ${
            stats.cumulativeSaving >= 0 ? 'bg-emerald-500 text-white shadow-emerald-200' : 'bg-rose-500 text-white shadow-rose-200'
          }`}>
            <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-piggy-bank' : 'fa-skull-crossbones'}`}></i>
          </div>
        </div>
        <div className="mt-4 flex items-center gap-2 z-10 relative">
           <div className="flex-1 h-1.5 bg-black/5 rounded-full overflow-hidden">
              <div 
                className={`h-full transition-all duration-1000 ${stats.cumulativeSaving >= 0 ? 'bg-emerald-500' : 'bg-rose-500'}`}
                style={{ width: `${Math.min(100, Math.max(10, (stats.cumulativeSaving / (settings.dailyCost * 30 || 1)) * 100))}%` }}
              ></div>
           </div>
           <span className={`text-[10px] font-black ${stats.cumulativeSaving >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
              KỶ LUẬT
           </span>
        </div>
        <p className={`text-[11px] font-bold mt-4 leading-relaxed z-10 relative ${stats.cumulativeSaving >= 0 ? 'text-emerald-600/80' : 'text-rose-600/80'}`}>
          {savingAdvice()}
        </p>

        {/* Background icon decoration */}
        <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-chart-line' : 'fa-exclamation-triangle'} absolute -right-4 -bottom-4 text-8xl opacity-5`}></i>
      </div>

      {/* CSS For Shake Animation */}
      <style>{`
        @keyframes shake {
          0% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          50% { transform: translateX(4px); }
          75% { transform: translateX(-4px); }
          100% { transform: translateX(0); }
        }
        .animate-shake {
          animation: shake 0.5s cubic-bezier(.36,.07,.19,.97) both;
          animation-iteration-count: 2;
        }
      `}</style>

      {/* Metric Cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden h-28 flex flex-col justify-center">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest z-10">Tiền mặt hiện có</p>
          <p className="text-xl font-black text-slate-800 mt-1 z-10">{formatCurrency(stats.currentCash)}</p>
          <i className="fas fa-wallet absolute -right-3 -bottom-3 text-5xl text-slate-50 opacity-50 transform rotate-12"></i>
        </div>

        <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden h-28 flex flex-col justify-center">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest z-10">Trong tài khoản</p>
          <p className="text-xl font-black text-slate-800 mt-1 z-10">{formatCurrency(stats.currentBank)}</p>
          <i className="fas fa-credit-card absolute -right-3 -bottom-3 text-5xl text-slate-50 opacity-50 transform -rotate-12"></i>
        </div>

        <div className="col-span-2 bg-gradient-to-br from-slate-800 to-slate-900 p-6 rounded-3xl shadow-xl text-white relative overflow-hidden">
          <div className="z-10 relative">
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Tổng tài sản ròng</p>
            <p className="text-4xl font-black mt-1 tracking-tighter">{formatCurrency(stats.total)}</p>
            <div className="mt-4 flex items-center gap-6">
               <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-500 uppercase tracking-tighter">Sinh tồn dự kiến</span>
                  <span className="text-lg font-black text-indigo-400">{stats.survivalDays} <span className="text-[10px] text-white/50">Ngày</span></span>
               </div>
               <div className="w-[1px] h-8 bg-white/10"></div>
               <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-500 uppercase tracking-tighter">Chi tiêu hôm nay</span>
                  <span className="text-lg font-black text-rose-400">{formatCurrency(stats.todayExpense)}</span>
               </div>
            </div>
          </div>
          <i className="fas fa-shield-alt absolute -right-6 -bottom-6 text-[120px] text-white/5 pointer-events-none"></i>
        </div>
      </div>

      {/* Biểu đồ: Chi tiêu vs Hạn mức */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
        <div className="flex justify-between items-center mb-6">
          <div>
            <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
              <i className="fas fa-history text-indigo-500"></i> Lịch sử kỷ luật
            </h3>
            <p className="text-[9px] text-slate-400 font-bold mt-0.5">7 ngày gần nhất</p>
          </div>
          <div className="flex items-center gap-3">
             <div className="flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-rose-500"></span>
                <span className="text-[9px] font-bold text-slate-400">CHI</span>
             </div>
             <div className="flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-indigo-200"></span>
                <span className="text-[9px] font-bold text-slate-400">HẠN MỨC</span>
             </div>
          </div>
        </div>
        <div className="h-56 w-full">
          {transactions.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fontSize: 9, fill: '#94a3b8', fontWeight: 700}} dy={10} />
                <YAxis hide domain={[0, 'auto']} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', fontSize: '10px', fontWeight: 700 }}
                  formatter={(value: number) => [formatCurrency(value), '']}
                />
                <Area type="monotone" dataKey="target" fill="#f5f3ff" stroke="none" fillOpacity={1} />
                <Bar dataKey="expense" fill="#f43f5e" radius={[4, 4, 0, 0]} barSize={12} />
                <Line type="monotone" dataKey="target" stroke="#818cf8" strokeWidth={2} strokeDasharray="5 5" dot={false} />
                <ReferenceLine y={0} stroke="#000" />
              </ComposedChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-2">
               <i className="fas fa-chart-bar text-3xl opacity-20"></i>
               <p className="text-[10px] font-bold uppercase tracking-widest">Ghi chép để phân tích kỷ luật</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, TransactionType, PaymentSource, Settings, FinancialStats } from './types';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import AIChat from './components/AIChat';
import { exportToCSV } from './services/exportService';

const App: React.FC = () => {
  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('cashflow_settings');
    return saved ? JSON.parse(saved) : { initialCash: 0, initialBank: 0, dailyCost: 0 };
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('cashflow_transactions');
    return saved ? JSON.parse(saved) : [];
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'ai'>('dashboard');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  useEffect(() => {
    localStorage.setItem('cashflow_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('cashflow_transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    const updateOnlineStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);
    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
    };
  }, []);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;
    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    // CHÍNH XÁC HÓA LOGIC KHOẢN NHO NHỎ TÍCH LŨY
    let cumulativeSaving = 0;
    if (transactions.length > 0 && settings.dailyCost > 0) {
      // 1. Tìm ngày đầu tiên có giao dịch
      const startDateStr = transactions.reduce((min, t) => t.date < min ? t.date : min, transactions[0].date);
      const start = new Date(startDateStr);
      const today = new Date();

      // 2. Tính số ngày lịch (calendar days) bao gồm cả ngày hiện tại
      const s = Date.UTC(start.getFullYear(), start.getMonth(), start.getDate());
      const e = Date.UTC(today.getFullYear(), today.getMonth(), today.getDate());
      const diffDays = Math.floor((e - s) / (1000 * 60 * 60 * 24)) + 1;

      // 3. (Số ngày * Hạn mức/ngày) - Tổng chi thực tế
      const totalBudget = diffDays * settings.dailyCost;
      const totalSpent = transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .reduce((sum, t) => sum + t.amount, 0);

      cumulativeSaving = totalBudget - totalSpent;
    }

    return {
      currentCash, currentBank, total, survivalDays,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense,
      cumulativeSaving
    };
  }, [transactions, settings]);

  const handleAddTransaction = (t: Omit<Transaction, 'id'>) => {
    setTransactions([{...t, id: Date.now().toString()}, ...transactions]);
    if (activeTab !== 'transactions') setActiveTab('transactions');
  };

  const handleUpdateTransaction = (updated: Transaction) => {
    setTransactions(transactions.map(t => t.id === updated.id ? updated : t));
    setEditingTransaction(null);
  };

  const handleDeleteTransaction = (id: string) => {
    if (window.confirm('Xóa giao dịch này khỏi hệ thống?')) {
      setTransactions(transactions.filter(t => t.id !== id));
      if (editingTransaction?.id === id) setEditingTransaction(null);
    }
  };

  const handleResetData = () => {
    if (window.confirm('CẢNH BÁO: Hành động này sẽ xóa toàn bộ lịch sử giao dịch và thiết lập ban đầu. Bạn có chắc chắn?')) {
      setTransactions([]);
      setSettings({ initialCash: 0, initialBank: 0, dailyCost: 0 });
      localStorage.clear();
      window.location.reload();
    }
  };

  return (
    <div className="h-screen flex flex-col bg-slate-50 overflow-hidden font-sans">
      <header className="flex-none h-16 bg-white border-b border-slate-100 flex items-center justify-between px-5 sticky top-0 z-50 glass-effect">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-200">
            <i className="fas fa-wallet text-white text-sm"></i>
          </div>
          <h1 className="text-lg font-black tracking-tight text-slate-800">
            CASH<span className="text-indigo-600">FLOW</span>
          </h1>
        </div>

        <div className="flex items-center gap-3">
          {!isOnline && (
            <div className="flex items-center gap-1.5 bg-rose-50 text-rose-600 px-2.5 py-1 rounded-full text-[10px] font-black border border-rose-100 animate-pulse">
              <i className="fas fa-plane"></i> OFFLINE
            </div>
          )}
          <button 
            onClick={() => exportToCSV(transactions, settings)} 
            className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all active-scale"
            title="Xuất dữ liệu"
          >
            <i className="fas fa-file-export"></i>
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 space-y-5 pb-24 scroll-smooth">
        {activeTab === 'dashboard' && (
          <div className="max-w-xl mx-auto space-y-5">
             <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100">
                <div className="flex justify-between items-center mb-4">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Cấu hình mục tiêu</p>
                  <button onClick={handleResetData} className="text-[10px] text-rose-400 font-bold hover:text-rose-600">LÀM MỚI</button>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] text-slate-400 font-bold ml-1">VỐN TIỀN MẶT</label>
                    <input type="number" placeholder="0" value={settings.initialCash || ''} onChange={e => setSettings({...settings, initialCash: +e.target.value})} className="w-full bg-slate-50 p-3 rounded-2xl text-sm font-bold outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] text-slate-400 font-bold ml-1">VỐN TÀI KHOẢN</label>
                    <input type="number" placeholder="0" value={settings.initialBank || ''} onChange={e => setSettings({...settings, initialBank: +e.target.value})} className="w-full bg-slate-50 p-3 rounded-2xl text-sm font-bold outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                  </div>
                  <div className="col-span-2 space-y-1">
                    <label className="text-[10px] text-slate-400 font-bold ml-1 flex justify-between">
                      <span>SINH HOẠT MỤC TIÊU / NGÀY</span>
                      <span className="text-indigo-500">{settings.dailyCost.toLocaleString()}đ</span>
                    </label>
                    <input type="number" placeholder="Ví dụ: 80000" value={settings.dailyCost || ''} onChange={e => setSettings({...settings, dailyCost: +e.target.value})} className="w-full bg-indigo-50/50 p-3.5 rounded-2xl text-base font-black text-indigo-700 outline-none border border-indigo-100 focus:bg-white transition-all"/>
                  </div>
                </div>
             </div>
             <Dashboard stats={stats} transactions={transactions} settings={settings} />
          </div>
        )}

        {activeTab === 'transactions' && (
          <div className="max-w-xl mx-auto space-y-5">
            <TransactionForm 
              onAdd={handleAddTransaction} 
              editingTransaction={editingTransaction}
              onUpdate={handleUpdateTransaction}
              onCancelEdit={() => setEditingTransaction(null)}
            />
            <TransactionList 
              transactions={transactions} 
              settings={settings}
              onDelete={handleDeleteTransaction}
              onEdit={(t) => {
                setEditingTransaction(t);
                window.scrollTo({ top: 0, behavior: 'smooth' });
              }}
            />
          </div>
        )}

        {activeTab === 'ai' && (
          <div className="h-full max-w-xl mx-auto">
            {isOnline ? (
              <AIChat 
                transactions={transactions} 
                stats={stats} 
                onAddTransaction={handleAddTransaction} 
              />
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-center p-12 space-y-6">
                <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center">
                  <i className="fas fa-wifi-slash text-4xl text-slate-300"></i>
                </div>
                <div>
                  <h3 className="font-black text-xl text-slate-800">Cần kết nối mạng</h3>
                  <p className="text-sm text-slate-500 mt-2 leading-relaxed">Tính năng trợ lý AI yêu cầu Internet để xử lý giọng nói và tư vấn tài chính.</p>
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      <nav className="fixed bottom-0 inset-x-0 h-20 bg-white border-t border-slate-100 flex justify-around items-center px-6 pb-4 glass-effect shadow-[0_-10px_25px_rgba(0,0,0,0.03)]">
        {[
          { id: 'dashboard', icon: 'fa-chart-pie', label: 'Dashboard' },
          { id: 'transactions', icon: 'fa-exchange-alt', label: 'Giao dịch' },
          { id: 'ai', icon: 'fa-magic', label: 'FinAI' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex flex-col items-center gap-1.5 transition-all duration-300 relative ${
              activeTab === tab.id 
                ? 'text-indigo-600 scale-110' 
                : 'text-slate-400'
            }`}
          >
            {activeTab === tab.id && (
              <span className="absolute -top-3 w-1.5 h-1.5 bg-indigo-600 rounded-full"></span>
            )}
            <i className={`fas ${tab.icon} text-xl`}></i>
            <span className="text-[10px] font-black uppercase tracking-tighter">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
