            <h2 className={`text-4xl font-black mt-1 ${stats.cumulativeSaving >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
              {stats.cumulativeSaving > 0 ? '+' : ''}{formatCurrency(stats.cumulativeSaving)}
            </h2>
            <div className={`mt-2 inline-flex items-center gap-1.5 px-2 py-1 rounded-lg text-[10px] font-black border ${
              todaySaving >= 0 
                ? 'bg-emerald-500/10 text-emerald-600 border-emerald-500/20' 
                : 'bg-rose-500/10 text-rose-600 border-rose-500/20'
            }`}>
               <i className={`fas ${todaySaving >= 0 ? 'fa-caret-up' : 'fa-caret-down'}`}></i>
               Hôm nay: {todaySaving > 0 ? '+' : ''}{formatCurrency(todaySaving)}
            </div>
          </div>
          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl shadow-lg ${
            stats.cumulativeSaving >= 0 ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white shadow-rose-200'
          }`}>
            <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-piggy-bank' : 'fa-skull-crossbones'}`}></i>
          </div>
        </div>

        <p className={`text-[11px] font-bold mt-5 leading-relaxed z-10 relative ${stats.cumulativeSaving >= 0 ? 'text-emerald-600/80' : 'text-rose-600/80'}`}>
          {savingAdvice()}
        </p>

        <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-coins' : 'fa-exclamation-triangle'} absolute -right-4 -bottom-4 text-8xl opacity-5`}></i>
      </div>

      <style>{`
        @keyframes shake {
          0% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          50% { transform: translateX(4px); }
          75% { transform: translateX(-4px); }
          100% { transform: translateX(0); }
        }
        .animate-shake {
          animation: shake 0.5s cubic-bezier(.36,.07,.19,.97) both;
          animation-iteration-count: 2;
        }
      `}</style>

      {/* Metric Cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden h-28 flex flex-col justify-center">
