                  <span className="text-lg font-black text-rose-400">{formatCurrency(stats.todayExpense)}</span>
               </div>
            </div>
          </div>
          <i className="fas fa-shield-alt absolute -right-6 -bottom-6 text-[120px] text-white/5 pointer-events-none"></i>
