import React, { useMemo } from 'react';
import { ComposedChart, Area, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Line, ReferenceLine } from 'recharts';
import { FinancialStats, Transaction, TransactionType, Settings } from '../types';

interface Props {
  stats: FinancialStats;
  transactions: Transaction[];
  settings: Settings;
}

const Dashboard: React.FC<Props> = ({ stats, transactions, settings }) => {
  const chartData = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      days.push(d.toISOString().split('T')[0]);
    }

    return days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const expense = dayTransactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .reduce((sum, t) => sum + t.amount, 0);
      const income = dayTransactions
        .filter(t => t.type === TransactionType.INCOME)
        .reduce((sum, t) => sum + t.amount, 0);

      return {
        date: date.split('-').slice(1).reverse().join('/'),
        expense,
        income,
        target: settings.dailyCost,
        saving: settings.dailyCost - expense
      };
    });
  }, [transactions, settings.dailyCost]);

  const formatCurrency = (val: number) => val.toLocaleString('vi-VN') + 'đ';

  const todaySaving = settings.dailyCost - stats.todayExpense;

  const savingAdvice = () => {
    if (settings.dailyCost === 0) return "Hãy thiết lập mục tiêu chi tiêu mỗi ngày!";
    if (stats.cumulativeSaving > 0) return "Bạn đang quản lý kỷ luật cực tốt! Tổng tích lũy vẫn dương. 🚀";
    if (stats.cumulativeSaving === 0) return "Hết ngân sách tích lũy! Đừng tiêu thêm nhé. ⚖️";
    return "NGUY HIỂM: Bạn đang chi vượt hạn mức cộng dồn. Cần thắt chặt chi tiêu! 🛑";
  };

  return (
    <div className="space-y-5 animate-in fade-in slide-in-from-bottom-4 duration-500">

      {/* KHOẢN NHO NHỎ CARD (LOGIC CỘNG DỒN) */}
      <div className={`p-6 rounded-3xl shadow-xl border-2 transition-all duration-500 relative overflow-hidden ${
        stats.cumulativeSaving >= 0 
          ? 'bg-emerald-50 border-emerald-200 shadow-emerald-100/30' 
          : 'bg-rose-50 border-rose-300 shadow-rose-100/30 animate-shake'
      }`}>
        <div className="flex justify-between items-start z-10 relative">
          <div>
            <p className={`text-[10px] font-black uppercase tracking-widest ${stats.cumulativeSaving >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
              Khoản Nho Nhỏ (Tích lũy)
            </p>
            <h2 className={`text-4xl font-black mt-1 ${stats.cumulativeSaving >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
              {stats.cumulativeSaving > 0 ? '+' : ''}{formatCurrency(stats.cumulativeSaving)}
            </h2>
            <div className={`mt-3 inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-black border ${
              todaySaving >= 0 
                ? 'bg-emerald-500 text-white border-transparent' 
                : 'bg-rose-500 text-white border-transparent'
            }`}>
               <i className={`fas ${todaySaving >= 0 ? 'fa-plus-circle' : 'fa-minus-circle'}`}></i>
               Hôm nay: {todaySaving > 0 ? '+' : ''}{formatCurrency(todaySaving)}
            </div>
          </div>
          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-2xl shadow-lg transition-transform duration-500 ${
            stats.cumulativeSaving >= 0 ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white scale-110'
          }`}>
            <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-piggy-bank' : 'fa-triangle-exclamation'}`}></i>
          </div>
        </div>

        <p className={`text-[11px] font-bold mt-5 leading-relaxed z-10 relative ${stats.cumulativeSaving >= 0 ? 'text-emerald-600/80' : 'text-rose-600/80'}`}>
          {savingAdvice()}
        </p>

        <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-chart-area' : 'fa-fire'} absolute -right-4 -bottom-4 text-8xl opacity-5`}></i>
      </div>

      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          20% { transform: translateX(-5px); }
          40% { transform: translateX(5px); }
          60% { transform: translateX(-5px); }
          80% { transform: translateX(5px); }
        }
        .animate-shake {
          animation: shake 0.5s ease-in-out infinite;
          animation-iteration-count: 2;
        }
      `}</style>

      {/* Metric Cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden h-28 flex flex-col justify-center">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest z-10">Vốn Tiền mặt</p>
          <p className="text-xl font-black text-slate-800 mt-1 z-10">{formatCurrency(stats.currentCash)}</p>
          <i className="fas fa-wallet absolute -right-3 -bottom-3 text-5xl text-slate-50 opacity-40 transform rotate-12"></i>
        </div>

        <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden h-28 flex flex-col justify-center">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest z-10">Trong Tài khoản</p>
          <p className="text-xl font-black text-slate-800 mt-1 z-10">{formatCurrency(stats.currentBank)}</p>
          <i className="fas fa-credit-card absolute -right-3 -bottom-3 text-5xl text-slate-50 opacity-40 transform -rotate-12"></i>
        </div>

        <div className="col-span-2 bg-slate-900 p-6 rounded-3xl shadow-xl text-white relative overflow-hidden">
          <div className="z-10 relative">
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Tài sản ròng hiện có</p>
            <p className="text-4xl font-black mt-1 tracking-tighter">{formatCurrency(stats.total)}</p>
            <div className="mt-5 flex items-center gap-6">
               <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-500 uppercase">Khả năng Sinh tồn</span>
                  <span className="text-lg font-black text-indigo-400">{stats.survivalDays} <span className="text-[10px] text-white/40">Ngày</span></span>
               </div>
               <div className="w-[1px] h-8 bg-white/10"></div>
               <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-500 uppercase">Chi tiêu hôm nay</span>
                  <span className="text-lg font-black text-rose-400">{formatCurrency(stats.todayExpense)}</span>
               </div>
            </div>
          </div>
          <i className="fas fa-gem absolute -right-6 -bottom-6 text-[120px] text-white/5 pointer-events-none"></i>
        </div>
      </div>

      {/* Biểu đồ Kỷ luật */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
            <i className="fas fa-chart-line text-indigo-500"></i> Kỷ luật 7 ngày
          </h3>
          <div className="flex items-center gap-3">
             <div className="flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-rose-500"></span>
                <span className="text-[9px] font-bold text-slate-400 uppercase">Chi</span>
             </div>
             <div className="flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-indigo-200"></span>
                <span className="text-[9px] font-bold text-slate-400 uppercase">Hạn mức</span>
             </div>
          </div>
        </div>
        <div className="h-56 w-full">
          {transactions.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fontSize: 9, fill: '#94a3b8', fontWeight: 700}} dy={10} />
                <YAxis hide domain={[0, 'auto']} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', fontSize: '10px', fontWeight: 700 }}
                  formatter={(value: number) => [formatCurrency(value), '']}
                />
                <Area type="monotone" dataKey="target" fill="#f5f3ff" stroke="none" fillOpacity={1} />
                <Bar dataKey="expense" fill="#f43f5e" radius={[4, 4, 0, 0]} barSize={12} />
                <Line type="monotone" dataKey="target" stroke="#818cf8" strokeWidth={2} strokeDasharray="5 5" dot={false} />
                <ReferenceLine y={0} stroke="#000" />
              </ComposedChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-2">
               <i className="fas fa-chart-bar text-3xl opacity-20"></i>
               <p className="text-[10px] font-bold uppercase tracking-widest">Chưa có dữ liệu kỷ luật</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, TransactionType, PaymentSource, Settings, FinancialStats } from './types';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import AIChat from './components/AIChat';
import { exportToCSV } from './services/exportService';

const App: React.FC = () => {
  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem('cashflow_settings');
    return saved ? JSON.parse(saved) : { initialCash: 0, initialBank: 0, dailyCost: 0 };
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem('cashflow_transactions');
    return saved ? JSON.parse(saved) : [];
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'ai'>('dashboard');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  useEffect(() => {
    localStorage.setItem('cashflow_settings', JSON.stringify(settings));
  }, [settings]);

  useEffect(() => {
    localStorage.setItem('cashflow_transactions', JSON.stringify(transactions));
  }, [transactions]);

  useEffect(() => {
    const updateOnlineStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);
    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
    };
  }, []);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;
    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    let cumulativeSaving = 0;
    if (settings.dailyCost > 0) {
      const firstDateStr = transactions.length > 0 
        ? transactions.reduce((min, t) => t.date < min ? t.date : min, todayStr)
        : todayStr;

      const start = new Date(firstDateStr);
      const end = new Date(todayStr);
      const timeDiff = end.getTime() - start.getTime();
      const diffDays = Math.max(1, Math.floor(timeDiff / (1000 * 60 * 60 * 24)) + 1);
      const totalBudget = diffDays * settings.dailyCost;
      const totalSpent = transactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .reduce((sum, t) => sum + t.amount, 0);
      cumulativeSaving = totalBudget - totalSpent;
    }

    return {
      currentCash, currentBank, total, survivalDays,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense,
      cumulativeSaving
    };
  }, [transactions, settings]);

  const handleAddTransaction = (t: Omit<Transaction, 'id'>) => {
    setTransactions([{...t, id: Date.now().toString()}, ...transactions]);
    if (activeTab !== 'transactions') setActiveTab('transactions');
  };

  const handleUpdateTransaction = (updated: Transaction) => {
    setTransactions(transactions.map(t => t.id === updated.id ? updated : t));
    setEditingTransaction(null);
  };

  const handleDeleteTransaction = (id: string) => {
    if (window.confirm('Xóa giao dịch này?')) {
      setTransactions(transactions.filter(t => t.id !== id));
      if (editingTransaction?.id === id) setEditingTransaction(null);
    }
  };

  const handleResetData = () => {
    if (window.confirm('Xóa toàn bộ dữ liệu?')) {
      setTransactions([]);
      setSettings({ initialCash: 0, initialBank: 0, dailyCost: 0 });
      localStorage.clear();
      window.location.reload();
    }
  };

  return (
    <div className="h-screen flex flex-col bg-slate-50 font-sans overflow-hidden">
      {/* Header - Fixed Height & Safe Area aware */}
      <header className="flex-none bg-white border-b border-slate-100 px-5 pt-[env(safe-area-inset-top,1rem)] h-[calc(4rem+env(safe-area-inset-top,0px))] flex items-center justify-between z-50 glass-effect">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-200">
            <i className="fas fa-wallet text-white text-xs"></i>
          </div>
          <h1 className="text-lg font-black tracking-tight text-slate-800 uppercase">
            Cash<span className="text-indigo-600">Flow</span>
          </h1>
        </div>

        <div className="flex items-center gap-3">
          {!isOnline && (
            <div className="bg-rose-50 text-rose-600 px-2.5 py-1 rounded-full text-[10px] font-black border border-rose-100 animate-pulse">
              OFFLINE
            </div>
          )}
          <button 
            onClick={() => exportToCSV(transactions, settings)} 
            className="w-10 h-10 bg-slate-50 text-slate-600 rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all flex items-center justify-center active-scale"
          >
            <i className="fas fa-file-export text-sm"></i>
          </button>
        </div>
      </header>

      {/* Main Content Area - Scrollable */}
      <main className={`flex-1 overflow-y-auto ${activeTab === 'ai' ? 'overflow-hidden' : 'p-4'}`}>
        <div className={`max-w-xl mx-auto h-full ${activeTab === 'ai' ? '' : 'space-y-5 pb-8'}`}>
          {activeTab === 'dashboard' && (
            <>
               <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100">
                  <div className="flex justify-between items-center mb-4">
                    <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest">Thiết lập mục tiêu</p>
                    <button onClick={handleResetData} className="text-[10px] text-rose-400 font-bold hover:text-rose-600">RESET</button>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[10px] text-slate-400 font-bold ml-1">TIỀN MẶT</label>
                      <input type="number" placeholder="0" value={settings.initialCash || ''} onChange={e => setSettings({...settings, initialCash: +e.target.value})} className="w-full bg-slate-50 p-3 rounded-2xl text-sm font-bold outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[10px] text-slate-400 font-bold ml-1">TÀI KHOẢN</label>
                      <input type="number" placeholder="0" value={settings.initialBank || ''} onChange={e => setSettings({...settings, initialBank: +e.target.value})} className="w-full bg-slate-50 p-3 rounded-2xl text-sm font-bold outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                    </div>
                    <div className="col-span-2 space-y-1">
                      <label className="text-[10px] text-slate-400 font-bold ml-1 flex justify-between">
                        <span>HẠN MỨC / NGÀY</span>
                        <span className="text-indigo-600 font-black">{settings.dailyCost.toLocaleString()}đ</span>
                      </label>
                      <input type="number" placeholder="VD: 80000" value={settings.dailyCost || ''} onChange={e => setSettings({...settings, dailyCost: +e.target.value})} className="w-full bg-indigo-50/50 p-3.5 rounded-2xl text-base font-black text-indigo-700 outline-none border border-indigo-100 focus:bg-white transition-all"/>
                    </div>
                  </div>
               </div>
               <Dashboard stats={stats} transactions={transactions} settings={settings} />
            </>
          )}

          {activeTab === 'transactions' && (
            <>
              <TransactionForm 
                onAdd={handleAddTransaction} 
                editingTransaction={editingTransaction}
                onUpdate={handleUpdateTransaction}
                onCancelEdit={() => setEditingTransaction(null)}
              />
              <TransactionList 
                transactions={transactions} 
                settings={settings}
                onDelete={handleDeleteTransaction}
                onEdit={(t) => {
                  setEditingTransaction(t);
                  document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' });
                }}
              />
            </>
          )}

          {activeTab === 'ai' && (
            <div className="h-full">
              {isOnline ? (
                <AIChat 
                  transactions={transactions} 
                  stats={stats} 
                  onAddTransaction={handleAddTransaction} 
                />
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-center p-12 space-y-4">
                  <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center">
