            <i className="fas fa-wallet text-white text-3xl"></i>
          </div>
          <h1 className="text-3xl font-black text-white tracking-tighter">
            CASH<span className="text-indigo-500">FLOW</span>
          </h1>
          <p className="text-slate-400 text-sm mt-2 font-medium">Quản lý dòng tiền thông minh với AI</p>
        </div>

        <div className="bg-white/10 backdrop-blur-xl border border-white/10 p-8 rounded-[40px] shadow-2xl">
          <div className="flex bg-white/5 p-1 rounded-2xl mb-8">
            <button 
              onClick={() => setIsLogin(true)}
              className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${isLogin ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}
            >
              Đăng nhập
            </button>
            <button 
              onClick={() => setIsLogin(false)}
              className={`flex-1 py-3 text-xs font-black uppercase tracking-widest rounded-xl transition-all ${!isLogin ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400'}`}
            >
