const AdminPanel: React.FC<Props> = ({ onClose }) => {
  const [users, setUsers] = useState<User[]>([]);

  useEffect(() => {
    const savedUsers = JSON.parse(localStorage.getItem('cashflow_users') || '[]');
    setUsers(savedUsers);
  }, []);

  const deleteUser = (username: string) => {
    if (username === 'admin') return alert("Không thể xóa tài khoản admin gốc!");
    if (window.confirm(`Bạn chắc chắn muốn xóa tài khoản ${username}? Mọi dữ liệu thu chi của họ sẽ bị mất.`)) {
      const updated = users.filter(u => u.username !== username);
      localStorage.setItem('cashflow_users', JSON.stringify(updated));
      setUsers(updated);
      // Xóa dữ liệu liên quan
      localStorage.removeItem(`cashflow_transactions_${username}`);
      localStorage.removeItem(`cashflow_settings_${username}`);
    }
  };

  const exportUsers = () => {
    const headers = ["Username", "Tên", "Quyền", "Ngày tạo"];
    const rows = users.map(u => [u.username, u.name, u.role, u.createdAt || 'N/A']);
    const csvContent = "\ufeff" + [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `Danh_Sach_Nguoi_Dung_${new Date().getTime()}.csv`;
    link.click();
  };

  return (
    <div className="bg-white rounded-[32px] shadow-xl border border-slate-100 overflow-hidden animate-in fade-in zoom-in duration-300">
