            <i className="fas fa-file-download"></i>
          </button>
          <button onClick={onClose} className="bg-white/10 hover:bg-white/20 p-2.5 rounded-xl transition-all border border-white/10">
            <i className="fas fa-times"></i>
          </button>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-slate-50">
            <tr>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Người dùng</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Vai trò</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Hành động</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {users.map(u => (
              <tr key={u.username} className="hover:bg-slate-50/50 transition-colors">
                <td className="px-6 py-4">
                  <div className="font-bold text-slate-700 text-sm">{u.name}</div>
                  <div className="text-[10px] text-slate-400 font-mono">@{u.username}</div>
                </td>
                <td className="px-6 py-4">
                  <span className={`text-[8px] font-black px-2 py-1 rounded-md uppercase border ${u.role === UserRole.ADMIN ? 'bg-amber-50 text-amber-600 border-amber-100' : 'bg-blue-50 text-blue-600 border-blue-100'}`}>
                    {u.role}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  {u.username !== 'admin' && (
                    <button onClick={() => deleteUser(u.username)} className="text-rose-500 hover:text-rose-700 p-2 active:scale-90 transition-all">
