import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';

interface Props {
  onClose: () => void;
}

const AdminPanel: React.FC<Props> = ({ onClose }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [newName, setNewName] = useState('');
  const [newPassword, setNewPassword] = useState('');

  useEffect(() => {
    loadUsers();
  }, []);

  const loadUsers = () => {
    const savedUsers = JSON.parse(localStorage.getItem('cashflow_users') || '[]');
    setUsers(savedUsers);
  };

  const deleteUser = (username: string) => {
    if (username === 'admin') return alert("Không thể xóa tài khoản Admin hệ thống!");
    if (window.confirm(`Bạn có chắc chắn muốn xóa tài khoản @${username}?`)) {
      const updated = users.filter(u => u.username !== username);
      localStorage.setItem('cashflow_users', JSON.stringify(updated));
      localStorage.removeItem(`cashflow_transactions_${username}`);
      localStorage.removeItem(`cashflow_settings_${username}`);
      setUsers(updated);
    }
  };

  const startEdit = (user: User) => {
    setEditingUser(user);
    setNewName(user.name);
    setNewPassword(user.password || '');
  };

  const saveEdit = () => {
    if (!editingUser) return;
    const updatedUsers = users.map(u => {
      if (u.username === editingUser.username) {
        return { ...u, name: newName, password: newPassword };
      }
      return u;
    });
    localStorage.setItem('cashflow_users', JSON.stringify(updatedUsers));
    setUsers(updatedUsers);
    setEditingUser(null);
    alert("Đã cập nhật thông tin thành công!");
  };

  const exportUsers = () => {
    const headers = ["Username", "Tên", "Quyền", "Mật khẩu", "Ngày tạo"];
    const rows = users.map(u => [u.username, u.name, u.role, u.password, u.createdAt || 'N/A']);
    const csvContent = "\ufeff" + [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `Du_Lieu_Nguoi_Dung_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  return (
    <div className="bg-white rounded-[32px] shadow-2xl border border-slate-100 overflow-hidden flex flex-col h-full animate-in fade-in zoom-in duration-300">
      {/* Header Quản Trị */}
      <div className="p-6 bg-slate-900 text-white flex justify-between items-center shrink-0">
        <div>
          <h2 className="text-xl font-black uppercase tracking-tighter flex items-center gap-2">
            <i className="fas fa-user-shield text-indigo-400"></i>
            Hệ Thống Quản Trị
          </h2>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">
            Tổng cộng {users.length} tài khoản thành viên
          </p>
        </div>
        <div className="flex gap-2">
          <button onClick={exportUsers} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center hover:bg-white/20 transition-all" title="Xuất CSV">
            <i className="fas fa-download"></i>
          </button>
          <button onClick={onClose} className="w-10 h-10 bg-white/10 rounded-xl flex items-center justify-center hover:bg-rose-500 transition-all">
            <i className="fas fa-times"></i>
          </button>
        </div>
      </div>

      {/* Danh sách người dùng */}
      <div className="flex-1 overflow-y-auto custom-scrollbar">
        <table className="w-full text-left">
          <thead className="bg-slate-50 sticky top-0 z-10">
            <tr>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Thông tin tài khoản</th>
              <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Thao tác</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {users.map(u => (
              <tr key={u.username} className="hover:bg-slate-50/50 transition-colors">
                <td className="px-6 py-5">
                  <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-full flex items-center justify-center font-black text-xs ${u.role === UserRole.ADMIN ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'}`}>
                      {u.name.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <div className="font-bold text-slate-800 text-sm flex items-center gap-2">
                        {u.name}
                        {u.role === UserRole.ADMIN && <i className="fas fa-check-circle text-blue-500 text-[10px]"></i>}
                      </div>
                      <div className="text-[10px] text-slate-400 font-mono">@{u.username} • <span className="text-slate-300">MK: {u.password?.replace(/./g, '*')}</span></div>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-5 text-right">
                  <div className="flex justify-end gap-1">
                    <button 
                      onClick={() => startEdit(u)}
                      className="w-8 h-8 rounded-lg bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center"
                      title="Sửa thông tin"
                    >
                      <i className="fas fa-pen text-[10px]"></i>
                    </button>
                    {u.username !== 'admin' && (
                      <button 
                        onClick={() => deleteUser(u.username)}
                        className="w-8 h-8 rounded-lg bg-rose-50 text-rose-500 hover:bg-rose-600 hover:text-white transition-all flex items-center justify-center"
