const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('cashflow_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem(`cashflow_settings_${user?.username}`);
    return saved ? JSON.parse(saved) : { userId: user?.username || '', initialCash: 0, initialBank: 0, dailyCost: 0 };
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem(`cashflow_transactions_${user?.username}`);
    return saved ? JSON.parse(saved) : [];
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'ai' | 'admin'>('dashboard');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  useEffect(() => {
    if (user) {
      localStorage.setItem('cashflow_current_user', JSON.stringify(user));
      localStorage.setItem(`cashflow_settings_${user.username}`, JSON.stringify(settings));
      localStorage.setItem(`cashflow_transactions_${user.username}`, JSON.stringify(transactions));
    }
  }, [user, settings, transactions]);

  useEffect(() => {
    const updateOnlineStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);
    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
    };
  }, []);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;
    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    let cumulativeSaving = 0;
    if (settings.dailyCost > 0) {
      const firstDateStr = transactions.length > 0 
        ? transactions.reduce((min, t) => t.date < min ? t.date : min, todayStr)
        : todayStr;

      const start = new Date(firstDateStr);
      const end = new Date(todayStr);
      const diffDays = Math.max(1, Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1);
      cumulativeSaving = (diffDays * settings.dailyCost) - transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0);
    }

    return {
      currentCash, currentBank, total, survivalDays,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense,
      cumulativeSaving
    };
  }, [transactions, settings]);

  const handleAddTransaction = (t: Omit<Transaction, 'id' | 'userId'>) => {
    if (!user) return;
    setTransactions([{...t, id: Date.now().toString(), userId: user.username}, ...transactions]);
    if (activeTab !== 'transactions') setActiveTab('transactions');
  };

  const handleLogout = () => {
    if(window.confirm("Xác nhận đăng xuất tài khoản?")) {
      geminiService.resetSession();
      localStorage.removeItem('cashflow_current_user');
      setUser(null);
      setActiveTab('dashboard');
    }
  };

  if (!user) return <Auth onLogin={setUser} />;

  return (
    <div className="h-screen flex flex-col bg-slate-50 font-sans overflow-hidden">
      {/* Header */}
      <header className="flex-none bg-white border-b border-slate-100 px-5 pt-[env(safe-area-inset-top,1rem)] h-[calc(4.5rem+env(safe-area-inset-top,0px))] flex items-center justify-between z-50 glass-effect">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-100">
            <i className={`fas ${user.role === UserRole.ADMIN ? 'fa-user-shield' : 'fa-wallet'} text-white text-sm`}></i>
          </div>
          <div>
            <h1 className="text-sm font-black text-slate-800 uppercase tracking-tight truncate max-w-[120px]">{user.name}</h1>
            <p className="text-[9px] font-bold text-indigo-500 uppercase tracking-widest">{user.role === UserRole.ADMIN ? 'Hệ thống Quản trị' : 'Thành viên thường'}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {user.role === UserRole.ADMIN && (
            <button 
              onClick={() => setActiveTab('admin')}
              className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${activeTab === 'admin' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-50 text-slate-600 border border-slate-100'}`}
              title="Quản lý Người dùng"
            >
              <i className="fas fa-users-cog text-xs"></i>
            </button>
          )}
          <button 
            onClick={handleLogout}
            className="w-10 h-10 bg-rose-50 text-rose-500 rounded-xl flex items-center justify-center active:scale-90 border border-rose-100"
            title="Đăng xuất"
          >
            <i className="fas fa-power-off text-xs"></i>
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className={`flex-1 overflow-y-auto ${activeTab === 'ai' || activeTab === 'admin' ? 'overflow-hidden' : 'p-4'}`}>
        <div className={`max-w-xl mx-auto h-full ${(activeTab === 'ai' || activeTab === 'admin') ? '' : 'space-y-6 pb-24'}`}>
          {activeTab === 'dashboard' && (
            <>
               <div className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100 animate-in fade-in slide-in-from-top-4 duration-500">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-6">
                     <i className="fas fa-sliders-h text-indigo-500"></i> Cấu hình số dư ban đầu
                  </p>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase">Tiền mặt</label>
                      <input type="number" value={settings.initialCash || ''} onChange={e => setSettings({...settings, initialCash: +e.target.value})} className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase">Ngân hàng</label>
                      <input type="number" value={settings.initialBank || ''} onChange={e => setSettings({...settings, initialBank: +e.target.value})} className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                    </div>
                    <div className="col-span-2 space-y-1.5 mt-2">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase text-center block w-full">Hạn mức chi tiêu / Ngày</label>
                      <input type="number" placeholder="0" value={settings.dailyCost || ''} onChange={e => setSettings({...settings, dailyCost: +e.target.value})} className="w-full bg-indigo-50/50 p-5 rounded-2xl text-xl font-black text-indigo-700 outline-none border border-indigo-100 focus:bg-white transition-all text-center"/>
                    </div>
                  </div>
               </div>
               <Dashboard stats={stats} transactions={transactions} settings={settings} />
            </>
          )}

          {activeTab === 'transactions' && (
            <div className="space-y-4">
              <TransactionForm 
                onAdd={handleAddTransaction} 
                editingTransaction={editingTransaction}
                onUpdate={(updated) => {
                  setTransactions(transactions.map(t => t.id === updated.id ? updated : t));
                  setEditingTransaction(null);
                }}
                onCancelEdit={() => setEditingTransaction(null)}
              />
              <TransactionList 
                transactions={transactions} 
                settings={settings}
                onDelete={(id) => {
                  if (window.confirm('Xóa giao dịch này?')) setTransactions(transactions.filter(t => t.id !== id));
                }}
                onEdit={(t) => {
                  setEditingTransaction(t);
                  document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' });
                }}
              />
            </div>
          )}

          {activeTab === 'ai' && (
            <AIChat 
              transactions={transactions} 
              stats={stats} 
              onAddTransaction={handleAddTransaction} 
              onClose={() => setActiveTab('dashboard')} 
            />
          )}

          {activeTab === 'admin' && user.role === UserRole.ADMIN && (
            <div className="h-full p-4">
               <AdminPanel onClose={() => setActiveTab('dashboard')} />
            </div>
          )}
        </div>
      </main>

      {/* Navigation */}
      <nav className="flex-none bg-white border-t border-slate-100 flex justify-around items-center px-6 pb-[env(safe-area-inset-bottom,1.5rem)] h-[calc(5.5rem+env(safe-area-inset-bottom,0px))] z-50 glass-effect">
        {[
          { id: 'dashboard', icon: 'fa-th-large', label: 'Tổng quan' },
          { id: 'transactions', icon: 'fa-exchange-alt', label: 'Thu chi' },
          { id: 'ai', icon: 'fa-robot', label: 'Trợ lý AI' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex flex-col items-center gap-1.5 transition-all duration-300 relative group ${
              activeTab === tab.id ? 'text-indigo-600 scale-110' : 'text-slate-400'
            }`}
          >
            {activeTab === tab.id && <span className="absolute -top-4 w-1.5 h-1.5 bg-indigo-600 rounded-full animate-bounce"></span>}
            <i className={`fas ${tab.icon} text-lg`}></i>
            <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { ComposedChart, Area, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Line, ReferenceLine } from 'recharts';
import { FinancialStats, Transaction, TransactionType, Settings, User } from '../types';

interface Props {
  stats: FinancialStats;
  transactions: Transaction[];
  settings: Settings;
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ stats, transactions, settings, user, onLogout }) => {
  const chartData = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      days.push(d.toISOString().split('T')[0]);
    }

    return days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const expense = dayTransactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .reduce((sum, t) => sum + t.amount, 0);
      const income = dayTransactions
        .filter(t => t.type === TransactionType.INCOME)
        .reduce((sum, t) => sum + t.amount, 0);

      return {
        date: date.split('-').slice(1).reverse().join('/'),
        expense,
        income,
        target: settings.dailyCost,
        saving: settings.dailyCost - expense
      };
    });
  }, [transactions, settings.dailyCost]);

  const formatCurrency = (val: number) => val.toLocaleString('vi-VN') + 'đ';

  const todaySaving = settings.dailyCost - stats.todayExpense;

  const savingAdvice = () => {
    if (settings.dailyCost === 0) return "Hãy thiết lập mục tiêu chi tiêu mỗi ngày!";
    if (stats.cumulativeSaving > 0) return "Bạn đang quản lý kỷ luật cực tốt! Tổng tích lũy vẫn dương. 🚀";
    if (stats.cumulativeSaving === 0) return "Hết ngân sách tích lũy! Đừng tiêu thêm nhé. ⚖️";
    return "NGUY HIỂM: Bạn đang chi vượt hạn mức cộng dồn. Cần thắt chặt chi tiêu! 🛑";
  };

  return (
    <div className="space-y-5 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">

      {/* KHOẢN NHO NHỎ CARD */}
      <div className={`p-6 rounded-3xl shadow-lg border-2 transition-all duration-500 relative overflow-hidden ${
        stats.cumulativeSaving >= 0 
          ? 'bg-emerald-50 border-emerald-200' 
          : 'bg-rose-50 border-rose-300 animate-[shake_0.5s_ease-in-out_infinite]'
      }`}>
        <div className="flex justify-between items-start z-10 relative">
          <div>
            <p className={`text-[10px] font-black uppercase tracking-widest ${stats.cumulativeSaving >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
              Khoản Nho Nhỏ (Tích lũy)
            </p>
            <h2 className={`text-3xl font-black mt-1 ${stats.cumulativeSaving >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
              {stats.cumulativeSaving > 0 ? '+' : ''}{formatCurrency(stats.cumulativeSaving)}
            </h2>
            <div className={`mt-3 inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-black border ${
              todaySaving >= 0 
                ? 'bg-emerald-500 text-white border-transparent' 
                : 'bg-rose-500 text-white border-transparent'
            }`}>
               <i className={`fas ${todaySaving >= 0 ? 'fa-plus-circle' : 'fa-minus-circle'}`}></i>
               Hôm nay: {todaySaving > 0 ? '+' : ''}{formatCurrency(todaySaving)}
            </div>
          </div>
          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl shadow-lg ${
            stats.cumulativeSaving >= 0 ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'
          }`}>
            <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-piggy-bank' : 'fa-triangle-exclamation'}`}></i>
          </div>
        </div>

        <p className={`text-[11px] font-bold mt-5 leading-relaxed z-10 relative ${stats.cumulativeSaving >= 0 ? 'text-emerald-600/80' : 'text-rose-600/80'}`}>
          {savingAdvice()}
        </p>

        <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-chart-area' : 'fa-fire'} absolute -right-4 -bottom-4 text-8xl opacity-5`}></i>
      </div>

      {/* Metric Cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col justify-center min-h-[100px]">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest z-10">Vốn Tiền mặt</p>
          <p className="text-xl font-black text-slate-800 mt-1 z-10">{formatCurrency(stats.currentCash)}</p>
          <i className="fas fa-wallet absolute -right-3 -bottom-3 text-5xl text-slate-50 opacity-40 transform rotate-12"></i>
        </div>

        <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col justify-center min-h-[100px]">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest z-10">Trong Tài khoản</p>
          <p className="text-xl font-black text-slate-800 mt-1 z-10">{formatCurrency(stats.currentBank)}</p>
          <i className="fas fa-credit-card absolute -right-3 -bottom-3 text-5xl text-slate-50 opacity-40 transform -rotate-12"></i>
        </div>

        <div className="col-span-2 bg-slate-900 p-6 rounded-3xl shadow-xl text-white relative overflow-hidden">
          <div className="z-10 relative">
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Tài sản ròng hiện có</p>
            <p className="text-4xl font-black mt-1 tracking-tighter">{formatCurrency(stats.total)}</p>
            <div className="mt-5 flex items-center gap-6">
               <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-500 uppercase">Khả năng Sinh tồn</span>
                  <span className="text-lg font-black text-indigo-400">{stats.survivalDays} <span className="text-[10px] text-white/40">Ngày</span></span>
               </div>
               <div className="w-[1px] h-8 bg-white/10"></div>
               <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-500 uppercase">Chi hôm nay</span>
                  <span className="text-lg font-black text-rose-400">{formatCurrency(stats.todayExpense)}</span>
               </div>
            </div>
          </div>
          <i className="fas fa-gem absolute -right-6 -bottom-6 text-[120px] text-white/5 pointer-events-none"></i>
        </div>
      </div>

      {/* Biểu đồ Kỷ luật */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100">
        <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest flex items-center gap-2 mb-6">
          <i className="fas fa-chart-line text-indigo-500"></i> Kỷ luật 7 ngày
        </h3>
        <div className="h-56 w-full">
          {transactions.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fontSize: 9, fill: '#94a3b8', fontWeight: 700}} dy={10} />
                <YAxis hide domain={[0, 'auto']} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', fontSize: '10px', fontWeight: 700 }}
                  formatter={(value: number) => [formatCurrency(value), '']}
                />
                <Area type="monotone" dataKey="target" fill="#f5f3ff" stroke="none" fillOpacity={1} />
                <Bar dataKey="expense" fill="#f43f5e" radius={[4, 4, 0, 0]} barSize={12} />
                <Line type="monotone" dataKey="target" stroke="#818cf8" strokeWidth={2} strokeDasharray="5 5" dot={false} />
                <ReferenceLine y={0} stroke="#000" />
              </ComposedChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-2">
               <i className="fas fa-chart-bar text-3xl opacity-20"></i>
               <p className="text-[10px] font-bold uppercase tracking-widest">Chưa có dữ liệu kỷ luật</p>
            </div>
          )}
        </div>
      </div>

      {/* TÀI KHOẢN CARD - MỚI THÊM */}
      <div className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100">
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Thông tin tài khoản</p>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center text-xl font-black shadow-lg shadow-indigo-100">
              {user.name.charAt(0).toUpperCase()}
            </div>
            <div>
              <h4 className="text-sm font-black text-slate-800">{user.name}</h4>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">@{user.username}</p>
            </div>
          </div>
          <button 
            onClick={onLogout}
            className="flex flex-col items-center gap-1 group"
          >
            <div className="w-10 h-10 bg-rose-50 text-rose-500 rounded-xl flex items-center justify-center border border-rose-100 group-hover:bg-rose-500 group-hover:text-white transition-all">
              <i className="fas fa-power-off text-sm"></i>
            </div>
            <span className="text-[8px] font-black text-rose-500 uppercase tracking-widest group-hover:text-rose-600">Thoát</span>
          </button>
        </div>
      </div>

      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-4px); }
          75% { transform: translateX(4px); }
        }
      `}</style>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, TransactionType, PaymentSource, Settings, FinancialStats, User, UserRole } from './types';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import AIChat from './components/AIChat';
import Auth from './components/Auth';
import AdminPanel from './components/AdminPanel';
import { exportToCSV } from './services/exportService';
import { geminiService } from './services/geminiService';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('cashflow_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem(`cashflow_settings_${user?.username}`);
    return saved ? JSON.parse(saved) : { userId: user?.username || '', initialCash: 0, initialBank: 0, dailyCost: 0 };
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem(`cashflow_transactions_${user?.username}`);
    return saved ? JSON.parse(saved) : [];
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'ai' | 'admin'>('dashboard');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  useEffect(() => {
    if (user) {
      localStorage.setItem('cashflow_current_user', JSON.stringify(user));
      localStorage.setItem(`cashflow_settings_${user.username}`, JSON.stringify(settings));
      localStorage.setItem(`cashflow_transactions_${user.username}`, JSON.stringify(transactions));
    }
  }, [user, settings, transactions]);

  useEffect(() => {
    const updateOnlineStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);
    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
    };
  }, []);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;
    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    let cumulativeSaving = 0;
    if (settings.dailyCost > 0) {
      const firstDateStr = transactions.length > 0 
        ? transactions.reduce((min, t) => t.date < min ? t.date : min, todayStr)
        : todayStr;

      const start = new Date(firstDateStr);
      const end = new Date(todayStr);
      const diffDays = Math.max(1, Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1);
      cumulativeSaving = (diffDays * settings.dailyCost) - transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0);
    }

    return {
      currentCash, currentBank, total, survivalDays,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense,
      cumulativeSaving
    };
  }, [transactions, settings]);

  const handleAddTransaction = (t: Omit<Transaction, 'id' | 'userId'>) => {
    if (!user) return;
    setTransactions([{...t, id: Date.now().toString(), userId: user.username}, ...transactions]);
    if (activeTab !== 'transactions') setActiveTab('transactions');
  };

  const handleLogout = () => {
    if(window.confirm("Xác nhận đăng xuất tài khoản?")) {
      geminiService.resetSession();
      localStorage.removeItem('cashflow_current_user');
      setUser(null);
      setActiveTab('dashboard');
    }
  };

  if (!user) return <Auth onLogin={setUser} />;

  return (
    <div className="h-screen flex flex-col bg-slate-50 font-sans overflow-hidden">
      {/* Header */}
      <header className="flex-none bg-white border-b border-slate-100 px-5 pt-[env(safe-area-inset-top,1rem)] h-[calc(4.5rem+env(safe-area-inset-top,0px))] flex items-center justify-between z-50 glass-effect">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-100">
            <i className={`fas ${user.role === UserRole.ADMIN ? 'fa-user-shield' : 'fa-wallet'} text-white text-sm`}></i>
          </div>
          <div>
            <h1 className="text-sm font-black text-slate-800 uppercase tracking-tight truncate max-w-[120px]">{user.name}</h1>
            <p className="text-[9px] font-bold text-indigo-500 uppercase tracking-widest">{user.role === UserRole.ADMIN ? 'Hệ thống Quản trị' : 'Thành viên thường'}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {user.role === UserRole.ADMIN && (
            <button 
              onClick={() => setActiveTab('admin')}
              className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${activeTab === 'admin' ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-50 text-slate-600 border border-slate-100'}`}
              title="Quản lý Người dùng"
            >
              <i className="fas fa-users-cog text-xs"></i>
            </button>
          )}
          <button 
            onClick={handleLogout}
            className="w-10 h-10 bg-rose-50 text-rose-500 rounded-xl flex items-center justify-center active:scale-90 border border-rose-100 shadow-sm"
            title="Đăng xuất"
          >
            <i className="fas fa-power-off text-xs"></i>
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className={`flex-1 overflow-y-auto ${activeTab === 'ai' || activeTab === 'admin' ? 'overflow-hidden' : 'p-4'}`}>
        <div className={`max-w-xl mx-auto h-full ${(activeTab === 'ai' || activeTab === 'admin') ? '' : 'space-y-6 pb-24'}`}>
          {activeTab === 'dashboard' && (
            <>
               <div className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100 animate-in fade-in slide-in-from-top-4 duration-500">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-6">
                     <i className="fas fa-sliders-h text-indigo-500"></i> Cấu hình số dư ban đầu
                  </p>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase">Tiền mặt</label>
                      <input type="number" value={settings.initialCash || ''} onChange={e => setSettings({...settings, initialCash: +e.target.value})} className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase">Ngân hàng</label>
                      <input type="number" value={settings.initialBank || ''} onChange={e => setSettings({...settings, initialBank: +e.target.value})} className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                    </div>
                    <div className="col-span-2 space-y-1.5 mt-2">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase text-center block w-full">Hạn mức chi tiêu / Ngày</label>
                      <input type="number" placeholder="0" value={settings.dailyCost || ''} onChange={e => setSettings({...settings, dailyCost: +e.target.value})} className="w-full bg-indigo-50/50 p-5 rounded-2xl text-xl font-black text-indigo-700 outline-none border border-indigo-100 focus:bg-white transition-all text-center"/>
                    </div>
                  </div>
               </div>
               <Dashboard stats={stats} transactions={transactions} settings={settings} user={user} onLogout={handleLogout} />
            </>
          )}

          {activeTab === 'transactions' && (
            <div className="space-y-4">
              <TransactionForm 
                onAdd={handleAddTransaction} 
                editingTransaction={editingTransaction}
                onUpdate={(updated) => {
                  setTransactions(transactions.map(t => t.id === updated.id ? updated : t));
                  setEditingTransaction(null);
                }}
                onCancelEdit={() => setEditingTransaction(null)}
              />
              <TransactionList 
                transactions={transactions} 
                settings={settings}
                onDelete={(id) => {
                  if (window.confirm('Xóa giao dịch này?')) setTransactions(transactions.filter(t => t.id !== id));
                }}
                onEdit={(t) => {
                  setEditingTransaction(t);
                  document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' });
                }}
              />
            </div>
          )}

          {activeTab === 'ai' && (
            <AIChat 
              transactions={transactions} 
              stats={stats} 
              onAddTransaction={handleAddTransaction} 
              onClose={() => setActiveTab('dashboard')} 
            />
          )}

          {activeTab === 'admin' && user.role === UserRole.ADMIN && (
            <div className="h-full p-4">
               <AdminPanel onClose={() => setActiveTab('dashboard')} />
            </div>
          )}
        </div>
      </main>

      {/* Navigation */}
      <nav className="flex-none bg-white border-t border-slate-100 flex justify-around items-center px-6 pb-[env(safe-area-inset-bottom,1.5rem)] h-[calc(5.5rem+env(safe-area-inset-bottom,0px))] z-50 glass-effect">
        {[
          { id: 'dashboard', icon: 'fa-th-large', label: 'Tổng quan' },
          { id: 'transactions', icon: 'fa-exchange-alt', label: 'Thu chi' },
          { id: 'ai', icon: 'fa-robot', label: 'Trợ lý AI' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex flex-col items-center gap-1.5 transition-all duration-300 relative group ${
              activeTab === tab.id ? 'text-indigo-600 scale-110' : 'text-slate-400'
            }`}
          >
            {activeTab === tab.id && <span className="absolute -top-4 w-1.5 h-1.5 bg-indigo-600 rounded-full animate-bounce"></span>}
            <i className={`fas ${tab.icon} text-lg`}></i>
            <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, TransactionType, PaymentSource, Settings, FinancialStats, User, UserRole } from './types';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import AIChat from './components/AIChat';
import Auth from './components/Auth';
import AdminPanel from './components/AdminPanel';
import { geminiService } from './services/geminiService';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('cashflow_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [settings, setSettings] = useState<Settings>(() => {
    const saved = localStorage.getItem(`cashflow_settings_${user?.username}`);
    return saved ? JSON.parse(saved) : { userId: user?.username || '', initialCash: 0, initialBank: 0, dailyCost: 0 };
  });

  const [transactions, setTransactions] = useState<Transaction[]>(() => {
    const saved = localStorage.getItem(`cashflow_transactions_${user?.username}`);
    return saved ? JSON.parse(saved) : [];
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'ai' | 'admin'>('dashboard');
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  // Cập nhật settings và transactions khi user thay đổi (đăng nhập tài khoản khác)
  useEffect(() => {
    if (user) {
      const savedSettings = localStorage.getItem(`cashflow_settings_${user.username}`);
      const savedTrans = localStorage.getItem(`cashflow_transactions_${user.username}`);

      setSettings(savedSettings ? JSON.parse(savedSettings) : { userId: user.username, initialCash: 0, initialBank: 0, dailyCost: 0 });
      setTransactions(savedTrans ? JSON.parse(savedTrans) : []);
      localStorage.setItem('cashflow_current_user', JSON.stringify(user));
    }
  }, [user]);

  // Lưu dữ liệu khi có thay đổi
  useEffect(() => {
    if (user) {
      localStorage.setItem(`cashflow_settings_${user.username}`, JSON.stringify(settings));
      localStorage.setItem(`cashflow_transactions_${user.username}`, JSON.stringify(transactions));
    }
  }, [settings, transactions, user]);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;
    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE)
      .reduce((sum, t) => sum + t.amount, 0);

    let cumulativeSaving = 0;
    if (settings.dailyCost > 0) {
      const firstDateStr = transactions.length > 0 
        ? transactions.reduce((min, t) => t.date < min ? t.date : min, todayStr)
        : todayStr;

      const start = new Date(firstDateStr);
      const end = new Date(todayStr);
      const diffDays = Math.max(1, Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1);
      cumulativeSaving = (diffDays * settings.dailyCost) - transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0);
    }

    return {
      currentCash, currentBank, total, survivalDays,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense,
      cumulativeSaving
    };
  }, [transactions, settings]);

  const handleAddTransaction = (t: Omit<Transaction, 'id' | 'userId'>) => {
    if (!user) return;
    setTransactions([{...t, id: Date.now().toString(), userId: user.username}, ...transactions]);
    if (activeTab !== 'transactions') setActiveTab('transactions');
  };

  const handleLogout = () => {
    if(window.confirm("Bạn có chắc chắn muốn đăng xuất không?")) {
      geminiService.resetSession();
      localStorage.removeItem('cashflow_current_user');
      setUser(null);
      setActiveTab('dashboard');
    }
  };

  if (!user) return <Auth onLogin={setUser} />;

  return (
    <div className="h-screen flex flex-col bg-slate-50 font-sans overflow-hidden">
      {/* Header Tối Ưu */}
      <header className="flex-none bg-white border-b border-slate-100 px-5 pt-[env(safe-area-inset-top,1rem)] h-[calc(4.5rem+env(safe-area-inset-top,0px))] flex items-center justify-between z-50 glass-effect">
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ${user.role === UserRole.ADMIN ? 'bg-amber-500 shadow-amber-100' : 'bg-indigo-600 shadow-indigo-100'}`}>
            <i className={`fas ${user.role === UserRole.ADMIN ? 'fa-user-shield' : 'fa-wallet'} text-white text-sm`}></i>
          </div>
          <div>
            <h1 className="text-sm font-black text-slate-800 uppercase tracking-tight truncate max-w-[140px] leading-none mb-1">{user.name}</h1>
            <div className="flex items-center gap-1.5">
              <span className={`text-[8px] font-black uppercase px-1.5 py-0.5 rounded-md ${user.role === UserRole.ADMIN ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'}`}>
                {user.role === UserRole.ADMIN ? 'Quản trị viên' : 'Thành viên'}
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-2">
          {user.role === UserRole.ADMIN && (
            <button 
              onClick={() => setActiveTab('admin')}
              className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${activeTab === 'admin' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-600 border border-slate-100 hover:bg-slate-100'}`}
              title="Quản trị hệ thống"
            >
              <i className="fas fa-users-cog text-xs"></i>
            </button>
          )}
          <button 
            onClick={handleLogout}
            className="w-10 h-10 bg-rose-50 text-rose-500 rounded-xl flex items-center justify-center active:scale-90 border border-rose-100 hover:bg-rose-500 hover:text-white transition-all shadow-sm"
            title="Đăng xuất"
          >
            <i className="fas fa-sign-out-alt text-xs"></i>
          </button>
        </div>
      </header>

      {/* Main Content */}
      <main className={`flex-1 overflow-y-auto ${activeTab === 'ai' || activeTab === 'admin' ? 'overflow-hidden' : 'p-4'}`}>
        <div className={`max-w-xl mx-auto h-full ${(activeTab === 'ai' || activeTab === 'admin') ? '' : 'space-y-6 pb-24'}`}>
          {activeTab === 'dashboard' && (
            <>
               <div className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100 animate-in fade-in slide-in-from-top-4 duration-500">
                  <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2 mb-6">
                     <i className="fas fa-sliders-h text-indigo-500"></i> Cấu hình ví & mục tiêu
                  </p>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase">Tiền mặt ban đầu</label>
                      <input type="number" value={settings.initialCash || ''} onChange={e => setSettings({...settings, initialCash: +e.target.value})} className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase">Ngân hàng ban đầu</label>
                      <input type="number" value={settings.initialBank || ''} onChange={e => setSettings({...settings, initialBank: +e.target.value})} className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:border-indigo-100 focus:bg-white transition-all"/>
                    </div>
                    <div className="col-span-2 space-y-1.5 mt-2">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase text-center block w-full">Hạn mức chi tiêu mục tiêu / Ngày</label>
                      <input type="number" placeholder="Ví dụ: 200000" value={settings.dailyCost || ''} onChange={e => setSettings({...settings, dailyCost: +e.target.value})} className="w-full bg-indigo-50/50 p-5 rounded-2xl text-xl font-black text-indigo-700 outline-none border border-indigo-100 focus:bg-white transition-all text-center"/>
                    </div>
                  </div>
               </div>
               <Dashboard stats={stats} transactions={transactions} settings={settings} user={user} onLogout={handleLogout} />
            </>
          )}

          {activeTab === 'transactions' && (
            <div className="space-y-4">
              <TransactionForm 
                onAdd={handleAddTransaction} 
                editingTransaction={editingTransaction}
                onUpdate={(updated) => {
                  setTransactions(transactions.map(t => t.id === updated.id ? updated : t));
                  setEditingTransaction(null);
                }}
                onCancelEdit={() => setEditingTransaction(null)}
              />
              <TransactionList 
                transactions={transactions} 
                settings={settings}
                onDelete={(id) => {
                  if (window.confirm('Xóa giao dịch này?')) setTransactions(transactions.filter(t => t.id !== id));
                }}
                onEdit={(t) => {
                  setEditingTransaction(t);
                  document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' });
                }}
              />
            </div>
          )}

          {activeTab === 'ai' && (
            <AIChat 
              transactions={transactions} 
              stats={stats} 
              onAddTransaction={handleAddTransaction} 
              onClose={() => setActiveTab('dashboard')} 
            />
          )}

          {activeTab === 'admin' && user.role === UserRole.ADMIN && (
            <div className="h-full p-4 overflow-hidden">
               <AdminPanel onClose={() => setActiveTab('dashboard')} />
            </div>
          )}
        </div>
      </main>

      {/* Navigation Tối ưu */}
      <nav className="flex-none bg-white border-t border-slate-100 flex justify-around items-center px-6 pb-[env(safe-area-inset-bottom,1.5rem)] h-[calc(5.5rem+env(safe-area-inset-bottom,0px))] z-50 glass-effect">
        {[
          { id: 'dashboard', icon: 'fa-th-large', label: 'Ví của tôi' },
          { id: 'transactions', icon: 'fa-exchange-alt', label: 'Giao dịch' },
          { id: 'ai', icon: 'fa-robot', label: 'Trợ lý AI' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex flex-col items-center gap-1.5 transition-all duration-300 relative group ${
              activeTab === tab.id ? 'text-indigo-600 scale-110' : 'text-slate-400'
            }`}
          >
            {activeTab === tab.id && <span className="absolute -top-4 w-1.5 h-1.5 bg-indigo-600 rounded-full animate-bounce"></span>}
            <i className={`fas ${tab.icon} text-lg`}></i>
            <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { ComposedChart, Area, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Line, ReferenceLine } from 'recharts';
import { FinancialStats, Transaction, TransactionType, Settings, User, UserRole } from '../types';

interface Props {
  stats: FinancialStats;
  transactions: Transaction[];
  settings: Settings;
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ stats, transactions, settings, user, onLogout }) => {
  const chartData = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      days.push(d.toISOString().split('T')[0]);
    }

    return days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const expense = dayTransactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .reduce((sum, t) => sum + t.amount, 0);
      const income = dayTransactions
        .filter(t => t.type === TransactionType.INCOME)
        .reduce((sum, t) => sum + t.amount, 0);

      return {
        date: date.split('-').slice(1).reverse().join('/'),
        expense,
        income,
        target: settings.dailyCost,
        saving: settings.dailyCost - expense
      };
    });
  }, [transactions, settings.dailyCost]);

  const formatCurrency = (val: number) => val.toLocaleString('vi-VN') + 'đ';

  const todaySaving = settings.dailyCost - stats.todayExpense;

  const savingAdvice = () => {
    if (settings.dailyCost === 0) return "Hãy thiết lập mục tiêu chi tiêu mỗi ngày để tôi giúp bạn theo dõi!";
    if (stats.cumulativeSaving > 0) return "Tuyệt vời! Bạn đang dư dả so với kế hoạch tích lũy. 🚀";
    if (stats.cumulativeSaving === 0) return "Bạn đang tiêu xài đúng ngân sách dự kiến. Cố gắng lên! ⚖️";
    return "CẢNH BÁO: Bạn đang chi vượt hạn mức cộng dồn. Cần tiết kiệm ngay! 🛑";
  };

  return (
    <div className="space-y-5 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">

      {/* TÍCH LŨY CARD */}
      <div className={`p-6 rounded-3xl shadow-lg border-2 transition-all duration-500 relative overflow-hidden ${
        stats.cumulativeSaving >= 0 
          ? 'bg-emerald-50 border-emerald-200' 
          : 'bg-rose-50 border-rose-300 animate-[shake_0.5s_ease-in-out_infinite]'
      }`}>
        <div className="flex justify-between items-start z-10 relative">
          <div>
            <p className={`text-[10px] font-black uppercase tracking-widest ${stats.cumulativeSaving >= 0 ? 'text-emerald-600' : 'text-rose-600'}`}>
              Quỹ Tích Lũy Kỷ Luật
            </p>
            <h2 className={`text-3xl font-black mt-1 ${stats.cumulativeSaving >= 0 ? 'text-emerald-700' : 'text-rose-700'}`}>
              {stats.cumulativeSaving > 0 ? '+' : ''}{formatCurrency(stats.cumulativeSaving)}
            </h2>
            <div className={`mt-3 inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[10px] font-black border ${
              todaySaving >= 0 
                ? 'bg-emerald-500 text-white border-transparent' 
                : 'bg-rose-500 text-white border-transparent'
            }`}>
               <i className={`fas ${todaySaving >= 0 ? 'fa-plus-circle' : 'fa-minus-circle'}`}></i>
               Hôm nay: {todaySaving > 0 ? '+' : ''}{formatCurrency(todaySaving)}
            </div>
          </div>
          <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-xl shadow-lg ${
            stats.cumulativeSaving >= 0 ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'
          }`}>
            <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-piggy-bank' : 'fa-triangle-exclamation'}`}></i>
          </div>
        </div>

        <p className={`text-[11px] font-bold mt-5 leading-relaxed z-10 relative ${stats.cumulativeSaving >= 0 ? 'text-emerald-600/80' : 'text-rose-600/80'}`}>
          {savingAdvice()}
        </p>

        <i className={`fas ${stats.cumulativeSaving >= 0 ? 'fa-chart-area' : 'fa-fire'} absolute -right-4 -bottom-4 text-8xl opacity-5`}></i>
      </div>

      {/* Metric Cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col justify-center min-h-[100px]">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest z-10">Tiền mặt khả dụng</p>
          <p className="text-xl font-black text-slate-800 mt-1 z-10">{formatCurrency(stats.currentCash)}</p>
          <i className="fas fa-wallet absolute -right-3 -bottom-3 text-5xl text-slate-50 opacity-40 transform rotate-12"></i>
        </div>

        <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 relative overflow-hidden flex flex-col justify-center min-h-[100px]">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest z-10">Trong tài khoản</p>
          <p className="text-xl font-black text-slate-800 mt-1 z-10">{formatCurrency(stats.currentBank)}</p>
          <i className="fas fa-credit-card absolute -right-3 -bottom-3 text-5xl text-slate-50 opacity-40 transform -rotate-12"></i>
        </div>

        <div className="col-span-2 bg-slate-900 p-6 rounded-3xl shadow-xl text-white relative overflow-hidden">
          <div className="z-10 relative">
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Tổng tài sản ròng</p>
            <p className="text-4xl font-black mt-1 tracking-tighter">{formatCurrency(stats.total)}</p>
