              <div className="flex items-center gap-2">
                <h4 className="text-sm font-black text-slate-800">{user.name}</h4>
                {user.role === UserRole.ADMIN && <i className="fas fa-shield-alt text-amber-500 text-[10px]"></i>}
              </div>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">@{user.username} • {user.role === UserRole.ADMIN ? 'Quản trị viên' : 'Thành viên'}</p>
