          <div className="absolute -left-10 -bottom-10 w-32 h-32 bg-rose-500/10 rounded-full blur-3xl"></div>

          <div className="flex bg-white/5 p-1.5 rounded-2xl mb-8 relative z-10">
            <button 
              onClick={() => setIsLogin(true)}
