      if (users.find(u => u.username === cleanUser)) {
        setError('Tên đăng nhập đã tồn tại!');
        return;
      }
      const newUser: User = { 
        username: cleanUser, 
        password, 
        name, 
        role: UserRole.USER,
        createdAt: new Date().toISOString()
