interface Props {
  onLogin: (user: User) => void;
}

const Auth: React.FC<Props> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [isConnecting, setIsConnecting] = useState(false);

  useEffect(() => {
    const initAdmin = async () => {
      const users = await storageService.getUsers();
      if (!users.find(u => u.username === 'admin')) {
        await storageService.saveUser({
          username: 'admin',
          password: '123',
          name: 'Quản trị viên',
          role: UserRole.ADMIN,
          createdAt: new Date().toISOString()
        });
      }
    };
    initAdmin();
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const cleanUser = username.trim().toLowerCase();
    if (!cleanUser || !password || (!isLogin && !name)) {
      setError('Vui lòng nhập đầy đủ thông tin!');
      return;
    }

    setIsConnecting(true);
    // Giả lập thời gian kết nối server
    await new Promise(r => setTimeout(r, 1200));

    const users = await storageService.getUsers();

    if (isLogin) {
      const user = users.find(u => u.username === cleanUser && u.password === password);
      if (user) {
        onLogin(user);
      } else {
        setError('Tài khoản hoặc mật khẩu không chính xác!');
        setIsConnecting(false);
      }
    } else {
      if (users.find(u => u.username === cleanUser)) {
        setError('Tên đăng nhập đã tồn tại trên server!');
        setIsConnecting(false);
        return;
      }
      const newUser: User = { 
        username: cleanUser, 
        password, 
        name, 
        role: UserRole.USER,
        createdAt: new Date().toISOString()
      };
      await storageService.saveUser(newUser);
      onLogin(newUser);
    }
