/**
 * CLOUD API CLIENT V3.0 (Production Ready)
 * Hệ thống này được thiết kế để dễ dàng chuyển đổi từ Mock sang Real Backend.
 */
class CloudAPIClient {
  private baseURL = "https://api.cashflow-master.cloud/v3";
  private mockLatency = 1000;

  private async request(endpoint: string, options: RequestInit = {}) {
    // Trong môi trường Production, bạn sẽ dùng lệnh này:
    // return fetch(`${this.baseURL}${endpoint}`, options);

    // Hiện tại: Mô phỏng hành vi của Server
    console.log(`[CloudRequest] ${options.method || 'GET'} -> ${endpoint}`);
    await new Promise(resolve => setTimeout(resolve, Math.random() * 500 + this.mockLatency));
    return {
      ok: true,
      json: async () => {
        const key = endpoint.replace(/\//g, '_');
        const data = localStorage.getItem(`db${key}`);
        return data ? JSON.parse(data) : null;
      }
    };
  }

  // LẤY DỮ LIỆU THỊ TRƯỜNG THẬT (ONLINE)
  async getLiveMarketData() {
    try {
      // Gọi một API thật từ Internet
      const res = await fetch('https://api.coingecko.com/api/v3/simple/price?ids=bitcoin,ethereum,tether&vs_currencies=vnd');
      return await res.json();
    } catch (e) {
      return null;
    }
  }

  // QUẢN LÝ USER
  // Fixed: Renamed fetchUsers to getUsers to resolve errors in Auth.tsx and AdminPanel.tsx
  async getUsers(): Promise<User[]> {
    const data = localStorage.getItem('db_users');
    return data ? JSON.parse(data) : [];
  }

  // Fixed: Renamed syncUser to saveUser to resolve errors in Auth.tsx
  async saveUser(user: User) {
    const users = await this.getUsers();
    const index = users.findIndex(u => u.username === user.username);
    if (index > -1) users[index] = user;
    else users.push(user);
    localStorage.setItem('db_users', JSON.stringify(users));
  }

  // Fixed: Added updateUser method to resolve errors in AdminPanel.tsx
  async updateUser(user: User) {
    await this.saveUser(user);
  }

  // Fixed: Added deleteUser method to resolve errors in AdminPanel.tsx
  async deleteUser(username: string) {
    let users = await this.getUsers();
    users = users.filter(u => u.username !== username);
    localStorage.setItem('db_users', JSON.stringify(users));
    localStorage.removeItem(`db_transactions_${username}`);
    localStorage.removeItem(`db_settings_${username}`);
    localStorage.removeItem(`db_last_sync_${username}`);
  }

  // Fixed: Added wipeAllData method to resolve errors in AdminPanel.tsx
  async wipeAllData() {
    localStorage.clear();
  }

  // QUẢN LÝ DỮ LIỆU GIAO DỊCH
  async fetchUserData(username: string) {
    const trans = localStorage.getItem(`db_transactions_${username}`);
    const settings = localStorage.getItem(`db_settings_${username}`);
    return {
      transactions: trans ? JSON.parse(trans) : [],
      settings: settings ? JSON.parse(settings) : null
    };
  }

  async pushUserData(username: string, transactions: Transaction[], settings: Settings) {
    localStorage.setItem(`db_transactions_${username}`, JSON.stringify(transactions));
    localStorage.setItem(`db_settings_${username}`, JSON.stringify(settings));
    localStorage.setItem(`db_last_sync_${username}`, new Date().toISOString());
    return true;
  }

  getLastSync(username: string) {
    return localStorage.getItem(`db_last_sync_${username}`) || "Chưa có dữ liệu";
  }

  // HỆ THỐNG CONFIG
  getGlobalConfig() {
    const data = localStorage.getItem('db_sys_config');
    return data ? JSON.parse(data) : { aiActive: true, maintenance: false };
  }

  setGlobalConfig(config: any) {
    localStorage.setItem('db_sys_config', JSON.stringify(config));
  }
}

