    const syncData = async () => {
      setIsSyncing(true);
      const data = await storageService.fetchUserData(user.username);
      if (data.settings) setSettings(data.settings);
      setTransactions(data.transactions);
      setIsSyncing(false);
    };
    syncData();
    // Polling mỗi 60 giây để đảm bảo đồng bộ
    const poll = setInterval(syncData, 60000);
    return () => clearInterval(poll);
  }, [user]);

  // AUTOMATED PUSH (Đẩy dữ liệu lên Server mỗi khi có thay đổi)
  useEffect(() => {
