  createdAt?: string;
}

export interface Transaction {
  id: string;
  userId: string;
  date: string;
  content: string;
  type: TransactionType;
  source: PaymentSource;
  amount: number;
  isExcluded?: boolean; // Nếu true, không tính vào hạn mức chi tiêu hàng ngày
}

export interface Settings {
  userId: string;
  initialCash: number;
  initialBank: number;
  dailyCost: number;
}

export interface FinancialStats {
  currentCash: number;
  currentBank: number;
  total: number;
  survivalDays: number;
  totalIncome: number;
  totalExpense: number;
  todayExpense: number;
  cumulativeSaving: number;
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Transaction, TransactionType, PaymentSource, Settings, FinancialStats, User, UserRole } from './types';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Auth from './components/Auth';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('cashflow_current_user');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [settings, setSettings] = useState<Settings>({ userId: '', initialCash: 0, initialBank: 0, dailyCost: 0 });
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'admin'>('dashboard');
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  const [displayInitialCash, setDisplayInitialCash] = useState('');
  const [displayInitialBank, setDisplayInitialBank] = useState('');
  const [displayDailyCost, setDisplayDailyCost] = useState('');

  useEffect(() => {
    if (user) {
      const savedSettings = localStorage.getItem(`cashflow_settings_${user.username}`);
      const savedTrans = localStorage.getItem(`cashflow_transactions_${user.username}`);

      const loadedSettings = savedSettings ? JSON.parse(savedSettings) : { userId: user.username, initialCash: 0, initialBank: 0, dailyCost: 0 };
      setSettings(loadedSettings);
      setTransactions(savedTrans ? JSON.parse(savedTrans) : []);

      setDisplayInitialCash(loadedSettings.initialCash > 0 ? loadedSettings.initialCash.toLocaleString('vi-VN') : '');
      setDisplayInitialBank(loadedSettings.initialBank > 0 ? loadedSettings.initialBank.toLocaleString('vi-VN') : '');
      setDisplayDailyCost(loadedSettings.dailyCost > 0 ? loadedSettings.dailyCost.toLocaleString('vi-VN') : '');

      localStorage.setItem('cashflow_current_user', JSON.stringify(user));
    } else {
      setSettings({ userId: '', initialCash: 0, initialBank: 0, dailyCost: 0 });
      setTransactions([]);
      setActiveTab('dashboard');
      setDisplayInitialCash('');
      setDisplayInitialBank('');
      setDisplayDailyCost('');
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`cashflow_settings_${user.username}`, JSON.stringify(settings));
      localStorage.setItem(`cashflow_transactions_${user.username}`, JSON.stringify(transactions));
    }
  }, [settings, transactions, user]);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;

    // Chi tiêu hôm nay (Loại trừ các khoản isExcluded)
    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE && !t.isExcluded)
      .reduce((sum, t) => sum + t.amount, 0);

    let cumulativeSaving = 0;
    if (settings.dailyCost > 0) {
      const firstDateStr = transactions.length > 0 
        ? transactions.reduce((min, t) => t.date < min ? t.date : min, todayStr)
        : todayStr;

      const start = new Date(firstDateStr);
      const end = new Date(todayStr);
      const diffDays = Math.max(1, Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1);

      // Tích lũy = (Tổng hạn mức cho các ngày đã qua) - (Tổng chi tiêu thực tế NHƯNG loại trừ các khoản isExcluded)
      const totalDailyExpenseToSubtract = transactions
        .filter(t => t.type === TransactionType.EXPENSE && !t.isExcluded)
        .reduce((s, t) => s + t.amount, 0);

      cumulativeSaving = (diffDays * settings.dailyCost) - totalDailyExpenseToSubtract;
    }

    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    return {
      currentCash, currentBank, total, survivalDays,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense,
      cumulativeSaving
    };
  }, [transactions, settings]);

  const handleFormatInput = (value: string, setter: (v: string) => void, settingKey: keyof Settings) => {
    const numeric = Number(value.replace(/\D/g, ''));
    setter(numeric === 0 ? '' : numeric.toLocaleString('vi-VN'));
    setSettings(prev => ({ ...prev, [settingKey]: numeric }));
  };

  const handleResetSettings = () => {
    if (window.confirm("Bạn muốn reset các thiết lập mục tiêu về 0?")) {
      setSettings(prev => ({ ...prev, initialCash: 0, initialBank: 0, dailyCost: 0 }));
      setDisplayInitialCash('');
      setDisplayInitialBank('');
      setDisplayDailyCost('');
    }
  };

  const handleLogout = useCallback(() => {
    if (window.confirm("Bạn có chắc chắn muốn đăng xuất?")) {
      localStorage.removeItem('cashflow_current_user');
      setUser(null);
    }
  }, []);

  if (!user) {
    return <Auth onLogin={setUser} />;
  }

  return (
    <div className="h-screen flex flex-col bg-slate-50 font-sans overflow-hidden">
      <header className="flex-none bg-white border-b border-slate-100 px-5 pt-[env(safe-area-inset-top,1rem)] h-[calc(4.5rem+env(safe-area-inset-top,0px))] flex items-center justify-between z-50 glass-effect">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-100">
            <i className="fas fa-wallet text-white text-sm"></i>
          </div>
          <h1 className="text-xl font-black text-slate-800 tracking-tighter">CASHFLOW</h1>
        </div>

        <div className="flex items-center gap-2">
          {user.role === UserRole.ADMIN && (
            <button 
              onClick={() => setActiveTab('admin')}
              className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all ${activeTab === 'admin' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-600 border border-slate-100'}`}
            >
              <i className="fas fa-users-cog text-xs"></i>
            </button>
          )}
          <button 
            onClick={handleLogout}
            className="w-10 h-10 bg-slate-50 text-slate-400 rounded-xl flex items-center justify-center active:scale-90 border border-slate-100 hover:text-rose-500 transition-all shadow-sm"
          >
            <i className="fas fa-sign-out-alt text-xs"></i>
          </button>
        </div>
      </header>

      <main className={`flex-1 overflow-y-auto ${activeTab === 'admin' ? 'overflow-hidden' : 'p-4'}`}>
        <div className={`max-w-xl mx-auto h-full ${activeTab === 'admin' ? '' : 'space-y-6 pb-24'}`}>
          {activeTab === 'dashboard' && (
            <>
               <div className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100 animate-in fade-in slide-in-from-top-4 duration-500">
                  <div className="flex justify-between items-center mb-6">
                    <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                       THIẾT LẬP MỤC TIÊU
                    </p>
                    <button onClick={handleResetSettings} className="text-[10px] font-black text-rose-400 uppercase tracking-widest hover:text-rose-600 transition-colors">RESET</button>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase">TIỀN MẶT</label>
                      <input 
                        type="text" 
                        inputMode="numeric"
                        placeholder="0"
                        value={displayInitialCash} 
                        onChange={e => handleFormatInput(e.target.value, setDisplayInitialCash, 'initialCash')} 
                        className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:bg-white transition-all"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] text-slate-400 font-black ml-1 uppercase">TÀI KHOẢN</label>
                      <input 
                        type="text" 
                        inputMode="numeric"
                        placeholder="0"
                        value={displayInitialBank} 
                        onChange={e => handleFormatInput(e.target.value, setDisplayInitialBank, 'initialBank')} 
                        className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-black outline-none border border-transparent focus:bg-white transition-all"
                      />
                    </div>
                    <div className="col-span-2 space-y-1.5">
                      <div className="flex justify-between px-1">
                        <label className="text-[10px] text-slate-400 font-black uppercase">HẠN MỨC / NGÀY</label>
                        <span className="text-[10px] font-black text-indigo-500">{settings.dailyCost.toLocaleString('vi-VN')}đ</span>
                      </div>
                      <input 
                        type="text" 
                        inputMode="numeric"
                        placeholder="VD: 80000" 
                        value={displayDailyCost} 
                        onChange={e => handleFormatInput(e.target.value, setDisplayDailyCost, 'dailyCost')} 
                        className="w-full bg-slate-50 p-5 rounded-2xl text-xl font-black text-slate-700 outline-none border border-transparent focus:bg-white transition-all"
                      />
                    </div>
                  </div>
               </div>
               <Dashboard stats={stats} transactions={transactions} settings={settings} user={user} onLogout={handleLogout} />
            </>
          )}

          {activeTab === 'transactions' && (
            <div className="space-y-4">
              <TransactionForm 
                onAdd={(t) => {
                  setTransactions([{...t, id: Date.now().toString(), userId: user.username}, ...transactions]);
                }} 
                editingTransaction={editingTransaction}
                onUpdate={(updated) => {
                  setTransactions(transactions.map(t => t.id === updated.id ? updated : t));
                  setEditingTransaction(null);
                }}
                onCancelEdit={() => setEditingTransaction(null)}
              />
              <TransactionList 
                transactions={transactions} 
                settings={settings}
                onDelete={(id) => {
                  if (window.confirm('Xóa giao dịch này?')) setTransactions(transactions.filter(t => t.id !== id));
                }}
                onEdit={(t) => {
                  setEditingTransaction(t);
                  document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' });
                }}
              />
            </div>
          )}

          {activeTab === 'admin' && user.role === UserRole.ADMIN && (
            <div className="h-full p-4 overflow-hidden">
               <AdminPanel onClose={() => setActiveTab('dashboard')} />
            </div>
          )}
        </div>
      </main>

      <nav className="flex-none bg-white border-t border-slate-100 flex justify-around items-center px-6 pb-[env(safe-area-inset-bottom,1.5rem)] h-[calc(5.5rem+env(safe-area-inset-bottom,0px))] z-50 glass-effect">
        {[
          { id: 'dashboard', icon: 'fa-chart-pie', label: 'TỔNG QUAN' },
          { id: 'transactions', icon: 'fa-exchange-alt', label: 'GIAO DỊCH' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex flex-col items-center gap-1.5 transition-all duration-300 relative group ${
              activeTab === tab.id ? 'text-indigo-600 scale-110' : 'text-slate-400'
            }`}
          >
            {activeTab === tab.id && <span className="absolute -top-4 w-1.5 h-1.5 bg-indigo-600 rounded-full"></span>}
            <i className={`fas ${tab.icon} text-lg`}></i>
            <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { ComposedChart, Area, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Line, ReferenceLine } from 'recharts';
import { FinancialStats, Transaction, TransactionType, Settings, User, UserRole } from '../types';

interface Props {
  stats: FinancialStats;
  transactions: Transaction[];
  settings: Settings;
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ stats, transactions, settings, user, onLogout }) => {
  const chartData = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      days.push(d.toISOString().split('T')[0]);
    }

    return days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const expense = dayTransactions
        .filter(t => t.type === TransactionType.EXPENSE)
        .reduce((sum, t) => sum + t.amount, 0);
      const income = dayTransactions
        .filter(t => t.type === TransactionType.INCOME)
        .reduce((sum, t) => sum + t.amount, 0);

      return {
        date: date.split('-').slice(1).reverse().join('/'),
        expense,
        income,
        target: settings.dailyCost,
        saving: settings.dailyCost - expense
      };
    });
  }, [transactions, settings.dailyCost]);

  const formatCurrency = (val: number) => val.toLocaleString('vi-VN') + 'đ';

  const todaySaving = settings.dailyCost - stats.todayExpense;

  // Tính % để lấp đầy "bể nước"
  // Giả sử mục tiêu là có 1 khoản tiết kiệm bằng 30 ngày chi tiêu để coi là "đầy" bể nước nhỏ
  const targetSavingsPool = settings.dailyCost * 30 || 1000000;
  const fillPercentage = Math.min(100, Math.max(0, (stats.cumulativeSaving / targetSavingsPool) * 100));

  const savingAdvice = () => {
    if (settings.dailyCost === 0) return "Hãy thiết lập mục tiêu chi tiêu mỗi ngày!";
    if (todaySaving > 0) return "Bạn đang quản lý chi tiêu rất tốt hôm nay! 🌟";
    return "Hãy chú ý hạn mức chi tiêu để bảo vệ khoản tích lũy! 🎯";
  };

  return (
    <div className="space-y-5 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-10">

      {/* KHOẢN NHO NHỎ - WATER TANK UI */}
      <div className="relative p-6 rounded-[32px] bg-white border border-slate-100 shadow-xl overflow-hidden min-h-[180px] flex items-center">
        {/* Water Level Background */}
        <div 
          className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-emerald-400/30 to-emerald-200/10 transition-all duration-1000 ease-out z-0"
          style={{ height: `${fillPercentage}%` }}
        >
          {/* Wave Animation Effect */}
          <div className="absolute top-0 left-0 w-full h-4 -translate-y-full opacity-50">
             <svg className="w-full h-full" viewBox="0 0 100 20" preserveAspectRatio="none">
                <path d="M0 10 Q 25 20 50 10 T 100 10 V 20 H 0 Z" fill="currentColor" className="text-emerald-300">
                  <animate attributeName="d" dur="3s" repeatCount="indefinite" values="M0 10 Q 25 20 50 10 T 100 10 V 20 H 0 Z; M0 10 Q 25 0 50 10 T 100 10 V 20 H 0 Z; M0 10 Q 25 20 50 10 T 100 10 V 20 H 0 Z" />
                </path>
             </svg>
          </div>
        </div>

        <div className="flex justify-between items-start z-10 relative w-full">
          <div className="flex-1">
            <p className="text-[10px] font-black uppercase tracking-widest text-emerald-600 mb-1">
              KHOẢN NHO NHỎ (TÍCH LŨY)
            </p>
            <h2 className="text-4xl font-black text-emerald-800 tracking-tighter">
              {formatCurrency(stats.cumulativeSaving)}
            </h2>
            <div className="mt-4 flex flex-wrap gap-2">
               <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black bg-emerald-500/10 text-emerald-700 border border-emerald-200">
                  <i className="fas fa-droplet text-[8px]"></i>
                  {fillPercentage.toFixed(1)}% Bể chứa
               </div>
               <div className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-[10px] font-black bg-white text-emerald-700 border border-emerald-100 shadow-sm">
                  <i className="fas fa-plus-circle"></i>
                  Hôm nay: {formatCurrency(todaySaving)}
               </div>
            </div>
            <p className="text-[11px] font-bold mt-4 text-emerald-700/80 leading-relaxed italic">
              {savingAdvice()}
            </p>
          </div>
          <div className="w-14 h-14 rounded-2xl bg-emerald-500 flex items-center justify-center text-2xl text-white shadow-lg shadow-emerald-200 animate-pulse-slow">
            <i className="fas fa-piggy-bank"></i>
          </div>
        </div>
      </div>

      {/* Vốn và tài sản */}
      <div className="grid grid-cols-2 gap-4">
        <div className="bg-white p-5 rounded-[32px] shadow-sm border border-slate-100 relative overflow-hidden">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">VỐN TIỀN MẶT</p>
          <p className="text-xl font-black text-slate-800 mt-1">{formatCurrency(stats.currentCash)}</p>
        </div>

        <div className="bg-white p-5 rounded-[32px] shadow-sm border border-slate-100 relative overflow-hidden">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">TRONG TÀI KHOẢN</p>
          <p className="text-xl font-black text-slate-800 mt-1">{formatCurrency(stats.currentBank)}</p>
        </div>

        <div className="col-span-2 bg-[#0c1222] p-6 rounded-[32px] shadow-xl text-white relative overflow-hidden">
          <div className="z-10 relative">
            <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">TÀI SẢN RÒNG HIỆN CÓ</p>
            <p className="text-5xl font-black mt-2 tracking-tighter">{formatCurrency(stats.total)}</p>
            <div className="mt-8 flex items-center gap-10">
               <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">KHẢ NĂNG SINH TỒN</span>
                  <span className="text-lg font-black text-indigo-400">{stats.survivalDays} <span className="text-[10px] text-white/40 uppercase">Ngày</span></span>
               </div>
               <div className="w-[1px] h-8 bg-white/10"></div>
               <div className="flex flex-col">
                  <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">CHI HÔM NAY</span>
                  <span className="text-lg font-black text-rose-400">{formatCurrency(stats.todayExpense)}</span>
               </div>
            </div>
          </div>
        </div>
      </div>

      {/* Phân tích biểu đồ */}
      <div className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100">
        <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">BIỂU ĐỒ CHI TIÊU KỶ LUẬT</h3>
        <div className="h-48 w-full">
          {transactions.length > 0 ? (
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fontSize: 8, fill: '#94a3b8', fontWeight: 800}} dy={10} />
                <YAxis hide domain={[0, 'auto']} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)', fontSize: '10px', fontWeight: 800 }}
                  formatter={(value: number) => [formatCurrency(value), '']}
                />
                <Area type="monotone" dataKey="target" fill="#f5f3ff" stroke="none" fillOpacity={0.5} />
                <Bar dataKey="expense" fill="#f43f5e" radius={[4, 4, 0, 0]} barSize={10} />
                <Line type="monotone" dataKey="target" stroke="#818cf8" strokeWidth={2} strokeDasharray="5 5" dot={false} />
              </ComposedChart>
            </ResponsiveContainer>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-2 opacity-30">
               <i className="fas fa-chart-line text-2xl"></i>
               <p className="text-[9px] font-black uppercase">Chưa có dữ liệu</p>
            </div>
          )}
        </div>
      </div>

      {/* HỒ SƠ TÀI KHOẢN */}
      <div className="bg-white p-6 rounded-[32px] shadow-sm border border-slate-100">
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">HỒ SƠ TÀI KHOẢN</p>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className={`w-14 h-14 text-white rounded-[20px] flex items-center justify-center text-xl font-black shadow-lg ${user.role === UserRole.ADMIN ? 'bg-amber-500' : 'bg-indigo-600'}`}>
              {user.name.charAt(0).toUpperCase()}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h4 className="text-sm font-black text-slate-800">{user.name}</h4>
                {user.role === UserRole.ADMIN && <i className="fas fa-shield-alt text-amber-500 text-[10px]"></i>}
              </div>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">
                @{user.username} • <span className={user.role === UserRole.ADMIN ? 'text-amber-500' : 'text-indigo-500'}>{user.role === UserRole.ADMIN ? 'QUẢN TRỊ VIÊN' : 'THÀNH VIÊN'}</span>
              </p>
            </div>
          </div>
          <button 
            type="button"
            onClick={onLogout}
            className="flex flex-col items-center gap-1 group"
          >
            <div className="w-10 h-10 bg-rose-50 text-rose-500 rounded-xl flex items-center justify-center border border-rose-100 group-hover:bg-rose-500 group-hover:text-white transition-all">
              <i className="fas fa-power-off text-sm"></i>
            </div>
            <span className="text-[8px] font-black text-rose-500 uppercase tracking-widest">ĐĂNG XUẤT</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, PaymentSource } from '../types';

interface Props {
  onAdd: (t: Omit<Transaction, 'id' | 'userId'>) => void;
  editingTransaction?: Transaction | null;
  onUpdate?: (t: Transaction) => void;
  onCancelEdit?: () => void;
}

const TransactionForm: React.FC<Props> = ({ onAdd, editingTransaction, onUpdate, onCancelEdit }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [content, setContent] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [source, setSource] = useState<PaymentSource>(PaymentSource.CASH);
  const [displayAmount, setDisplayAmount] = useState('');
  const [isExcluded, setIsExcluded] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDate(editingTransaction.date);
      setContent(editingTransaction.content);
      setType(editingTransaction.type);
      setSource(editingTransaction.source);
      setDisplayAmount(editingTransaction.amount.toLocaleString('vi-VN'));
      setIsExcluded(!!editingTransaction.isExcluded);
    } else {
      resetForm();
    }
  }, [editingTransaction]);

  const resetForm = () => {
    setDate(new Date().toISOString().split('T')[0]);
    setContent('');
    setType(TransactionType.EXPENSE);
    setSource(PaymentSource.CASH);
    setDisplayAmount('');
    setIsExcluded(false);
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/\D/g, '');
    const cleanValue = rawValue.replace(/^0+/, '');
    if (cleanValue === '') {
      setDisplayAmount('');
      return;
    }
    const formattedValue = Number(cleanValue).toLocaleString('vi-VN');
    setDisplayAmount(formattedValue);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = Number(displayAmount.replace(/\./g, ''));
    if (!content || numericAmount <= 0) {
      alert("Vui lòng nhập đầy đủ nội dung và số tiền!");
      return;
    }

    const transactionData = {
      date,
      content,
      type,
      source,
      amount: numericAmount,
      isExcluded: type === TransactionType.EXPENSE ? isExcluded : false // Chỉ cho phép exclude các khoản Chi
    };

    if (editingTransaction && onUpdate) {
      onUpdate({
        ...editingTransaction,
        ...transactionData
      });
    } else {
      onAdd(transactionData);
    }
    resetForm();
  };

  return (
    <div className={`p-6 rounded-3xl shadow-xl border transition-all duration-300 ${
      editingTransaction 
        ? 'bg-amber-50 border-amber-300 ring-4 ring-amber-100' 
        : 'bg-white border-slate-100'
    }`}>
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-lg font-black text-slate-800 flex items-center gap-2">
          <i className={`fas ${editingTransaction ? 'fa-pen-to-square text-amber-500' : 'fa-plus-circle text-indigo-600'}`}></i>
          {editingTransaction ? 'CẬP NHẬT GIAO DỊCH' : 'THÊM MỚI'}
        </h3>
        {editingTransaction && (
          <button 
            onClick={onCancelEdit}
            className="text-[10px] font-black bg-rose-100 text-rose-600 px-3 py-1.5 rounded-full hover:bg-rose-200 transition-colors uppercase tracking-widest"
          >
            Hủy Sửa
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <div className="col-span-2 sm:col-span-1">
            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1 ml-1">Ngày tháng</label>
            <input 
              type="date" 
              value={date} 
              onChange={(e) => setDate(e.target.value)}
              className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            />
          </div>
          <div className="col-span-2 sm:col-span-1">
            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1 ml-1">Nội dung</label>
            <input 
              type="text" 
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Mua sắm, ăn uống..."
              className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-3 text-sm focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1 ml-1">Loại</label>
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button 
                type="button"
                onClick={() => setType(TransactionType.EXPENSE)}
                className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${type === TransactionType.EXPENSE ? 'bg-white shadow-sm text-rose-600' : 'text-slate-500'}`}
              >
                Chi tiêu
              </button>
              <button 
                type="button"
                onClick={() => setType(TransactionType.INCOME)}
                className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${type === TransactionType.INCOME ? 'bg-white shadow-sm text-emerald-600' : 'text-slate-500'}`}
              >
                Thu nhập
              </button>
            </div>
          </div>
          <div>
            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-1 ml-1">Nguồn</label>
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button 
                type="button"
                onClick={() => setSource(PaymentSource.CASH)}
                className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${source === PaymentSource.CASH ? 'bg-white shadow-sm text-amber-600' : 'text-slate-500'}`}
              >
                Tiền mặt
              </button>
              <button 
                type="button"
                onClick={() => setSource(PaymentSource.BANK)}
                className={`flex-1 py-2 text-xs font-bold rounded-lg transition-all ${source === PaymentSource.BANK ? 'bg-white shadow-sm text-blue-600' : 'text-slate-500'}`}
              >
                ATM
              </button>
            </div>
          </div>
        </div>

        {type === TransactionType.EXPENSE && (
           <div className="bg-slate-50 p-3 rounded-xl border border-slate-100">
              <label className="flex items-center gap-3 cursor-pointer">
                 <input 
                    type="checkbox" 
                    checked={isExcluded} 
                    onChange={(e) => setIsExcluded(e.target.checked)}
                    className="w-5 h-5 rounded-md border-slate-300 text-indigo-600 focus:ring-indigo-500"
                 />
                 <div className="flex flex-col">
                    <span className="text-xs font-black text-slate-700 uppercase tracking-tighter">Giao dịch đặc biệt</span>
                    <span className="text-[10px] text-slate-400 leading-none">Không tính vào hạn mức chi tiêu hàng ngày</span>
