          {/* Water Tank Background Logic */}
          <div 
            className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-blue-500/40 via-blue-400/20 to-transparent transition-all duration-[2000ms] ease-out z-0"
            style={{ height: `${fillPercentage}%` }}
          >
            {/* Wave Animation */}
            <div className="absolute top-0 left-0 w-full h-8 -translate-y-1/2 overflow-hidden">
               <svg className="w-[200%] h-full animate-wave opacity-60" viewBox="0 0 100 20" preserveAspectRatio="none">
                  <path d="M0 10 Q 25 20 50 10 T 100 10 T 150 10 T 200 10 V 20 H 0 Z" fill="#3b82f6" />
               </svg>
            </div>
          </div>

          <div className="z-10 relative flex justify-between">
            <div>
              <p className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-600 mb-1">DÒNG TIỀN TÍCH LŨY</p>
              <h2 className="text-4xl font-black text-slate-800 tracking-tighter drop-shadow-sm">
                {formatCurrency(stats.cumulativeSaving)}
              </h2>
            </div>
            <div className="text-right">
              <span className="text-2xl font-black text-blue-600">{fillPercentage.toFixed(1)}%</span>
              <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Lấp đầy</p>
