import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, PaymentSource } from '../types';

interface Props {
  onAdd: (t: Omit<Transaction, 'id' | 'userId'>) => void;
  editingTransaction?: Transaction | null;
  onUpdate?: (t: Transaction) => void;
  onCancelEdit?: () => void;
}

const TransactionForm: React.FC<Props> = ({ onAdd, editingTransaction, onUpdate, onCancelEdit }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [content, setContent] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [source, setSource] = useState<PaymentSource>(PaymentSource.CASH);
  const [displayAmount, setDisplayAmount] = useState('');
  const [isExcluded, setIsExcluded] = useState(false);
  const [isFromSavings, setIsFromSavings] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDate(editingTransaction.date);
      setContent(editingTransaction.content);
      setType(editingTransaction.type);
      setSource(editingTransaction.source);
      setDisplayAmount(editingTransaction.amount.toLocaleString('vi-VN'));
      setIsExcluded(!!editingTransaction.isExcluded);
      setIsFromSavings(!!editingTransaction.isFromSavings);
    } else {
      resetForm();
    }
  }, [editingTransaction]);

  const resetForm = () => {
    setDate(new Date().toISOString().split('T')[0]);
    setContent('');
    setType(TransactionType.EXPENSE);
    setSource(PaymentSource.CASH);
    setDisplayAmount('');
    setIsExcluded(false);
    setIsFromSavings(false);
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/\D/g, '');
    setDisplayAmount(rawValue ? Number(rawValue).toLocaleString('vi-VN') : '');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = Number(displayAmount.replace(/\./g, ''));
    if (!content || numericAmount <= 0) return alert("Vui lòng nhập đủ thông tin!");

    const data = {
      date, content, type, source, 
      amount: numericAmount, 
      isExcluded: type === TransactionType.EXPENSE ? isExcluded : false,
      isFromSavings: type === TransactionType.EXPENSE ? isFromSavings : false
    };

    if (editingTransaction && onUpdate) onUpdate({ ...editingTransaction, ...data });
    else onAdd(data);
    resetForm();
  };

  return (
    <div className={`p-6 rounded-3xl shadow-xl border transition-all ${editingTransaction ? 'bg-amber-50 border-amber-300' : 'bg-white border-slate-100'}`}>
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-lg font-black text-slate-800 flex items-center gap-2">
          <i className={`fas ${editingTransaction ? 'fa-pen-to-square' : 'fa-plus-circle text-indigo-600'}`}></i>
          {editingTransaction ? 'CẬP NHẬT' : 'GIAO DỊCH MỚI'}
        </h3>
        {editingTransaction && <button onClick={onCancelEdit} className="text-[10px] font-black text-rose-500 uppercase">Hủy</button>}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <input type="date" value={date} onChange={e => setDate(e.target.value)} className="bg-slate-50 p-3 rounded-xl text-sm border-none focus:ring-2 focus:ring-indigo-500 outline-none" />
          <input type="text" value={content} onChange={e => setContent(e.target.value)} placeholder="Nội dung..." className="bg-slate-50 p-3 rounded-xl text-sm border-none focus:ring-2 focus:ring-indigo-500 outline-none" />
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div className="flex bg-slate-100 p-1 rounded-xl">
            {[TransactionType.EXPENSE, TransactionType.INCOME].map(t => (
              <button key={t} type="button" onClick={() => setType(t)} className={`flex-1 py-2 text-[10px] font-black rounded-lg ${type === t ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400'}`}>{t.toUpperCase()}</button>
            ))}
          </div>
          <div className="flex bg-slate-100 p-1 rounded-xl">
            {[PaymentSource.CASH, PaymentSource.BANK].map(s => (
              <button key={s} type="button" onClick={() => setSource(s)} className={`flex-1 py-2 text-[10px] font-black rounded-lg ${source === s ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400'}`}>{s.toUpperCase()}</button>
            ))}
          </div>
        </div>

        {type === TransactionType.EXPENSE && (
          <div className="grid grid-cols-2 gap-3">
            <button 
              type="button" 
              onClick={() => { setIsExcluded(!isExcluded); if(!isExcluded) setIsFromSavings(false); }}
              className={`p-3 rounded-xl border text-[10px] font-black transition-all flex items-center justify-center gap-2 ${isExcluded ? 'bg-amber-500 text-white border-amber-600 shadow-lg shadow-amber-100' : 'bg-slate-50 text-slate-400 border-slate-100'}`}
            >
              <i className="fas fa-tag"></i> ĐẶC BIỆT
            </button>
            <button 
              type="button" 
              onClick={() => { setIsFromSavings(!isFromSavings); if(!isFromSavings) setIsExcluded(false); }}
              className={`p-3 rounded-xl border text-[10px] font-black transition-all flex items-center justify-center gap-2 ${isFromSavings ? 'bg-blue-500 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-slate-50 text-slate-400 border-slate-100'}`}
            >
              <i className="fas fa-droplet"></i> TRỪ TÍCH LŨY
            </button>
          </div>
        )}

        <input type="text" inputMode="numeric" value={displayAmount} onChange={handleAmountChange} placeholder="0đ" className={`w-full text-4xl font-black text-center py-5 bg-slate-50 rounded-2xl outline-none ${type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'}`} />

        <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black shadow-xl active:scale-95 transition-all">HOÀN TẤT</button>
      </form>
    </div>
  );
};

export default TransactionForm;

