import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, PaymentSource } from '../types';

interface Props {
  onAdd: (t: Omit<Transaction, 'id' | 'userId'>) => void;
  editingTransaction?: Transaction | null;
  onUpdate?: (t: Transaction) => void;
  onCancelEdit?: () => void;
}

const TransactionForm: React.FC<Props> = ({ onAdd, editingTransaction, onUpdate, onCancelEdit }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [content, setContent] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [source, setSource] = useState<PaymentSource>(PaymentSource.CASH);
  const [displayAmount, setDisplayAmount] = useState('');
  const [isExcluded, setIsExcluded] = useState(false);
  const [isFromSavings, setIsFromSavings] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDate(editingTransaction.date);
      setContent(editingTransaction.content);
      setType(editingTransaction.type);
      setSource(editingTransaction.source);
      setDisplayAmount(editingTransaction.amount.toLocaleString('vi-VN'));
      setIsExcluded(!!editingTransaction.isExcluded);
      setIsFromSavings(!!editingTransaction.isFromSavings);
    } else {
      resetForm();
    }
  }, [editingTransaction]);

  const resetForm = () => {
    setDate(new Date().toISOString().split('T')[0]);
    setContent('');
    setType(TransactionType.EXPENSE);
    setSource(PaymentSource.CASH);
    setDisplayAmount('');
    setIsExcluded(false);
    setIsFromSavings(false);
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/\D/g, '');
    setDisplayAmount(rawValue ? Number(rawValue).toLocaleString('vi-VN') : '');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = Number(displayAmount.replace(/\D/g, ''));
    if (!content || numericAmount <= 0) return alert("Vui lòng nhập đầy đủ thông tin!");

    const data = {
      date, content, type, source, 
      amount: numericAmount, 
      isExcluded: type === TransactionType.EXPENSE ? isExcluded : false,
      isFromSavings: type === TransactionType.EXPENSE ? isFromSavings : false
    };

    if (editingTransaction && onUpdate) onUpdate({ ...editingTransaction, ...data });
    else onAdd(data);
    resetForm();
  };

  return (
    <div className={`p-8 rounded-[40px] shadow-2xl border transition-all duration-500 ${editingTransaction ? 'bg-amber-50 border-amber-200' : 'bg-white border-slate-100'}`}>
      <div className="flex justify-between items-center mb-8">
        <h3 className="text-xl font-black text-slate-800 flex items-center gap-3">
          <div className={`w-10 h-10 rounded-2xl flex items-center justify-center text-white ${editingTransaction ? 'bg-amber-500' : 'bg-indigo-600'}`}>
             <i className={`fas ${editingTransaction ? 'fa-pen-nib' : 'fa-plus'}`}></i>
          </div>
          {editingTransaction ? 'CẬP NHẬT GIAO DỊCH' : 'GIAO DỊCH MỚI'}
        </h3>
        {editingTransaction && (
           <button onClick={onCancelEdit} className="text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-rose-500">Hủy bỏ</button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-1.5">
             <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Ngày tháng</label>
             <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-bold border-none outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
          <div className="space-y-1.5">
             <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Nội dung</label>
             <input type="text" value={content} onChange={e => setContent(e.target.value)} placeholder="VD: Ăn sáng..." className="w-full bg-slate-50 p-4 rounded-2xl text-sm font-bold border-none outline-none focus:ring-2 focus:ring-indigo-500" />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="bg-slate-100 p-1.5 rounded-2xl flex gap-1">
            {[TransactionType.EXPENSE, TransactionType.INCOME].map(t => (
              <button key={t} type="button" onClick={() => setType(t)} className={`flex-1 py-3 text-[10px] font-black rounded-xl transition-all ${type === t ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400'}`}>{t.toUpperCase()}</button>
            ))}
          </div>
          <div className="bg-slate-100 p-1.5 rounded-2xl flex gap-1">
            {[PaymentSource.CASH, PaymentSource.BANK].map(s => (
              <button key={s} type="button" onClick={() => setSource(s)} className={`flex-1 py-3 text-[10px] font-black rounded-xl transition-all ${source === s ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400'}`}>{s.toUpperCase()}</button>
            ))}
          </div>
        </div>

        {type === TransactionType.EXPENSE && (
          <div className="flex gap-4">
            <button 
              type="button" 
              onClick={() => { setIsExcluded(!isExcluded); if(!isExcluded) setIsFromSavings(false); }}
              className={`flex-1 p-4 rounded-2xl border-2 text-[10px] font-black transition-all flex flex-col items-center gap-2 ${isExcluded ? 'bg-amber-500 text-white border-amber-600 shadow-lg shadow-amber-200' : 'bg-slate-50 text-slate-400 border-transparent hover:border-slate-200'}`}
            >
              <i className="fas fa-tag text-sm"></i> ĐẶC BIỆT
            </button>
            <button 
              type="button" 
              onClick={() => { setIsFromSavings(!isFromSavings); if(!isFromSavings) setIsExcluded(false); }}
              className={`flex-1 p-4 rounded-2xl border-2 text-[10px] font-black transition-all flex flex-col items-center gap-2 ${isFromSavings ? 'bg-blue-600 text-white border-blue-700 shadow-lg shadow-blue-200' : 'bg-slate-50 text-slate-400 border-transparent hover:border-slate-200'}`}
            >
              <i className="fas fa-droplet text-sm"></i> TRỪ TÍCH LŨY
            </button>
          </div>
        )}

        <div className="relative group">
           <label className="absolute left-1/2 -top-2.5 -translate-x-1/2 bg-white px-3 text-[9px] font-black text-slate-400 uppercase tracking-[0.3em]">SỐ TIỀN GIAO DỊCH</label>
           <input type="text" inputMode="numeric" value={displayAmount} onChange={handleAmountChange} placeholder="0đ" className={`w-full text-5xl font-black text-center py-8 bg-slate-50 rounded-[32px] border-2 border-transparent outline-none focus:bg-white focus:border-indigo-100 transition-all ${type === TransactionType.INCOME ? 'text-emerald-500' : 'text-rose-500'}`} />
        </div>

        <button type="submit" className={`w-full py-5 rounded-[24px] font-black text-white shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 ${editingTransaction ? 'bg-amber-500 shadow-amber-200' : 'bg-indigo-600 shadow-indigo-200'}`}>
          <i className={`fas ${editingTransaction ? 'fa-save' : 'fa-check-circle'}`}></i>
          {editingTransaction ? 'LƯU THAY ĐỔI' : 'HOÀN TẤT GIAO DỊCH'}
        </button>
      </form>
    </div>
  );
};

export default TransactionForm;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Transaction, TransactionType, PaymentSource, Settings, FinancialStats, User, UserRole } from './types';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Auth from './components/Auth';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('cashflow_current_user');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [settings, setSettings] = useState<Settings>({ userId: '', initialCash: 0, initialBank: 0, dailyCost: 0 });
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'admin'>('dashboard');
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  useEffect(() => {
    if (user) {
      const savedSettings = localStorage.getItem(`cashflow_settings_${user.username}`);
      const savedTrans = localStorage.getItem(`cashflow_transactions_${user.username}`);

      const loadedSettings = savedSettings ? JSON.parse(savedSettings) : { userId: user.username, initialCash: 0, initialBank: 0, dailyCost: 0 };
      setSettings(loadedSettings);
      setTransactions(savedTrans ? JSON.parse(savedTrans) : []);

      localStorage.setItem('cashflow_current_user', JSON.stringify(user));
    } else {
      setSettings({ userId: '', initialCash: 0, initialBank: 0, dailyCost: 0 });
      setTransactions([]);
      setActiveTab('dashboard');
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`cashflow_settings_${user.username}`, JSON.stringify(settings));
      localStorage.setItem(`cashflow_transactions_${user.username}`, JSON.stringify(transactions));
    }
  }, [settings, transactions, user]);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;

    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE && !t.isExcluded && !t.isFromSavings)
      .reduce((sum, t) => sum + t.amount, 0);

    let cumulativeSaving = 0;
    if (settings.dailyCost > 0) {
      const firstDateStr = transactions.length > 0 
        ? transactions.reduce((min, t) => t.date < min ? t.date : min, todayStr)
        : todayStr;
      const start = new Date(firstDateStr);
      const end = new Date(todayStr);
      const diffDays = Math.max(1, Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1);

      const normalExpenses = transactions
        .filter(t => t.type === TransactionType.EXPENSE && !t.isExcluded && !t.isFromSavings)
        .reduce((s, t) => s + t.amount, 0);

      const spentFromSavings = transactions
        .filter(t => t.type === TransactionType.EXPENSE && t.isFromSavings)
        .reduce((s, t) => s + t.amount, 0);

      cumulativeSaving = (diffDays * settings.dailyCost) - normalExpenses - spentFromSavings;
    }

    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    return {
      currentCash, currentBank, total, survivalDays,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense,
      cumulativeSaving
    };
  }, [transactions, settings]);

  const handleLogout = useCallback(() => {
    if (window.confirm("Thoát phiên làm việc an toàn?")) {
      localStorage.removeItem('cashflow_current_user');
      setUser(null);
    }
  }, []);

  const handleUpdateTransactionStates = (id: string, updates: Partial<Transaction>) => {
    setTransactions(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t));
  };

  const handleAmountInput = (value: string, key: keyof Settings) => {
    const numeric = Number(value.replace(/\D/g, ''));
    setSettings(prev => ({ ...prev, [key]: numeric }));
  };

  if (!user) return <Auth onLogin={setUser} />;

  return (
    <div className="h-screen flex flex-col bg-[#f8fafc] font-sans overflow-hidden">
      <header className="flex-none bg-white/80 backdrop-blur-2xl border-b border-slate-100 px-4 h-14 flex items-center justify-between z-50">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-100 rotate-3">
            <i className="fas fa-layer-group text-white text-[10px]"></i>
          </div>
          <div>
            <h1 className="text-base font-black text-slate-800 tracking-tighter leading-none">CASH<span className="text-indigo-600">FLOW</span></h1>
            <p className="text-[7px] font-black text-slate-400 uppercase tracking-widest">Version 2.0 Mini</p>
          </div>
        </div>

        <div className="flex items-center gap-1.5">
          {user.role === UserRole.ADMIN && (
            <button 
              onClick={() => setActiveTab('admin')}
              className={`w-8 h-8 rounded-lg flex items-center justify-center transition-all ${activeTab === 'admin' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-600 border border-slate-100'}`}
            >
              <i className="fas fa-cog text-[10px]"></i>
            </button>
          )}
          <button onClick={handleLogout} className="w-8 h-8 bg-slate-50 text-slate-400 rounded-lg flex items-center justify-center active:scale-90 border border-slate-100"><i className="fas fa-power-off text-[10px]"></i></button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-3 custom-scrollbar">
        <div className="max-w-sm mx-auto space-y-4 pb-24">
          {activeTab === 'dashboard' && (
            <>
               <div className="bg-white p-5 rounded-3xl shadow-sm border border-slate-100 animate-in fade-in slide-in-from-top-4 duration-500">
                  <div className="flex justify-between items-center mb-5">
                    <p className="text-[8px] font-black text-slate-400 uppercase tracking-[0.2em]">THIẾT LẬP MỤC TIÊU</p>
                    <button onClick={() => setSettings(p => ({...p, initialCash:0, initialBank:0, dailyCost:0}))} className="text-[8px] font-black text-rose-500 uppercase tracking-widest border-b border-rose-100">Reset</button>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                      <label className="text-[8px] text-slate-400 font-black uppercase ml-1">TIỀN MẶT</label>
                      <input 
                        type="text" 
                        inputMode="numeric"
                        value={settings.initialCash.toLocaleString('vi-VN')} 
                        onChange={e => handleAmountInput(e.target.value, 'initialCash')} 
                        className="w-full bg-slate-50 p-3 rounded-xl text-sm font-black border-2 border-transparent focus:bg-white focus:border-indigo-100 outline-none transition-all"
                      />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[8px] text-slate-400 font-black uppercase ml-1">TÀI KHOẢN</label>
                      <input 
                        type="text" 
                        inputMode="numeric"
                        value={settings.initialBank.toLocaleString('vi-VN')} 
                        onChange={e => handleAmountInput(e.target.value, 'initialBank')} 
                        className="w-full bg-slate-50 p-3 rounded-xl text-sm font-black border-2 border-transparent focus:bg-white focus:border-indigo-100 outline-none transition-all"
                      />
                    </div>
                    <div className="col-span-2 space-y-1">
                      <label className="text-[8px] text-slate-400 font-black uppercase ml-1 text-center block">HẠN MỨC / NGÀY</label>
                      <input 
                        type="text" 
                        inputMode="numeric"
                        value={settings.dailyCost.toLocaleString('vi-VN')} 
                        onChange={e => handleAmountInput(e.target.value, 'dailyCost')} 
                        className="w-full bg-indigo-50/50 p-4 rounded-2xl text-xl font-black text-indigo-600 text-center border-2 border-indigo-50 focus:bg-white focus:border-indigo-100 outline-none transition-all"
                      />
                    </div>
                  </div>
               </div>
               <Dashboard stats={stats} transactions={transactions} settings={settings} user={user} onLogout={handleLogout} />
            </>
          )}

          {activeTab === 'transactions' && (
            <div className="space-y-4">
              <TransactionForm 
                onAdd={(t) => setTransactions([{...t, id: Date.now().toString(), userId: user.username}, ...transactions])} 
                editingTransaction={editingTransaction}
                onUpdate={(updated) => { setTransactions(transactions.map(t => t.id === updated.id ? updated : t)); setEditingTransaction(null); }}
                onCancelEdit={() => setEditingTransaction(null)}
              />
              <TransactionList 
                transactions={transactions} 
                settings={settings}
                onDelete={(id) => { if (window.confirm('Xác nhận xóa giao dịch?')) setTransactions(transactions.filter(t => t.id !== id)); }}
                onEdit={(t) => { setEditingTransaction(t); document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' }); }}
                onUpdateStates={handleUpdateTransactionStates}
              />
            </div>
          )}

          {activeTab === 'admin' && user.role === UserRole.ADMIN && (
            <AdminPanel onClose={() => setActiveTab('dashboard')} />
          )}
        </div>
      </main>

      <nav className="flex-none bg-white/80 backdrop-blur-3xl border-t border-slate-100 flex justify-around items-center px-4 pb-4 h-20 z-50">
        {[
          { id: 'dashboard', icon: 'fa-th-large', label: 'TỔNG QUAN' },
          { id: 'transactions', icon: 'fa-server', label: 'GIAO DỊCH' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex flex-col items-center gap-1 transition-all duration-300 ${activeTab === tab.id ? 'text-indigo-600 scale-105' : 'text-slate-400'}`}
          >
            <div className={`w-10 h-8 flex items-center justify-center rounded-xl ${activeTab === tab.id ? 'bg-indigo-50' : ''}`}>
               <i className={`fas ${tab.icon} text-base`}></i>
            </div>
            <span className="text-[7px] font-black uppercase tracking-[0.1em]">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

