import React, { useState, useEffect } from 'react';
import { Transaction, TransactionType, PaymentSource } from '../types';

interface Props {
  onAdd: (t: Omit<Transaction, 'id' | 'userId'>) => void;
  editingTransaction?: Transaction | null;
  onUpdate?: (t: Transaction) => void;
  onCancelEdit?: () => void;
}

const TransactionForm: React.FC<Props> = ({ onAdd, editingTransaction, onUpdate, onCancelEdit }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [content, setContent] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [source, setSource] = useState<PaymentSource>(PaymentSource.CASH);
  const [displayAmount, setDisplayAmount] = useState('');
  const [isExcluded, setIsExcluded] = useState(false);
  const [isFromSavings, setIsFromSavings] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDate(editingTransaction.date);
      setContent(editingTransaction.content);
      setType(editingTransaction.type);
      setSource(editingTransaction.source);
      setDisplayAmount(editingTransaction.amount.toLocaleString('vi-VN'));
      setIsExcluded(!!editingTransaction.isExcluded);
      setIsFromSavings(!!editingTransaction.isFromSavings);
    } else {
      resetForm();
    }
  }, [editingTransaction]);

  const resetForm = () => {
    setDate(new Date().toISOString().split('T')[0]);
    setContent('');
    setType(TransactionType.EXPENSE);
    setSource(PaymentSource.CASH);
    setDisplayAmount('');
    setIsExcluded(false);
    setIsFromSavings(false);
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/\D/g, '');
    setDisplayAmount(rawValue ? Number(rawValue).toLocaleString('vi-VN') : '');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = Number(displayAmount.replace(/\D/g, ''));
    if (!content || numericAmount <= 0) return alert("Vui lòng nhập đầy đủ thông tin!");

    const data = {
      date, content, type, source, 
      amount: numericAmount, 
      isExcluded: type === TransactionType.EXPENSE ? isExcluded : false,
      isFromSavings: type === TransactionType.EXPENSE ? isFromSavings : false
    };

    if (editingTransaction && onUpdate) onUpdate({ ...editingTransaction, ...data });
    else onAdd(data);
    resetForm();
  };

  return (
    <div className={`p-5 rounded-[32px] shadow-xl border transition-all duration-500 ${editingTransaction ? 'bg-amber-50 border-amber-200' : 'bg-white border-slate-100'}`}>
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-base font-black text-slate-800 flex items-center gap-2">
          <div className={`w-8 h-8 rounded-xl flex items-center justify-center text-white ${editingTransaction ? 'bg-amber-500' : 'bg-indigo-600'}`}>
             <i className={`fas ${editingTransaction ? 'fa-pen-nib' : 'fa-plus'} text-[10px]`}></i>
          </div>
          {editingTransaction ? 'CẬP NHẬT' : 'MỚI'}
        </h3>
        {editingTransaction && (
           <button onClick={onCancelEdit} className="text-[8px] font-black text-slate-400 uppercase tracking-widest hover:text-rose-500">Hủy</button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-2 gap-3">
          <div className="space-y-1">
             <label className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">Ngày</label>
             <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-50 p-3 rounded-xl text-xs font-bold border-none outline-none focus:ring-1 focus:ring-indigo-500" />
          </div>
          <div className="space-y-1">
             <label className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">Nội dung</label>
             <input type="text" value={content} onChange={e => setContent(e.target.value)} placeholder="..." className="w-full bg-slate-50 p-3 rounded-xl text-xs font-bold border-none outline-none focus:ring-1 focus:ring-indigo-500" />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div className="bg-slate-100 p-1 rounded-xl flex gap-0.5">
            {[TransactionType.EXPENSE, TransactionType.INCOME].map(t => (
              <button key={t} type="button" onClick={() => setType(t)} className={`flex-1 py-2 text-[8px] font-black rounded-lg transition-all ${type === t ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400'}`}>{t.toUpperCase()}</button>
            ))}
          </div>
          <div className="bg-slate-100 p-1 rounded-xl flex gap-0.5">
            {[PaymentSource.CASH, PaymentSource.BANK].map(s => (
              <button key={s} type="button" onClick={() => setSource(s)} className={`flex-1 py-2 text-[8px] font-black rounded-lg transition-all ${source === s ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400'}`}>{s.split(' ')[0].toUpperCase()}</button>
            ))}
          </div>
        </div>

        {type === TransactionType.EXPENSE && (
          <div className="flex gap-2">
            <button 
              type="button" 
              onClick={() => { setIsExcluded(!isExcluded); if(!isExcluded) setIsFromSavings(false); }}
              className={`flex-1 p-3 rounded-xl border-2 text-[8px] font-black transition-all flex flex-col items-center gap-1 ${isExcluded ? 'bg-amber-500 text-white border-amber-600 shadow-lg shadow-amber-200' : 'bg-slate-50 text-slate-400 border-transparent hover:border-slate-200'}`}
            >
              <i className="fas fa-tag text-[10px]"></i> ĐẶC BIỆT
            </button>
            <button 
              type="button" 
              onClick={() => { setIsFromSavings(!isFromSavings); if(!isFromSavings) setIsExcluded(false); }}
              className={`flex-1 p-3 rounded-xl border-2 text-[8px] font-black transition-all flex flex-col items-center gap-1 ${isFromSavings ? 'bg-blue-600 text-white border-blue-700 shadow-lg shadow-blue-200' : 'bg-slate-50 text-slate-400 border-transparent hover:border-slate-200'}`}
            >
              <i className="fas fa-droplet text-[10px]"></i> TÍCH LŨY
            </button>
          </div>
        )}

        <div className="relative group">
           <label className="absolute left-1/2 -top-2 -translate-x-1/2 bg-white px-2 text-[8px] font-black text-slate-400 uppercase tracking-[0.2em]">SỐ TIỀN</label>
           <input type="text" inputMode="numeric" value={displayAmount} onChange={handleAmountChange} placeholder="0đ" className={`w-full text-2xl font-black text-center py-5 bg-slate-50 rounded-2xl border-2 border-transparent outline-none focus:bg-white focus:border-indigo-100 transition-all ${type === TransactionType.INCOME ? 'text-emerald-500' : 'text-rose-500'}`} />
        </div>

        <button type="submit" className={`w-full py-3.5 rounded-2xl font-black text-white shadow-xl active:scale-95 transition-all flex items-center justify-center gap-2 text-xs uppercase tracking-widest ${editingTransaction ? 'bg-amber-500 shadow-amber-200' : 'bg-indigo-600 shadow-indigo-200'}`}>
          <i className={`fas ${editingTransaction ? 'fa-save' : 'fa-check-circle'} text-[10px]`}></i>
          {editingTransaction ? 'LƯU' : 'XÁC NHẬN'}
        </button>
      </form>
    </div>
  );
};

export default TransactionForm;

