          </div>
          <h1 className="text-2xl font-black text-white tracking-tighter">CASH<span className="text-[#6366f1]">FLOW</span></h1>
          <p className="text-slate-500 text-[8px] font-black uppercase tracking-[0.2em] mt-1">Hệ thống quản lý 2.0</p>
        </div>

        <div className="bg-[#1e293b]/50 backdrop-blur-xl border border-white/5 p-6 rounded-[32px] shadow-2xl">
          <div className="flex bg-[#0f172a]/50 p-1 rounded-2xl mb-6">
            <button 
              onClick={() => setIsLogin(true)}
              className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${isLogin ? 'bg-[#6366f1] text-white shadow-lg' : 'text-slate-500'}`}
            >
              Đăng nhập
            </button>
            <button 
              onClick={() => setIsLogin(false)}
              className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${!isLogin ? 'bg-[#6366f1] text-white shadow-lg' : 'text-slate-500'}`}
