                  <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-[#0f172a]/50 border border-white/5 rounded-xl pl-10 pr-4 py-3 text-white text-xs font-bold outline-none focus:border-[#6366f1] transition-all" placeholder="Tên của bạn..." />
