import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Transaction, TransactionType, PaymentSource, Settings, FinancialStats, User, UserRole } from './types';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Auth from './components/Auth';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('cashflow_current_user');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [settings, setSettings] = useState<Settings>({ userId: '', initialCash: 0, initialBank: 0, dailyCost: 0 });
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'admin'>('dashboard');
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  useEffect(() => {
    if (user) {
      const savedSettings = localStorage.getItem(`cashflow_settings_${user.username}`);
      const savedTrans = localStorage.getItem(`cashflow_transactions_${user.username}`);
      setSettings(savedSettings ? JSON.parse(savedSettings) : { userId: user.username, initialCash: 0, initialBank: 0, dailyCost: 0 });
      setTransactions(savedTrans ? JSON.parse(savedTrans) : []);
      localStorage.setItem('cashflow_current_user', JSON.stringify(user));
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`cashflow_settings_${user.username}`, JSON.stringify(settings));
      localStorage.setItem(`cashflow_transactions_${user.username}`, JSON.stringify(transactions));
    }
  }, [settings, transactions, user]);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;
    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE && !t.isExcluded && !t.isFromSavings)
      .reduce((sum, t) => sum + t.amount, 0);

    let cumulativeSaving = 0;
    if (settings.dailyCost > 0) {
      const firstDateStr = transactions.length > 0 ? transactions.reduce((min, t) => t.date < min ? t.date : min, todayStr) : todayStr;
      const start = new Date(firstDateStr);
      const end = new Date(todayStr);
      const diffDays = Math.max(1, Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1);
      const normalExpenses = transactions.filter(t => t.type === TransactionType.EXPENSE && !t.isExcluded && !t.isFromSavings).reduce((s, t) => s + t.amount, 0);
      const spentFromSavings = transactions.filter(t => t.type === TransactionType.EXPENSE && t.isFromSavings).reduce((s, t) => s + t.amount, 0);
      cumulativeSaving = (diffDays * settings.dailyCost) - normalExpenses - spentFromSavings;
    }

    return {
      currentCash, currentBank, total, survivalDays: settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense, cumulativeSaving
    };
  }, [transactions, settings]);

  const handleLogout = useCallback(() => {
    if (window.confirm("Đăng xuất khỏi hệ thống?")) {
      localStorage.removeItem('cashflow_current_user');
      setUser(null);
    }
  }, []);

  if (!user) return <Auth onLogin={setUser} />;

  return (
    <div className="h-screen flex flex-col bg-[#0f172a] text-white font-sans overflow-hidden">
      <header className="flex-none bg-[#1e293b]/50 backdrop-blur-xl border-b border-white/5 px-4 h-14 flex items-center justify-between z-50">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-[#6366f1] rounded-xl flex items-center justify-center shadow-lg">
            <i className="fas fa-layer-group text-white text-[10px]"></i>
          </div>
          <div>
            <h1 className="text-sm font-black tracking-tighter">CASH<span className="text-[#6366f1]">FLOW</span></h1>
            <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest">Master Mini v2</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          {user.role === UserRole.ADMIN && (
            <button onClick={() => setActiveTab('admin')} className={`w-8 h-8 rounded-xl flex items-center justify-center ${activeTab === 'admin' ? 'bg-[#6366f1]' : 'bg-[#1e293b]'}`}>
              <i className="fas fa-cog text-[10px]"></i>
            </button>
          )}
          <button onClick={handleLogout} className="w-8 h-8 bg-[#1e293b] rounded-xl flex items-center justify-center text-rose-400 border border-white/5"><i className="fas fa-power-off text-[10px]"></i></button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 custom-scrollbar">
        <div className="max-w-[320px] mx-auto space-y-4 pb-24">
          {activeTab === 'dashboard' && (
            <>
               <div className="bg-[#1e293b]/50 border border-white/5 p-5 rounded-[28px] shadow-xl animate-in fade-in slide-in-from-top-4">
                  <p className="text-[8px] font-black text-slate-500 uppercase tracking-[0.2em] mb-4">THIẾT LẬP DÒNG TIỀN</p>
                  <div className="grid grid-cols-2 gap-3 mb-4">
                    <div className="space-y-1">
                      <label className="text-[7px] text-slate-500 font-black uppercase">TIỀN MẶT</label>
                      <input type="text" inputMode="numeric" value={settings.initialCash.toLocaleString('vi-VN')} onChange={e => setSettings(p => ({...p, initialCash: Number(e.target.value.replace(/\D/g, ''))}))} className="w-full bg-[#0f172a]/50 border border-white/5 p-3 rounded-xl text-xs font-black outline-none focus:border-[#6366f1]" />
                    </div>
                    <div className="space-y-1">
                      <label className="text-[7px] text-slate-500 font-black uppercase">TÀI KHOẢN</label>
                      <input type="text" inputMode="numeric" value={settings.initialBank.toLocaleString('vi-VN')} onChange={e => setSettings(p => ({...p, initialBank: Number(e.target.value.replace(/\D/g, ''))}))} className="w-full bg-[#0f172a]/50 border border-white/5 p-3 rounded-xl text-xs font-black outline-none focus:border-[#6366f1]" />
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[7px] text-slate-500 font-black uppercase text-center block">HẠN MỨC CHI TIÊU / NGÀY</label>
                    <input type="text" inputMode="numeric" value={settings.dailyCost.toLocaleString('vi-VN')} onChange={e => setSettings(p => ({...p, dailyCost: Number(e.target.value.replace(/\D/g, ''))}))} className="w-full bg-indigo-500/10 border border-[#6366f1]/20 p-4 rounded-2xl text-xl font-black text-[#6366f1] text-center outline-none" />
                  </div>
               </div>
               <Dashboard stats={stats} transactions={transactions} settings={settings} user={user} onLogout={handleLogout} />
            </>
          )}

          {activeTab === 'transactions' && (
            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4">
              <TransactionForm onAdd={t => setTransactions([{...t, id: Date.now().toString(), userId: user.username}, ...transactions])} editingTransaction={editingTransaction} onUpdate={updated => { setTransactions(transactions.map(t => t.id === updated.id ? updated : t)); setEditingTransaction(null); }} onCancelEdit={() => setEditingTransaction(null)} />
              <TransactionList transactions={transactions} settings={settings} onDelete={id => { if (window.confirm('Xóa giao dịch này?')) setTransactions(transactions.filter(t => t.id !== id)); }} onEdit={t => { setEditingTransaction(t); document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' }); }} onUpdateStates={(id, updates) => setTransactions(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t))} />
            </div>
          )}

          {activeTab === 'admin' && user.role === UserRole.ADMIN && (
            <AdminPanel onClose={() => setActiveTab('dashboard')} />
          )}
        </div>
      </main>

      <nav className="flex-none bg-[#1e293b]/80 backdrop-blur-3xl border-t border-white/5 flex justify-around items-center px-4 pb-4 h-20 z-50">
        {[
          { id: 'dashboard', icon: 'fa-th-large', label: 'TỔNG QUAN' },
          { id: 'transactions', icon: 'fa-server', label: 'GIAO DỊCH' }
        ].map(tab => (
          <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeTab === tab.id ? 'text-[#6366f1] scale-105' : 'text-slate-500'}`}>
            <div className={`w-10 h-8 flex items-center justify-center rounded-xl ${activeTab === tab.id ? 'bg-[#6366f1]/10' : ''}`}>
               <i className={`fas ${tab.icon} text-sm`}></i>
            </div>
            <span className="text-[7px] font-black uppercase tracking-widest">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
