      <div className="grid grid-cols-2 gap-3">
        <div className="bg-[#1e293b]/50 border border-white/5 p-4 rounded-3xl">
          <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest mb-1">Tiền mặt</p>
          <p className="text-base font-black tracking-tight">{formatCurrency(stats.currentCash)}</p>
        </div>
        <div className="bg-[#1e293b]/50 border border-white/5 p-4 rounded-3xl">
          <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest mb-1">Tài khoản</p>
          <p className="text-base font-black tracking-tight">{formatCurrency(stats.currentBank)}</p>
        </div>
        <div className="col-span-2 bg-[#111827] border border-white/5 p-5 rounded-[32px] shadow-inner">
           <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest">TÀI SẢN RÒNG</p>
           <h3 className="text-3xl font-black text-white tracking-tighter my-2">{formatCurrency(stats.total)}</h3>
