import React, { useMemo } from 'react';
import { 
  ComposedChart, Area, Bar, XAxis, YAxis, CartesianGrid, Tooltip, 
  ResponsiveContainer, Line, PieChart, Pie, Cell, BarChart, Legend 
} from 'recharts';
import { FinancialStats, Transaction, TransactionType, Settings, User } from '../types';

interface Props {
  stats: FinancialStats;
  transactions: Transaction[];
  settings: Settings;
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ stats, transactions, settings }) => {
  const chartData = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      days.push(d.toISOString().split('T')[0]);
    }
    return days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const expense = dayTransactions.filter(t => t.type === TransactionType.EXPENSE && !t.isExcluded && !t.isFromSavings).reduce((sum, t) => sum + t.amount, 0);
      const income = dayTransactions.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
      const totalExpense = dayTransactions.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

      return { 
        date: date.split('-').slice(1).reverse().join('/'), 
        expense, 
        income,
        totalExpense,
        target: settings.dailyCost 
      };
    });
  }, [transactions, settings.dailyCost]);

  const assetData = [
    { name: 'Tiền mặt', value: stats.currentCash },
    { name: 'Tài khoản', value: stats.currentBank }
  ].filter(d => d.value > 0);

  const PIE_COLORS = ['#6366f1', '#10b981'];

  const formatCurrency = (val: number) => val.toLocaleString('vi-VN') + 'đ';
  const targetSavingsPool = settings.dailyCost * 30 || 1000000;
  const fillPercentage = Math.min(100, Math.max(0, (stats.cumulativeSaving / targetSavingsPool) * 100));

  return (
    <div className="space-y-4 animate-in fade-in duration-700">
      {/* TANK MINI DARK */}
      <div className="relative group overflow-hidden rounded-[32px] border border-white/5 shadow-2xl bg-[#1e293b]">
        <div className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-[#6366f1] via-indigo-500 to-indigo-400 transition-all duration-[2000ms]" style={{ height: `${fillPercentage}%`, opacity: 0.8 }}>
          <div className="absolute top-0 left-0 w-[200%] h-8 -translate-y-[80%] opacity-30 animate-wave-slow fill-[#6366f1]"><svg viewBox="0 0 100 20" preserveAspectRatio="none" className="w-full h-full"><path d="M0 10 C 20 15 40 5 60 10 C 80 15 100 5 120 10 V 20 H 0 Z" /></svg></div>
        </div>
        <div className="relative z-10 p-5 flex flex-col justify-between min-h-[140px]">
          <div className="flex justify-between items-start">
            <p className="text-[8px] font-black uppercase tracking-[0.2em] text-slate-400 mix-blend-difference">QUỸ TÍCH LŨY</p>
            <div className="px-2 py-1 rounded-lg bg-black/30 border border-white/10 text-[9px] font-black">{fillPercentage.toFixed(1)}%</div>
          </div>
          <div>
            <h2 className="text-2xl font-black tracking-tighter mix-blend-difference">{formatCurrency(stats.cumulativeSaving)}</h2>
            <p className="text-[7px] font-bold text-slate-400 mt-1 uppercase tracking-widest">Tiết kiệm là nền tảng tự do</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        {/* Biểu đồ tròn cơ cấu tài sản */}
        <div className="bg-[#1e293b]/50 border border-white/5 p-4 rounded-3xl flex flex-col items-center">
          <p className="text-[7px] font-black text-slate-500 uppercase tracking-widest mb-2 w-full">Cơ cấu tài sản</p>
          <div className="h-24 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
