import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, TransactionType, PaymentSource } from '../types';

interface Props {
  onAdd: (t: Omit<Transaction, 'id' | 'userId'>) => void;
  editingTransaction?: Transaction | null;
  onUpdate?: (t: Transaction) => void;
  onCancelEdit?: () => void;
}

const PREDEFINED_KEYWORDS = [
  'ăn sáng', 'ăn trưa', 'ăn tối', 'đi chợ', 'đi BHX', 
  'tài liệu', 'đi chơi', 'mỳ Cay', 'thanh toán', 
  'mua trà sữa', 'nạp game', 'đổ xăng', 'phí gửi xe 1k'
];

const TransactionForm: React.FC<Props> = ({ onAdd, editingTransaction, onUpdate, onCancelEdit }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [content, setContent] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [source, setSource] = useState<PaymentSource>(PaymentSource.CASH);
  const [displayAmount, setDisplayAmount] = useState('');
  const [isExcluded, setIsExcluded] = useState(false);
  const [isFromSavings, setIsFromSavings] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDate(editingTransaction.date);
      setContent(editingTransaction.content);
      setType(editingTransaction.type);
      setSource(editingTransaction.source);
      setDisplayAmount(editingTransaction.amount.toLocaleString('vi-VN'));
      setIsExcluded(!!editingTransaction.isExcluded);
      setIsFromSavings(!!editingTransaction.isFromSavings);
    } else { resetForm(); }
  }, [editingTransaction]);

  const resetForm = () => {
    setDate(new Date().toISOString().split('T')[0]);
    setContent('');
    setType(TransactionType.EXPENSE);
    setSource(PaymentSource.CASH);
    setDisplayAmount('');
    setIsExcluded(false);
    setIsFromSavings(false);
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/\D/g, '');
    setDisplayAmount(rawValue ? Number(rawValue).toLocaleString('vi-VN') : '');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = Number(displayAmount.replace(/\D/g, ''));
    if (!content || numericAmount <= 0) return alert("Vui lòng nhập đầy đủ!");
    const data = { date, content, type, source, amount: numericAmount, isExcluded: type === TransactionType.EXPENSE ? isExcluded : false, isFromSavings: type === TransactionType.EXPENSE ? isFromSavings : false };
    if (editingTransaction && onUpdate) onUpdate({ ...editingTransaction, ...data });
    else onAdd(data);
    resetForm();
  };

  const suggestions = useMemo(() => {
    if (!content) return [];
    const lowerContent = content.toLowerCase();
    return PREDEFINED_KEYWORDS.filter(kw => 
      kw.toLowerCase().includes(lowerContent) || 
      kw.toLowerCase().split(' ').some(word => word.startsWith(lowerContent))
    );
  }, [content]);

  const handleSuggestionClick = (val: string) => {
    setContent(val);
    setShowSuggestions(false);
  };

  return (
    <div className={`p-5 rounded-[32px] border border-white/5 transition-all ${editingTransaction ? 'bg-amber-500/10' : 'bg-[#1e293b]'}`}>
      <div className="flex justify-between items-center mb-5">
        <h3 className="text-xs font-black flex items-center gap-2">
          <div className={`w-6 h-6 rounded-lg flex items-center justify-center text-white ${editingTransaction ? 'bg-amber-500' : 'bg-[#6366f1]'}`}><i className={`fas ${editingTransaction ? 'fa-edit' : 'fa-plus'} text-[8px]`}></i></div>
          {editingTransaction ? 'SỬA' : 'MỚI'}
        </h3>
        {editingTransaction && <button onClick={onCancelEdit} className="text-[8px] font-black text-rose-400">HỦY</button>}
      </div>

      <form onSubmit={handleSubmit} className="space-y-3">
        <div className="grid grid-cols-2 gap-3">
          <div className="relative">
            <i className="fas fa-calendar absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 text-[9px]"></i>
            <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-[#0f172a]/50 border border-white/5 rounded-xl pl-9 pr-3 py-2.5 text-[10px] font-bold outline-none focus:border-[#6366f1]" />
          </div>

          <div className="relative group">
            <i className="fas fa-pen absolute left-3 top-1/2 -translate-y-1/2 text-slate-500 text-[9px]"></i>
            <input 
              type="text" 
              value={content} 
              onFocus={() => setShowSuggestions(true)}
              onChange={e => { setContent(e.target.value); setShowSuggestions(true); }} 
              placeholder="Nội dung..." 
              className="w-full bg-[#0f172a]/50 border border-white/5 rounded-xl pl-9 pr-3 py-2.5 text-[10px] font-bold outline-none focus:border-[#6366f1]" 
            />
            {/* Đề xuất nhập nhanh */}
            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute left-0 bottom-full mb-2 w-full flex gap-1 overflow-x-auto pb-2 custom-scrollbar scroll-smooth no-scrollbar">
                {suggestions.map((s, i) => (
                  <button 
                    key={i} 
                    type="button" 
                    onClick={() => handleSuggestionClick(s)}
                    className="flex-none bg-[#6366f1] text-white text-[8px] font-black px-3 py-1.5 rounded-full shadow-lg border border-indigo-400/30 whitespace-nowrap active:scale-95 transition-transform"
                  >
                    {s}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div className="bg-[#0f172a] p-1 rounded-xl flex gap-1">{[TransactionType.EXPENSE, TransactionType.INCOME].map(t => (
            <button key={t} type="button" onClick={() => setType(t)} className={`flex-1 py-2 text-[8px] font-black rounded-lg ${type === t ? 'bg-[#6366f1] text-white shadow-lg' : 'text-slate-500'}`}>{t.toUpperCase()}</button>
          ))}</div>
          <div className="bg-[#0f172a] p-1 rounded-xl flex gap-1">{[PaymentSource.CASH, PaymentSource.BANK].map(s => (
            <button key={s} type="button" onClick={() => setSource(s)} className={`flex-1 py-2 text-[8px] font-black rounded-lg ${source === s ? 'bg-[#6366f1] text-white shadow-lg' : 'text-slate-500'}`}>{s.split(' ')[0].toUpperCase()}</button>
          ))}</div>
        </div>

        {type === TransactionType.EXPENSE && (
          <div className="flex gap-2">
            <button type="button" onClick={() => { setIsExcluded(!isExcluded); if(!isExcluded) setIsFromSavings(false); }} className={`flex-1 p-2 rounded-xl border text-[8px] font-black transition-all ${isExcluded ? 'bg-amber-500 text-white border-amber-600' : 'bg-[#0f172a] text-slate-500 border-white/5'}`}>ĐẶC BIỆT</button>
            <button type="button" onClick={() => { setIsFromSavings(!isFromSavings); if(!isFromSavings) setIsExcluded(false); }} className={`flex-1 p-2 rounded-xl border text-[8px] font-black transition-all ${isFromSavings ? 'bg-[#6366f1] text-white border-[#6366f1]' : 'bg-[#0f172a] text-slate-500 border-white/5'}`}>TÍCH LŨY</button>
          </div>
        )}

        <div className="relative py-2">
           <input type="text" inputMode="numeric" value={displayAmount} onChange={handleAmountChange} placeholder="0đ" className={`w-full text-2xl font-black text-center py-4 bg-[#0f172a] rounded-2xl border border-white/5 outline-none focus:border-[#6366f1] ${type === TransactionType.INCOME ? 'text-emerald-400' : 'text-rose-400'}`} />
        </div>
        <button type="submit" className={`w-full py-4 rounded-2xl font-black text-white text-[10px] uppercase tracking-widest active:scale-95 transition-all ${editingTransaction ? 'bg-amber-500' : 'bg-[#6366f1]'}`}>{editingTransaction ? 'LƯU' : 'XÁC NHẬN'}</button>
      </form>
    </div>
  );
};

export default TransactionForm;

import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';

interface Props {
  onLogin: (user: User) => void;
}

const Auth: React.FC<Props> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    const users = JSON.parse(localStorage.getItem('cashflow_users') || '[]');
    if (!users.find((u: any) => u.username === 'admin')) {
      users.push({
        username: 'admin',
        password: '123',
        name: 'Quản trị viên',
        role: UserRole.ADMIN,
        createdAt: new Date().toISOString()
      });
      localStorage.setItem('cashflow_users', JSON.stringify(users));
    }
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const cleanUser = username.trim().toLowerCase();
    if (!cleanUser || !password || (!isLogin && !name)) {
      setError('Vui lòng nhập đầy đủ!');
      return;
    }
    const users: User[] = JSON.parse(localStorage.getItem('cashflow_users') || '[]');
    if (isLogin) {
      const user = users.find(u => u.username === cleanUser && u.password === password);
      if (user) onLogin(user);
      else setError('Sai tài khoản hoặc mật khẩu!');
    } else {
      if (users.find(u => u.username === cleanUser)) {
        setError('Tài khoản đã tồn tại!');
        return;
      }
      const newUser: User = { 
        username: cleanUser, 
        password, 
        name, 
        role: UserRole.USER,
        createdAt: new Date().toISOString()
      };
      users.push(newUser);
      localStorage.setItem('cashflow_users', JSON.stringify(users));
      onLogin(newUser);
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] flex items-center justify-center p-4 overflow-hidden">
      {/* Container chính thu nhỏ 60% */}
      <div className="w-full max-w-[240px] animate-in fade-in zoom-in duration-500 scale-100">
        <div className="text-center mb-5">
          <div className="w-12 h-12 bg-indigo-600 rounded-[18px] flex items-center justify-center shadow-2xl shadow-indigo-100 mx-auto mb-3 rotate-3">
            <i className="fas fa-vault text-white text-lg"></i>
          </div>
          <h1 className="text-lg font-black text-slate-900 tracking-tighter leading-none">CASH<span className="text-indigo-600">FLOW</span></h1>
          <p className="text-slate-400 text-[6px] font-black uppercase tracking-[0.3em] mt-1">MASTER MINI 60%</p>
        </div>

        <div className="bg-white border border-slate-100 p-5 rounded-[28px] shadow-2xl relative">
          <div className="flex bg-slate-50 p-1 rounded-xl mb-5 border border-slate-100">
            <button 
              onClick={() => setIsLogin(true)}
              className={`flex-1 py-1.5 text-[7px] font-black uppercase tracking-widest rounded-lg transition-all ${isLogin ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400'}`}
            >
              Đăng nhập
            </button>
            <button 
              onClick={() => setIsLogin(false)}
              className={`flex-1 py-1.5 text-[7px] font-black uppercase tracking-widest rounded-lg transition-all ${!isLogin ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400'}`}
            >
              Đăng ký
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-3.5">
            {!isLogin && (
              <div className="space-y-1">
                <label className="text-[7px] font-black text-slate-400 uppercase tracking-widest ml-1">Họ tên</label>
                <div className="relative">
                  <i className="fas fa-user absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-[8px]"></i>
                  <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg pl-8 pr-3 py-2 text-slate-900 text-[10px] font-bold outline-none focus:border-indigo-400 focus:bg-white transition-all" placeholder="Tên..." />
                </div>
              </div>
            )}

            <div className="space-y-1">
              <label className="text-[7px] font-black text-slate-400 uppercase tracking-widest ml-1">Tài khoản</label>
              <div className="relative">
                <i className="fas fa-at absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-[8px]"></i>
                <input type="text" value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg pl-8 pr-3 py-2 text-slate-900 text-[10px] font-mono outline-none focus:border-indigo-400 focus:bg-white transition-all" placeholder="user..." />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[7px] font-black text-slate-400 uppercase tracking-widest ml-1">Mật khẩu</label>
              <div className="relative">
                <i className="fas fa-lock absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-[8px]"></i>
                <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-lg pl-8 pr-3 py-2 text-slate-900 text-[10px] font-bold outline-none focus:border-indigo-400 focus:bg-white transition-all" placeholder="••••" />
              </div>
            </div>

            {error && (
              <p className="text-rose-500 text-[7px] font-black text-center uppercase py-0.5">{error}</p>
            )}

            <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-black py-3 rounded-xl shadow-xl shadow-indigo-100 active:scale-95 transition-all uppercase tracking-[0.2em] text-[9px] mt-2">
              {isLogin ? 'Đăng nhập' : 'Hoàn tất'}
            </button>
          </form>
        </div>

        <p className="text-center mt-5 text-slate-400 text-[6px] font-black uppercase tracking-[0.3em] opacity-80 italic">Privacy & Security 2025</p>
      </div>
    </div>
  );
};

