const PREDEFINED_KEYWORDS = [
  'ăn sáng', 'ăn trưa', 'ăn tối', 'đi chợ', 'đi BHX', 
  'tài liệu', 'đi chơi', 'mỳ Cay', 'thanh toán', 
  'mua trà sữa', 'nạp game', 'đổ xăng', 'phí gửi xe 1k'
];

const TransactionForm: React.FC<Props> = ({ onAdd, editingTransaction, onUpdate, onCancelEdit }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [content, setContent] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [source, setSource] = useState<PaymentSource>(PaymentSource.CASH);
  const [displayAmount, setDisplayAmount] = useState('');
  const [isExcluded, setIsExcluded] = useState(false);
  const [isFromSavings, setIsFromSavings] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDate(editingTransaction.date);
      setContent(editingTransaction.content);
      setType(editingTransaction.type);
      setSource(editingTransaction.source);
      setDisplayAmount(editingTransaction.amount.toLocaleString('vi-VN'));
      setIsExcluded(!!editingTransaction.isExcluded);
      setIsFromSavings(!!editingTransaction.isFromSavings);
    } else { resetForm(); }
  }, [editingTransaction]);

  const resetForm = () => {
    setDate(new Date().toISOString().split('T')[0]);
    setContent('');
    setType(TransactionType.EXPENSE);
    setSource(PaymentSource.CASH);
    setDisplayAmount('');
    setIsExcluded(false);
    setIsFromSavings(false);
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/\D/g, '');
    setDisplayAmount(rawValue ? Number(rawValue).toLocaleString('vi-VN') : '');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = Number(displayAmount.replace(/\D/g, ''));
    if (!content || numericAmount <= 0) return alert("Vui lòng nhập đầy đủ!");
    const data = { date, content, type, source, amount: numericAmount, isExcluded: type === TransactionType.EXPENSE ? isExcluded : false, isFromSavings: type === TransactionType.EXPENSE ? isFromSavings : false };
    if (editingTransaction && onUpdate) onUpdate({ ...editingTransaction, ...data });
    else onAdd(data);
    resetForm();
  };

  // Logic tiên đoán: Chỉ dự đoán kí tự đầu tiên hoặc kí tự <phím cách>kí tự đầu
  const suggestions = useMemo(() => {
    if (!content) return [];
    const lowerInput = content.toLowerCase();

    return PREDEFINED_KEYWORDS.filter(kw => {
      const kwLower = kw.toLowerCase();
      // Khớp từ đầu hoặc khớp sau dấu cách (đầu mỗi từ trong cụm từ)
      return kwLower.startsWith(lowerInput) || kwLower.includes(" " + lowerInput);
    });
  }, [content]);

  const handleSuggestionClick = (val: string) => {
    setContent(val);
    setShowSuggestions(false);
  };

  return (
    <div className={`p-5 rounded-[32px] border border-slate-100 transition-all shadow-sm ${editingTransaction ? 'bg-amber-50 border-amber-200' : 'bg-white'}`}>
      <div className="flex justify-between items-center mb-5">
        <h3 className="text-xs font-black flex items-center gap-2">
          <div className={`w-6 h-6 rounded-lg flex items-center justify-center text-white ${editingTransaction ? 'bg-amber-500' : 'bg-indigo-600 shadow-lg shadow-indigo-100'}`}><i className={`fas ${editingTransaction ? 'fa-edit' : 'fa-plus'} text-[8px]`}></i></div>
          <span className="text-slate-700 tracking-tight uppercase">{editingTransaction ? 'CẬP NHẬT' : 'GIAO DỊCH MỚI'}</span>
        </h3>
        {editingTransaction && <button onClick={onCancelEdit} className="text-[8px] font-black text-rose-500 uppercase tracking-widest hover:underline">Hủy sửa</button>}
      </div>

      <form onSubmit={handleSubmit} className="space-y-3">
        <div className="grid grid-cols-2 gap-3">
          <div className="relative">
            <i className="fas fa-calendar absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-[9px]"></i>
            <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-9 pr-3 py-2.5 text-[10px] font-bold text-slate-700 outline-none focus:border-indigo-400 focus:bg-white transition-all" />
          </div>

          <div className="relative group">
            <i className="fas fa-pen absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-[9px]"></i>
            <input 
              type="text" 
              value={content} 
              onFocus={() => setShowSuggestions(true)}
              onChange={e => { setContent(e.target.value); setShowSuggestions(true); }} 
              placeholder="Nội dung..." 
              className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-9 pr-3 py-2.5 text-[10px] font-bold text-slate-700 outline-none focus:border-indigo-400 focus:bg-white transition-all" 
            />

            {/* Thanh đề xuất nhập nhanh */}
            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute left-0 bottom-full mb-2 w-full flex gap-1 overflow-x-auto pb-2 custom-scrollbar scroll-smooth no-scrollbar z-30">
                {suggestions.map((s, i) => (
                  <button 
                    key={i} 
                    type="button" 
                    onClick={() => handleSuggestionClick(s)}
                    className="flex-none bg-white text-indigo-600 border border-indigo-100 text-[8px] font-black px-3 py-1.5 rounded-full shadow-lg whitespace-nowrap active:scale-95 transition-transform hover:bg-indigo-600 hover:text-white"
                  >
                    {s}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div className="bg-slate-50 p-1 rounded-xl flex gap-1 border border-slate-100">{[TransactionType.EXPENSE, TransactionType.INCOME].map(t => (
            <button key={t} type="button" onClick={() => setType(t)} className={`flex-1 py-2 text-[8px] font-black rounded-lg transition-all ${type === t ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}>{t.toUpperCase()}</button>
          ))}</div>
          <div className="bg-slate-50 p-1 rounded-xl flex gap-1 border border-slate-100">{[PaymentSource.CASH, PaymentSource.BANK].map(s => (
            <button key={s} type="button" onClick={() => setSource(s)} className={`flex-1 py-2 text-[8px] font-black rounded-lg transition-all ${source === s ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}>{s.split(' ')[0].toUpperCase()}</button>
          ))}</div>
        </div>

        {type === TransactionType.EXPENSE && (
          <div className="flex gap-2">
            <button type="button" onClick={() => { setIsExcluded(!isExcluded); if(!isExcluded) setIsFromSavings(false); }} className={`flex-1 p-2 rounded-xl border text-[8px] font-black transition-all ${isExcluded ? 'bg-amber-500 text-white border-amber-600' : 'bg-slate-50 text-slate-400 border-slate-200 hover:bg-slate-100'}`}>ĐẶC BIỆT</button>
            <button type="button" onClick={() => { setIsFromSavings(!isFromSavings); if(!isFromSavings) setIsExcluded(false); }} className={`flex-1 p-2 rounded-xl border text-[8px] font-black transition-all ${isFromSavings ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-slate-50 text-slate-400 border-slate-200 hover:bg-slate-100'}`}>TÍCH LŨY</button>
          </div>
        )}

        <div className="relative py-2">
           <input type="text" inputMode="numeric" value={displayAmount} onChange={handleAmountChange} placeholder="0đ" className={`w-full text-2xl font-black text-center py-4 bg-slate-50 rounded-2xl border border-slate-200 outline-none focus:border-indigo-400 focus:bg-white transition-all ${type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'}`} />
        </div>
        <button type="submit" className={`w-full py-4 rounded-2xl font-black text-white text-[10px] uppercase tracking-widest active:scale-95 transition-all shadow-xl shadow-indigo-100 ${editingTransaction ? 'bg-amber-500 hover:bg-amber-600' : 'bg-indigo-600 hover:bg-indigo-700'}`}>
          {editingTransaction ? 'LƯU THAY ĐỔI' : 'XÁC NHẬN GIAO DỊCH'}
        </button>
      </form>
    </div>
  );
};

export default TransactionForm;

import React, { useMemo } from 'react';
import { 
  ComposedChart, Area, Bar, XAxis, YAxis, CartesianGrid, Tooltip, 
  ResponsiveContainer, Line, PieChart, Pie, Cell, BarChart, Legend 
} from 'recharts';
import { FinancialStats, Transaction, TransactionType, Settings, User } from '../types';

interface Props {
  stats: FinancialStats;
  transactions: Transaction[];
  settings: Settings;
  user: User;
  onLogout: () => void;
}

const Dashboard: React.FC<Props> = ({ stats, transactions, settings }) => {
  const chartData = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      days.push(d.toISOString().split('T')[0]);
    }
    return days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const expense = dayTransactions.filter(t => t.type === TransactionType.EXPENSE && !t.isExcluded && !t.isFromSavings).reduce((sum, t) => sum + t.amount, 0);
      const income = dayTransactions.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
      const totalExpense = dayTransactions.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);

      return { 
        date: date.split('-').slice(1).reverse().join('/'), 
        expense, 
        income,
        totalExpense,
        target: settings.dailyCost 
      };
    });
  }, [transactions, settings.dailyCost]);

  const assetData = [
    { name: 'Tiền mặt', value: stats.currentCash },
    { name: 'Tài khoản', value: stats.currentBank }
  ].filter(d => d.value > 0);

  const PIE_COLORS = ['#4f46e5', '#10b981'];

  const formatCurrency = (val: number) => val.toLocaleString('vi-VN') + 'đ';
  const targetSavingsPool = settings.dailyCost * 30 || 1000000;
  const fillPercentage = Math.min(100, Math.max(0, (stats.cumulativeSaving / targetSavingsPool) * 100));

  return (
    <div className="space-y-4 animate-in fade-in duration-700">
      {/* TANK LIGHT MODE */}
      <div className="relative group overflow-hidden rounded-[32px] border border-slate-100 shadow-lg bg-white">
        <div className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-indigo-500/10 via-indigo-400/5 to-transparent transition-all duration-[2000ms]" style={{ height: `${fillPercentage}%` }}>
          <div className="absolute top-0 left-0 w-[200%] h-8 -translate-y-[80%] opacity-20 animate-wave-slow fill-indigo-500"><svg viewBox="0 0 100 20" preserveAspectRatio="none" className="w-full h-full"><path d="M0 10 C 20 15 40 5 60 10 C 80 15 100 5 120 10 V 20 H 0 Z" /></svg></div>
        </div>
        <div className="relative z-10 p-5 flex flex-col justify-between min-h-[140px]">
          <div className="flex justify-between items-start">
            <p className="text-[8px] font-black uppercase tracking-[0.2em] text-slate-400">QUỸ TÍCH LŨY</p>
            <div className="px-2 py-1 rounded-lg bg-indigo-50 border border-indigo-100 text-indigo-600 text-[9px] font-black">{fillPercentage.toFixed(1)}%</div>
          </div>
          <div>
            <h2 className="text-2xl font-black tracking-tighter text-slate-800">{formatCurrency(stats.cumulativeSaving)}</h2>
            <p className="text-[7px] font-bold text-slate-400 mt-1 uppercase tracking-widest">Tài sản tích lũy cho tương lai</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3">
        {/* Biểu đồ cơ cấu tài sản */}
        <div className="bg-white border border-slate-100 p-4 rounded-3xl flex flex-col items-center shadow-sm">
          <p className="text-[7px] font-black text-slate-400 uppercase tracking-widest mb-2 w-full">Cơ cấu tài sản</p>
          <div className="h-24 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={assetData} innerRadius={20} outerRadius={35} paddingAngle={5} dataKey="value">
                  {assetData.map((_, index) => (
                    <Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} stroke="none" />
                  ))}
                </Pie>
                <Tooltip contentStyle={{ backgroundColor: '#fff', border: '1px solid #f1f5f9', borderRadius: '8px', fontSize: '8px' }} formatter={(v: any) => formatCurrency(v)} />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex gap-2 mt-1">
             <div className="flex items-center gap-1"><div className="w-1.5 h-1.5 rounded-full bg-indigo-600"></div><span className="text-[6px] text-slate-400 font-bold uppercase">Tiền mặt</span></div>
             <div className="flex items-center gap-1"><div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div><span className="text-[6px] text-slate-400 font-bold uppercase">Bank</span></div>
          </div>
        </div>

        <div className="bg-white border border-slate-100 p-4 rounded-3xl flex flex-col justify-center shadow-sm">
          <p className="text-[7px] font-black text-slate-400 uppercase tracking-widest mb-1">Dư nợ hiện tại</p>
          <p className="text-sm font-black text-slate-800 tracking-tighter">{formatCurrency(stats.total)}</p>
          <div className="w-full bg-slate-50 h-1.5 rounded-full mt-2 overflow-hidden border border-slate-100">
             <div className="h-full bg-indigo-500 shadow-sm" style={{ width: `${(stats.currentCash/stats.total)*100 || 0}%` }}></div>
          </div>
          <p className="text-[6px] text-slate-400 mt-1 uppercase font-black tracking-tight">Cash: {Math.round((stats.currentCash/stats.total)*100 || 0)}%</p>
        </div>

        <div className="col-span-2 bg-slate-900 border border-slate-800 p-5 rounded-[32px] shadow-2xl relative overflow-hidden">
           <div className="absolute -top-4 -right-4 w-16 h-16 bg-white/5 rounded-full blur-xl"></div>
           <p className="text-[7px] font-black text-slate-400 uppercase tracking-widest">TÀI SẢN RÒNG</p>
           <h3 className="text-3xl font-black text-white tracking-tighter my-2">{formatCurrency(stats.total)}</h3>
           <div className="flex justify-between border-t border-white/5 pt-4">
              <div><p className="text-[7px] font-black text-slate-400 uppercase">Dự kiến sống</p><p className="text-sm font-black text-indigo-400">{stats.survivalDays} <span className="text-[7px] font-bold">Ngày</span></p></div>
              <div className="text-right"><p className="text-[7px] font-black text-slate-400 uppercase">Chi hôm nay</p><p className="text-sm font-black text-rose-400">{formatCurrency(stats.todayExpense)}</p></div>
           </div>
        </div>
      </div>

      {/* Biểu đồ xu hướng */}
      <div className="bg-white border border-slate-100 p-4 rounded-3xl shadow-sm">
        <h3 className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-4">XU HƯỚNG THU / CHI</h3>
        <div className="h-32 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData}>
              <XAxis dataKey="date" hide />
              <YAxis hide />
              <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ backgroundColor: '#fff', border: '1px solid #f1f5f9', borderRadius: '12px', fontSize: '9px' }} />
              <Bar dataKey="income" fill="#10b981" radius={[2, 2, 0, 0]} barSize={6} />
              <Bar dataKey="totalExpense" fill="#f43f5e" radius={[2, 2, 0, 0]} barSize={6} />
            </BarChart>
          </ResponsiveContainer>
        </div>
        <div className="flex justify-center gap-4 mt-2">
           <div className="flex items-center gap-1"><div className="w-2 h-2 rounded bg-emerald-500"></div><span className="text-[7px] text-slate-400 font-black uppercase">Thu</span></div>
           <div className="flex items-center gap-1"><div className="w-2 h-2 rounded bg-rose-500"></div><span className="text-[7px] text-slate-400 font-black uppercase">Chi</span></div>
        </div>
      </div>

      <div className="bg-white border border-slate-100 p-4 rounded-3xl shadow-sm">
        <h3 className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-4">KỶ LUẬT CHI TIÊU HÀNG NGÀY</h3>
        <div className="h-32 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart data={chartData}>
              <XAxis dataKey="date" hide />
              <YAxis hide />
              <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ backgroundColor: '#fff', border: '1px solid #f1f5f9', borderRadius: '12px', fontSize: '9px' }} />
              <Area type="monotone" dataKey="target" fill="rgba(79, 70, 229, 0.05)" stroke="none" />
              <Bar dataKey="expense" fill="#f43f5e" radius={[3, 3, 0, 0]} barSize={8} />
              <Line type="monotone" dataKey="target" stroke="#4f46e5" strokeWidth={1} strokeDasharray="3 3" dot={false} />
            </ComposedChart>
          </ResponsiveContainer>
        </div>
      </div>
      <style>{`@keyframes wave { 0% { transform: translateX(0); } 100% { transform: translateX(-50%); } } .animate-wave-slow { animation: wave 8s linear infinite; }`}</style>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { User, UserRole } from '../types';

interface Props {
  onLogin: (user: User) => void;
}

const Auth: React.FC<Props> = ({ onLogin }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    const users = JSON.parse(localStorage.getItem('cashflow_users') || '[]');
    if (!users.find((u: any) => u.username === 'admin')) {
      users.push({
        username: 'admin',
        password: '123',
        name: 'Quản trị viên',
        role: UserRole.ADMIN,
        createdAt: new Date().toISOString()
      });
      localStorage.setItem('cashflow_users', JSON.stringify(users));
    }
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const cleanUser = username.trim().toLowerCase();
    if (!cleanUser || !password || (!isLogin && !name)) {
      setError('Vui lòng nhập đầy đủ!');
      return;
    }
    const users: User[] = JSON.parse(localStorage.getItem('cashflow_users') || '[]');
    if (isLogin) {
      const user = users.find(u => u.username === cleanUser && u.password === password);
      if (user) onLogin(user);
      else setError('Sai tài khoản hoặc mật khẩu!');
    } else {
      if (users.find(u => u.username === cleanUser)) {
        setError('Tài khoản đã tồn tại!');
        return;
      }
      const newUser: User = { 
        username: cleanUser, 
        password, 
        name, 
        role: UserRole.USER,
        createdAt: new Date().toISOString()
      };
      users.push(newUser);
      localStorage.setItem('cashflow_users', JSON.stringify(users));
      onLogin(newUser);
    }
  };

  return (
    <div className="min-h-screen bg-[#f1f5f9] flex items-center justify-center p-4">
      {/* UI 2.1: Lớp container chính với bóng đổ cực sâu */}
      <div className="w-full max-w-[240px] animate-in fade-in zoom-in duration-500">
        <div className="text-center mb-6">
          <div className="w-14 h-14 bg-indigo-600 rounded-[22px] flex items-center justify-center shadow-[0_20px_40px_-10px_rgba(79,70,229,0.4)] mx-auto mb-3 transform rotate-3 ring-4 ring-white">
            <i className="fas fa-vault text-white text-xl"></i>
          </div>
          <h1 className="text-xl font-black text-slate-900 tracking-tighter leading-none">CASH<span className="text-indigo-600">FLOW</span></h1>
          <p className="text-slate-400 text-[7px] font-black uppercase tracking-[0.4em] mt-1.5">Version 2.1 Depth</p>
        </div>

        <div className="bg-white border border-slate-100 p-5 rounded-[32px] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] ring-1 ring-black/5 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-indigo-500/20 to-transparent"></div>

          <div className="flex bg-slate-100/50 p-1.5 rounded-2xl mb-6 shadow-inner">
            <button 
              onClick={() => setIsLogin(true)}
              className={`flex-1 py-2 text-[8px] font-black uppercase tracking-widest rounded-xl transition-all ${isLogin ? 'bg-white text-indigo-600 shadow-md ring-1 ring-black/5' : 'text-slate-400'}`}
            >
              Đăng nhập
            </button>
            <button 
              onClick={() => setIsLogin(false)}
              className={`flex-1 py-2 text-[8px] font-black uppercase tracking-widest rounded-xl transition-all ${!isLogin ? 'bg-white text-indigo-600 shadow-md ring-1 ring-black/5' : 'text-slate-400'}`}
            >
              Đăng ký
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            {!isLogin && (
              <div className="space-y-1">
                <label className="text-[7px] font-black text-slate-400 uppercase tracking-widest ml-1">Họ tên</label>
                <input type="text" value={name} onChange={e => setName(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-slate-900 text-[10px] font-bold outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all" placeholder="Tên..." />
              </div>
            )}

            <div className="space-y-1">
              <label className="text-[7px] font-black text-slate-400 uppercase tracking-widest ml-1">Tài khoản</label>
              <input type="text" value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-slate-900 text-[10px] font-mono outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all" placeholder="user..." />
            </div>

            <div className="space-y-1">
              <label className="text-[7px] font-black text-slate-400 uppercase tracking-widest ml-1">Mật khẩu</label>
              <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-slate-900 text-[10px] font-bold outline-none focus:ring-2 focus:ring-indigo-100 focus:border-indigo-400 transition-all" placeholder="••••" />
            </div>

            {error && (
              <p className="text-rose-500 text-[7px] font-black text-center uppercase py-1">{error}</p>
            )}

            <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-black py-3.5 rounded-2xl shadow-[0_15px_30px_-5px_rgba(79,70,229,0.3)] active:scale-95 transition-all uppercase tracking-[0.2em] text-[10px] mt-2 border-b-4 border-indigo-800">
              {isLogin ? 'Vào hệ thống' : 'Tạo tài khoản'}
