const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    // Loại bỏ các mục trùng lặp dựa trên name (ví dụ: target xuất hiện ở cả Area và Line)
    const uniquePayload = payload.reduce((acc: any[], current: any) => {
      const exists = acc.find(item => item.name === current.name);
      if (!exists) {
        return acc.concat([current]);
      }
      return acc;
    }, []);

    return (
      <div className="bg-white/95 backdrop-blur-xl p-4 border border-slate-100 rounded-[28px] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.12)] ring-1 ring-black/5 animate-in fade-in zoom-in duration-200 min-w-[140px]">
