import React, { useMemo } from 'react';
import { 
  ComposedChart, Area, Bar, XAxis, YAxis, Tooltip, 
  ResponsiveContainer, Line, PieChart, Pie, Cell, BarChart 
} from 'recharts';
import { FinancialStats, Transaction, TransactionType, Settings, User } from '../types';

interface Props {
  stats: FinancialStats;
  transactions: Transaction[];
  settings: Settings;
  user: User;
  onLogout: () => void;
}

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    // Lọc bỏ trùng lặp và xác định đúng thứ tự hiển thị
    const uniqueItems: any[] = [];
    const seenNames = new Set();

    // Ưu tiên hiển thị Hạn mức (Target) rồi mới đến Thực chi (Expense)
    payload.forEach((item: any) => {
      // Chỉ lấy 1 lần cho mỗi loại name (đặc biệt là 'target' dùng ở cả Area và Line)
      if (!seenNames.has(item.name)) {
        seenNames.add(item.name);
        uniqueItems.push(item);
      }
    });

    return (
      <div className="bg-white/95 backdrop-blur-xl p-4 border border-slate-100 rounded-[28px] shadow-[0_20px_40px_-10px_rgba(0,0,0,0.1)] ring-1 ring-black/5 animate-in fade-in zoom-in duration-200 min-w-[150px]">
        <p className="text-[12px] font-black text-slate-900 mb-2 border-b border-slate-50 pb-2 uppercase tracking-[0.1em]">{label}</p>
        <div className="space-y-3">
          {uniqueItems.map((entry: any, index: number) => {
            const isTarget = entry.name === 'target';
            const isExpense = entry.name === 'expense';
            const isIncome = entry.name === 'income';

            return (
              <div key={index} className="flex items-center justify-between gap-4">
                <div className="flex items-center gap-2.5">
                  <div 
                    className={`w-2 h-2 rounded-full shadow-sm`} 
                    style={{ backgroundColor: isTarget ? '#4f46e5' : isExpense ? '#f43f5e' : entry.color || entry.fill }}
                  ></div>
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest whitespace-nowrap">
                    {isTarget ? 'HẠN MỨC' : isExpense ? 'THỰC CHI' : isIncome ? 'THU NHẬP' : 'TỔNG CHI'}
                  </span>
                </div>
                <span className="text-[10px] font-black text-slate-900">
                  {entry.value.toLocaleString('vi-VN')}đ
                </span>
              </div>
            );
          })}
        </div>
      </div>
    );
  }
  return null;
};

