const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    const uniqueItems: any[] = [];
    const seenNames = new Set();
    payload.forEach((item: any) => {
      if (!seenNames.has(item.name)) {
        seenNames.add(item.name);
        uniqueItems.push(item);
      }
    });

    return (
      <div className="bg-white/95 backdrop-blur-md p-4 border border-slate-100 rounded-[24px] shadow-xl ring-1 ring-black/5 animate-in fade-in zoom-in duration-200 min-w-[160px]">
        <p className="text-[13px] font-black text-slate-900 mb-2 border-b border-slate-50 pb-1 uppercase tracking-widest">{label}</p>
        <div className="space-y-2">
          {uniqueItems.map((entry: any, index: number) => {
            const isTarget = entry.name === 'target';
            const isExpense = entry.name === 'expense';
            return (
              <div key={index} className="flex items-center justify-between gap-4">
                <div className="flex items-center gap-2">
                  <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: isTarget ? '#4f46e5' : isExpense ? '#f43f5e' : entry.color || entry.fill }}></div>
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                    {isTarget ? 'HẠN MỨC' : isExpense ? 'CHI' : 'GIÁ TRỊ'}
                  </span>
                </div>
                <span className="text-[12px] font-black text-slate-900">
                  {entry.value.toLocaleString('vi-VN')}đ
                </span>
              </div>
            );
          })}
        </div>
      </div>
    );
  }
  return null;
};

const Dashboard: React.FC<Props> = ({ stats, transactions, settings }) => {
  const chartData = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
