import React, { useState, useEffect, useMemo } from 'react';
import { Transaction, TransactionType, PaymentSource } from '../types';

interface Props {
  onAdd: (t: Omit<Transaction, 'id' | 'userId'>) => void;
  editingTransaction?: Transaction | null;
  onUpdate?: (t: Transaction) => void;
  onCancelEdit?: () => void;
}

const PREDEFINED_KEYWORDS = [
  'ăn sáng', 'ăn trưa', 'ăn tối', 'đi chợ', 'đi BHX', 
  'tài liệu', 'đi chơi', 'ăn mỳ Cay', 'thanh toán', 
  'mua trà sữa', 'nạp game', 'đổ xăng', 'gửi xe 1k'
];

const TransactionForm: React.FC<Props> = ({ onAdd, editingTransaction, onUpdate, onCancelEdit }) => {
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [content, setContent] = useState('');
  const [type, setType] = useState<TransactionType>(TransactionType.EXPENSE);
  const [source, setSource] = useState<PaymentSource>(PaymentSource.CASH);
  const [displayAmount, setDisplayAmount] = useState('');
  const [isExcluded, setIsExcluded] = useState(false);
  const [isFromSavings, setIsFromSavings] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);

  useEffect(() => {
    if (editingTransaction) {
      setDate(editingTransaction.date);
      setContent(editingTransaction.content);
      setType(editingTransaction.type);
      setSource(editingTransaction.source);
      setDisplayAmount(editingTransaction.amount.toLocaleString('vi-VN'));
      setIsExcluded(!!editingTransaction.isExcluded);
      setIsFromSavings(!!editingTransaction.isFromSavings);
    } else { resetForm(); }
  }, [editingTransaction]);

  const resetForm = () => {
    setDate(new Date().toISOString().split('T')[0]);
    setContent('');
    setType(TransactionType.EXPENSE);
    setSource(PaymentSource.CASH);
    setDisplayAmount('');
    setIsExcluded(false);
    setIsFromSavings(false);
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawValue = e.target.value.replace(/\D/g, '');
    setDisplayAmount(rawValue ? Number(rawValue).toLocaleString('vi-VN') : '');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = Number(displayAmount.replace(/\D/g, ''));
    if (!content || numericAmount <= 0) return alert("Vui lòng nhập đầy đủ!");
    const data = { date, content, type, source, amount: numericAmount, isExcluded: type === TransactionType.EXPENSE ? isExcluded : false, isFromSavings: type === TransactionType.EXPENSE ? isFromSavings : false };
    if (editingTransaction && onUpdate) onUpdate({ ...editingTransaction, ...data });
    else onAdd(data);
    resetForm();
  };

  const suggestions = useMemo(() => {
    if (!content) return [];
    const lowerInput = content.toLowerCase();
    return PREDEFINED_KEYWORDS.filter(kw => kw.toLowerCase().startsWith(lowerInput) || kw.toLowerCase().includes(" " + lowerInput));
  }, [content]);

  const handleSuggestionClick = (val: string) => {
    setContent(val);
    setShowSuggestions(false);
  };

  return (
    <div className={`p-6 rounded-[32px] border border-slate-100 transition-all shadow-sm ${editingTransaction ? 'bg-amber-50 border-amber-200' : 'bg-white'}`}>
      <div className="flex justify-between items-center mb-5 px-1">
        <h3 className="text-[13px] font-black flex items-center gap-3 text-slate-700 uppercase tracking-widest">
          <i className={`fas ${editingTransaction ? 'fa-edit text-amber-500' : 'fa-plus-circle text-indigo-600'}`}></i>
          {editingTransaction ? 'Sửa giao dịch' : 'Ghi nhận mới'}
        </h3>
        {editingTransaction && <button onClick={onCancelEdit} className="text-[10px] font-black text-rose-500 uppercase tracking-widest">Hủy</button>}
      </div>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-2 gap-4">
          <input type="date" value={date} onChange={e => setDate(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 text-[13px] font-black outline-none focus:bg-white" />
          <div className="relative">
            <input type="text" value={content} onFocus={() => setShowSuggestions(true)} onChange={e => { setContent(e.target.value); setShowSuggestions(true); }} placeholder="Nội dung..." className="w-full bg-slate-50 border border-slate-100 rounded-2xl p-4 text-[13px] font-black outline-none focus:bg-white" />
            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute left-0 top-full mt-3 w-full flex gap-2 overflow-x-auto pb-3 z-50 no-scrollbar">
                {suggestions.map((s, i) => (
                  <button key={i} type="button" onClick={() => handleSuggestionClick(s)} className="bg-indigo-600 text-white text-[10px] font-black px-4 py-2 rounded-xl whitespace-nowrap shadow-md">{s}</button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div className="bg-slate-50 p-1.5 rounded-2xl flex gap-1.5 border border-slate-100">
            {[TransactionType.EXPENSE, TransactionType.INCOME].map(t => (
              <button key={t} type="button" onClick={() => setType(t)} className={`flex-1 py-3 text-[10px] font-black rounded-xl transition-all ${type === t ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>{t.toUpperCase()}</button>
            ))}
          </div>
          <div className="bg-slate-50 p-1.5 rounded-2xl flex gap-1.5 border border-slate-100">
            {[PaymentSource.CASH, PaymentSource.BANK].map(s => (
              <button 
                key={s} 
                type="button" 
                onClick={() => setSource(s)} 
                className={`flex-1 py-3 text-[10px] font-black rounded-xl transition-all ${source === s ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}
              >
                {s === PaymentSource.CASH ? 'TIỀN' : 'ATM'}
              </button>
            ))}
          </div>
        </div>

        {type === TransactionType.EXPENSE && (
          <div className="grid grid-cols-2 gap-3">
            <button 
              type="button" 
              onClick={() => setIsExcluded(!isExcluded)}
              className={`flex items-center justify-center gap-3 py-3 rounded-2xl text-[10px] font-black transition-all border ${isExcluded ? 'bg-amber-100 border-amber-200 text-amber-700 shadow-inner' : 'bg-slate-50 border-slate-100 text-slate-400 opacity-60'}`}
            >
              <i className={`fas fa-star ${isExcluded ? 'text-[12px] text-amber-500' : 'text-[10px]'}`}></i>
              ĐẶC BIỆT
            </button>
            <button 
              type="button" 
              onClick={() => setIsFromSavings(!isFromSavings)}
              className={`flex items-center justify-center gap-3 py-3 rounded-2xl text-[10px] font-black transition-all border ${isFromSavings ? 'bg-indigo-100 border-indigo-200 text-indigo-700 shadow-inner' : 'bg-slate-50 border-slate-100 text-slate-400 opacity-60'}`}
            >
              <i className={`fas fa-tint ${isFromSavings ? 'text-[12px] text-indigo-500' : 'text-[10px]'}`}></i>
              TỪ TÍCH LŨY
            </button>
          </div>
        )}

        <input type="text" inputMode="numeric" value={displayAmount} onChange={handleAmountChange} placeholder="0đ" className={`w-full text-[31px] font-black text-center py-4 bg-slate-50 rounded-2xl border border-slate-100 outline-none focus:bg-white transition-all ${type === TransactionType.INCOME ? 'text-emerald-600' : 'text-rose-600'}`} />

        <button type="submit" className="w-full py-5 bg-indigo-600 text-white font-black rounded-[24px] text-[13px] uppercase tracking-[0.2em] shadow-lg active:scale-95 transition-all">
          {editingTransaction ? 'Lưu thay đổi' : 'Ghi nhận'}
        </button>
      </form>
    </div>
  );
};

export default TransactionForm;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Transaction, TransactionType, PaymentSource, Settings, FinancialStats, User, UserRole } from './types';
import Dashboard from './components/Dashboard';
import TransactionForm from './components/TransactionForm';
import TransactionList from './components/TransactionList';
import Auth from './components/Auth';
import AdminPanel from './components/AdminPanel';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(() => {
    try {
      const saved = localStorage.getItem('cashflow_current_user');
      return saved ? JSON.parse(saved) : null;
    } catch (e) {
      return null;
    }
  });

  const [settings, setSettings] = useState<Settings>({ userId: '', initialCash: 0, initialBank: 0, dailyCost: 0 });
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'transactions' | 'admin'>('dashboard');
  const [editingTransaction, setEditingTransaction] = useState<Transaction | null>(null);

  useEffect(() => {
    if (user) {
      const savedSettings = localStorage.getItem(`cashflow_settings_${user.username}`);
      const savedTrans = localStorage.getItem(`cashflow_transactions_${user.username}`);

      const loadedSettings = savedSettings ? JSON.parse(savedSettings) : { userId: user.username, initialCash: 0, initialBank: 0, dailyCost: 0 };
      setSettings(loadedSettings);
      setTransactions(savedTrans ? JSON.parse(savedTrans) : []);

      localStorage.setItem('cashflow_current_user', JSON.stringify(user));
    } else {
      setSettings({ userId: '', initialCash: 0, initialBank: 0, dailyCost: 0 });
      setTransactions([]);
      setActiveTab('dashboard');
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      localStorage.setItem(`cashflow_settings_${user.username}`, JSON.stringify(settings));
      localStorage.setItem(`cashflow_transactions_${user.username}`, JSON.stringify(transactions));
    }
  }, [settings, transactions, user]);

  const stats = useMemo((): FinancialStats => {
    const calc = (type: TransactionType, source: PaymentSource) => 
      transactions.filter(t => t.type === type && t.source === source).reduce((sum, t) => sum + t.amount, 0);

    const currentCash = settings.initialCash + calc(TransactionType.INCOME, PaymentSource.CASH) - calc(TransactionType.EXPENSE, PaymentSource.CASH);
    const currentBank = settings.initialBank + calc(TransactionType.INCOME, PaymentSource.BANK) - calc(TransactionType.EXPENSE, PaymentSource.BANK);
    const total = currentCash + currentBank;

    const todayStr = new Date().toISOString().split('T')[0];
    const todayExpense = transactions
      .filter(t => t.date === todayStr && t.type === TransactionType.EXPENSE && !t.isExcluded && !t.isFromSavings)
      .reduce((sum, t) => sum + t.amount, 0);

    let cumulativeSaving = 0;
    if (settings.dailyCost > 0) {
      const firstDateStr = transactions.length > 0 
        ? transactions.reduce((min, t) => t.date < min ? t.date : min, todayStr)
        : todayStr;
      const start = new Date(firstDateStr);
      const end = new Date(todayStr);
      const diffDays = Math.max(1, Math.floor((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24)) + 1);

      const normalExpenses = transactions
        .filter(t => t.type === TransactionType.EXPENSE && !t.isExcluded && !t.isFromSavings)
        .reduce((s, t) => s + t.amount, 0);

      const spentFromSavings = transactions
        .filter(t => t.type === TransactionType.EXPENSE && t.isFromSavings)
        .reduce((s, t) => s + t.amount, 0);

      cumulativeSaving = (diffDays * settings.dailyCost) - normalExpenses - spentFromSavings;
    }

    const survivalDays = settings.dailyCost > 0 ? Math.floor(total / settings.dailyCost) : 0;

    return {
      currentCash, currentBank, total, survivalDays,
      totalIncome: transactions.filter(t => t.type === TransactionType.INCOME).reduce((s, t) => s + t.amount, 0),
      totalExpense: transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((s, t) => s + t.amount, 0),
      todayExpense,
      cumulativeSaving
    };
  }, [transactions, settings]);

  const handleLogout = useCallback(() => {
    if (window.confirm("Thoát phiên làm việc an toàn?")) {
      localStorage.removeItem('cashflow_current_user');
      setUser(null);
    }
  }, []);

  const handleAmountInput = (value: string, key: keyof Settings) => {
    const numeric = Number(value.replace(/\D/g, ''));
    setSettings(prev => ({ ...prev, [key]: numeric }));
  };

  if (!user) return <Auth onLogin={setUser} />;

  return (
    <div className="h-screen flex flex-col bg-[#f8fafc] font-sans overflow-hidden">
      <header className="flex-none bg-white/80 backdrop-blur-2xl border-b border-slate-100 px-5 h-20 flex items-center justify-between z-50">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-100 rotate-3 ring-2 ring-white">
            <i className="fas fa-layer-group text-white text-[16px]"></i>
          </div>
          <div>
            <h1 className="text-[24px] font-black text-slate-800 tracking-tighter leading-none">CASH<span className="text-indigo-600">FLOW</span></h1>
            <p className="text-[12px] font-black text-slate-400 uppercase tracking-widest">v2.1 SuperSize</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          {user.role === UserRole.ADMIN && (
            <button 
              onClick={() => setActiveTab('admin')}
              className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${activeTab === 'admin' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-600 border border-slate-100'}`}
            >
              <i className="fas fa-cog text-[16px]"></i>
            </button>
          )}
          <button onClick={handleLogout} className="w-12 h-12 bg-slate-50 text-slate-400 rounded-2xl flex items-center justify-center border border-slate-100"><i className="fas fa-power-off text-[16px]"></i></button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-5 custom-scrollbar">
        <div className="max-w-sm mx-auto space-y-7 pb-28">
          {activeTab === 'dashboard' && (
            <>
               <div className="bg-white p-7 rounded-[40px] shadow-sm border border-slate-50 animate-in fade-in slide-in-from-top-2 duration-500">
                  <div className="flex justify-between items-center mb-6 px-1">
                    <p className="text-[13px] font-black text-slate-400 uppercase tracking-[0.2em]">THIẾT LẬP MỤC TIÊU</p>
                    <button onClick={() => setSettings(p => ({...p, initialCash:0, initialBank:0, dailyCost:0}))} className="text-[12px] font-black text-rose-500 uppercase tracking-widest">RESET</button>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-3">
                      <label className="text-[12px] text-slate-400 font-black uppercase tracking-widest ml-1">TIỀN MẶT</label>
                      <input 
                        type="text" 
                        inputMode="numeric"
                        value={settings.initialCash.toLocaleString('vi-VN')} 
                        onChange={e => handleAmountInput(e.target.value, 'initialCash')} 
                        className="w-full bg-slate-50 p-4 rounded-3xl text-[17px] font-black text-center border border-slate-100 outline-none focus:ring-4 focus:ring-indigo-50"
                      />
                    </div>
                    <div className="space-y-3">
                      <label className="text-[12px] text-slate-400 font-black uppercase tracking-widest ml-1">TÀI KHOẢN</label>
                      <input 
                        type="text" 
                        inputMode="numeric"
                        value={settings.initialBank.toLocaleString('vi-VN')} 
                        onChange={e => handleAmountInput(e.target.value, 'initialBank')} 
                        className="w-full bg-slate-50 p-4 rounded-3xl text-[17px] font-black text-center border border-slate-100 outline-none focus:ring-4 focus:ring-indigo-50"
                      />
                    </div>
                    <div className="col-span-2 mt-3 space-y-3">
                      <label className="text-[12px] text-slate-400 font-black uppercase tracking-widest text-center block">HẠN MỨC / NGÀY</label>
                      <input 
                        type="text" 
                        inputMode="numeric"
                        value={settings.dailyCost.toLocaleString('vi-VN')} 
                        onChange={e => handleAmountInput(e.target.value, 'dailyCost')} 
                        className="w-full bg-indigo-50/20 p-5 rounded-3xl text-[30px] font-black text-indigo-600 text-center border border-indigo-100 focus:bg-white outline-none transition-all shadow-sm"
                      />
                    </div>
                  </div>
               </div>

               <Dashboard stats={stats} transactions={transactions} settings={settings} user={user} onLogout={handleLogout} />
            </>
          )}

          {activeTab === 'transactions' && (
            <div className="space-y-7">
              <TransactionForm 
                onAdd={(t) => setTransactions([{...t, id: Date.now().toString(), userId: user.username}, ...transactions])} 
                editingTransaction={editingTransaction}
                onUpdate={(updated) => { setTransactions(transactions.map(t => t.id === updated.id ? updated : t)); setEditingTransaction(null); }}
                onCancelEdit={() => setEditingTransaction(null)}
              />
              <TransactionList 
                transactions={transactions} 
                settings={settings}
                onDelete={(id) => { if (window.confirm('Xác nhận xóa giao dịch?')) setTransactions(transactions.filter(t => t.id !== id)); }}
                onEdit={(t) => { setEditingTransaction(t); document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' }); }}
                onUpdateStates={(id, updates) => setTransactions(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t))}
              />
            </div>
          )}

          {activeTab === 'admin' && user.role === UserRole.ADMIN && (
            <AdminPanel onClose={() => setActiveTab('dashboard')} />
          )}
        </div>
      </main>

      <nav className="flex-none bg-white border-t border-slate-100 flex justify-around items-center h-24 z-50">
        {[
          { id: 'dashboard', icon: 'fa-th-large', label: 'TỔNG QUAN' },
          { id: 'transactions', icon: 'fa-server', label: 'GIAO DỊCH' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex flex-col items-center transition-all ${activeTab === tab.id ? 'text-indigo-600' : 'text-slate-300'}`}
          >
            <div className={`w-16 h-14 flex items-center justify-center rounded-2xl transition-all ${activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl' : 'bg-slate-50'}`}>
               <i className={`fas ${tab.icon} text-[20px]`}></i>
            </div>
            <span className="text-[12px] font-black mt-3 uppercase tracking-widest">{tab.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { 
  ComposedChart, Area, Bar, XAxis, YAxis, Tooltip, 
  ResponsiveContainer, Line, PieChart, Pie, Cell, BarChart 
} from 'recharts';
import { FinancialStats, Transaction, TransactionType, Settings, User } from '../types';

interface Props {
  stats: FinancialStats;
  transactions: Transaction[];
  settings: Settings;
  user: User;
  onLogout: () => void;
}

const CustomTooltip = ({ active, payload, label }: any) => {
  if (active && payload && payload.length) {
    const uniqueItems: any[] = [];
    const seenNames = new Set();
    payload.forEach((item: any) => {
      if (!seenNames.has(item.name)) {
        seenNames.add(item.name);
        uniqueItems.push(item);
      }
    });

    return (
      <div className="bg-white/95 backdrop-blur-md p-5 border border-slate-100 rounded-[28px] shadow-2xl ring-1 ring-black/5 animate-in fade-in zoom-in duration-200 min-w-[200px]">
        <p className="text-[17px] font-black text-slate-900 mb-3 border-b border-slate-50 pb-2 uppercase tracking-widest">{label}</p>
        <div className="space-y-3">
          {uniqueItems.map((entry: any, index: number) => {
            const isTarget = entry.name === 'target';
            const isExpense = entry.name === 'expense';
            return (
              <div key={index} className="flex items-center justify-between gap-5">
                <div className="flex items-center gap-3">
                  <div className="w-3.5 h-3.5 rounded-full" style={{ backgroundColor: isTarget ? '#4f46e5' : isExpense ? '#f43f5e' : entry.color || entry.fill }}></div>
                  <span className="text-[13px] font-black text-slate-400 uppercase tracking-widest">
                    {isTarget ? 'HẠN MỨC' : isExpense ? 'CHI' : 'GIÁ TRỊ'}
                  </span>
                </div>
                <span className="text-[16px] font-black text-slate-900">
                  {entry.value.toLocaleString('vi-VN')}đ
                </span>
              </div>
            );
          })}
        </div>
      </div>
    );
  }
  return null;
};

const Dashboard: React.FC<Props> = ({ stats, transactions, settings }) => {
  const chartData = useMemo(() => {
    const days = [];
    for (let i = 6; i >= 0; i--) {
      const d = new Date();
      d.setDate(d.getDate() - i);
      days.push(d.toISOString().split('T')[0]);
    }
    return days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const expense = dayTransactions.filter(t => t.type === TransactionType.EXPENSE && !t.isExcluded && !t.isFromSavings).reduce((sum, t) => sum + t.amount, 0);
      const income = dayTransactions.filter(t => t.type === TransactionType.INCOME).reduce((sum, t) => sum + t.amount, 0);
      const totalExpense = dayTransactions.filter(t => t.type === TransactionType.EXPENSE).reduce((sum, t) => sum + t.amount, 0);
      return { 
        date: date.split('-').slice(1).reverse().join('/'), 
        expense, income, totalExpense, target: settings.dailyCost 
      };
    });
  }, [transactions, settings.dailyCost]);

  const assetData = [{ name: 'Mặt', value: stats.currentCash }, { name: 'Bank', value: stats.currentBank }].filter(d => d.value > 0);
  const PIE_COLORS = ['#6366f1', '#10b981'];
  const formatCurrency = (val: number) => val.toLocaleString('vi-VN') + 'đ';

  const targetSavingsPool = settings.dailyCost * 30 || 1000000;
  const fillPercentage = Math.min(100, Math.max(0, (stats.cumulativeSaving / targetSavingsPool) * 100));

  return (
    <div className="space-y-7 animate-in fade-in duration-700">
      {/* TANK SECTION */}
      <div className="relative overflow-hidden rounded-[40px] border border-white shadow-xl bg-white ring-1 ring-slate-100">
        <div 
          className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-indigo-500/25 to-indigo-500/45 transition-all duration-[2500ms] ease-out" 
          style={{ height: `${fillPercentage}%` }}
        >
