                <div className="flex justify-between items-start gap-3">
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <span className="text-[10px] font-black text-slate-400 font-mono tracking-tighter">{new Date(t.date).toLocaleDateString('vi-VN', {day:'2-digit', month:'2-digit'})}</span>
                      <h4 className="font-bold text-slate-700 text-[13px] tracking-tight truncate max-w-[160px]">{t.content}</h4>
                    </div>
                    <div className="flex items-center gap-2 mt-2">
